#![cfg_attr(windows, windows_subsystem = "windows")]

//! NEOTH GUI wizard — R-1 Phase 3.
//!
//! Multi-screen flow:
//!   welcome → license → identity → provider → autonomy → channels
//!     → (keys, when needed) → done
//!
//! On finish we write two files:
//!   - `~/.neoth/freedom.yaml` — operator id, provider kind, autonomy
//!     level, channels-enabled list. No secrets in this file.
//!   - `~/.neoth/credentials.yaml` (only when the operator entered at
//!     least one secret) — mode 0600 on unix, ACL-restricted on Windows.
//!     Mirrors the secrets-split landed by `config/credentials.rs`.

use std::io::{Read, Write};
use std::path::{Path, PathBuf};

use anyhow::{Context, Result};
use serde::{Deserialize, Serialize};
use tracing::info;
use tracing_subscriber::EnvFilter;

// FIX 1 — serialize all freedom.yaml writers so concurrent GUI toggles cannot
// interleave their read-modify-write cycles and lose an update.
static FREEDOM_WRITE_LOCK: std::sync::Mutex<()> = std::sync::Mutex::new(());

// A status probe started before a mutation must never overwrite the newer
// receipt-backed state. Every accepted Apply attempt advances this revision;
// asynchronous status callbacks only publish while their captured revision is
// still current.
static CLUSTER_UI_REVISION: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);

// Buddy and Mesh render one shared membership authority snapshot. Older probes
// and pre-mutation reads must never replace a newer receipt-verified readback.
static MEMBERSHIP_UI_REVISION: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);

// OMI status reads are asynchronous. A read started before an accepted
// mutation must never publish its now-stale snapshot after the mutation's
// receipt-backed readback. Mutations also share one in-process guard below so
// privacy actions cannot race each other.
static OMI_UI_REVISION: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);

// Editable OMI fields are a draft, not the verified runtime snapshot. User
// edits advance this revision so a slow startup/status read can update health
// metadata without overwriting a newer local draft.
static OMI_DRAFT_REVISION: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
static OMI_STATUS_OPERATION_ACTIVE: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

// Dream cron reads and mutations share one serialized GUI operation edge. A
// revision prevents a late startup read from replacing a newer receipt-backed
// mutation result.
static DREAM_CRON_UI_REVISION: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
static DREAM_CRON_OPERATION_ACTIVE: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

// GOLD-R3-13: only one explicit-root code-map recall may own the compact card
// and Buddy state at a time. The Slint button is also disabled while active;
// this guard covers callback re-entry and tests driving the callback directly.
static CODE_MAP_RECALL_ACTIVE: std::sync::atomic::AtomicBool =
    std::sync::atomic::AtomicBool::new(false);

// Multiple background-job refreshes can overlap (manual refresh, route entry,
// and the automatic refresh after a successful spawn). Only the newest request
// may publish its list or clear the loading state.
static BG_JOBS_UI_REVISION: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);

// Startup and rapid chat completions may overlap history reloads. Only the
// newest canonical raw-turn snapshot may replace the sidebar model.
static CHAT_HISTORY_REFRESH_REVISION: std::sync::atomic::AtomicU64 =
    std::sync::atomic::AtomicU64::new(0);

// Consent appears on both Chat and Overview. Separate revisions prevent an
// older asynchronous probe from repainting either surface after a verified
// mutation (or its fail-closed invalidation) has advanced the UI state.
static CHAT_CONSENT_UI_REVISION: std::sync::atomic::AtomicU64 =
    std::sync::atomic::AtomicU64::new(0);
static OVERVIEW_CONSENT_UI_REVISION: std::sync::atomic::AtomicU64 =
    std::sync::atomic::AtomicU64::new(0);
// D2 overview cost probes intentionally permit one replacement worker while a
// prior bounded refresh is still winding down.  Its output is presentation
// state, so the newest operator refresh must win even if an older worker
// completes last.
static USAGE_OVERVIEW_UI_REVISION: std::sync::atomic::AtomicU64 =
    std::sync::atomic::AtomicU64::new(0);

const CHAT_STREAM_STDOUT_MAX_BYTES: usize = 32 * 1024 * 1024;

struct PendingGuiChatConsent {
    request_id: chat_stream_phase::ChatStreamRequestId,
    surface: chat_stream_phase::ChatStreamSurface,
    body: String,
    explicit_skill_id: Option<String>,
    /// Captured before any async preflight so changing a visible toggle while
    /// consent is open cannot change the already-authorized child launch.
    incognito: bool,
    preflight: gui_action::VerifiedConsentChatPreflight,
}

type RequestBoundChatConsentToken = (
    chat_stream_phase::ChatStreamRequestId,
    zeroize::Zeroizing<Vec<u8>>,
);

const CHAT_SILENCE_WATCHDOG: std::time::Duration = std::time::Duration::from_secs(120);

/// A per-turn supervision state. This is deliberately separate from the
/// provider lifecycle: a UI timer may diagnose silence, but it may never
/// manufacture provider progress or advance a stream phase.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ChatWatchdogState {
    Monitoring,
    Diagnostic,
}

/// Owns exactly one request's meaningful-progress deadline.
///
/// Once a turn enters `Diagnostic`, later bytes/callbacks cannot hide the
/// diagnostic or turn it into a new request. A fresh retry receives a fresh
/// `ChatStreamRequestId` through the normal send path.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct ChatTurnWatchdog {
    request_id: chat_stream_phase::ChatStreamRequestId,
    last_meaningful_progress_at: std::time::Instant,
    state: ChatWatchdogState,
}

impl ChatTurnWatchdog {
    fn arm(request_id: ChatStreamRequestId, now: std::time::Instant) -> Self {
        Self {
            request_id,
            last_meaningful_progress_at: now,
            state: ChatWatchdogState::Monitoring,
        }
    }

    /// A successful byte read is not progress. Call this only after the
    /// stream parser observed visible text growth or a new authenticated
    /// provider/control event for the same request.
    fn rearm_for_meaningful_progress(
        &mut self,
        request_id: ChatStreamRequestId,
        now: std::time::Instant,
    ) {
        if self.request_id == request_id && self.state == ChatWatchdogState::Monitoring {
            self.last_meaningful_progress_at = now;
        }
    }

    /// Returns true exactly once, at the request-bound diagnostic transition.
    fn enter_diagnostic_if_silent(
        &mut self,
        request_id: ChatStreamRequestId,
        now: std::time::Instant,
    ) -> bool {
        if self.request_id != request_id || self.state != ChatWatchdogState::Monitoring {
            return false;
        }
        // `Instant` is deliberately monotonic. A synthetic/invalid earlier
        // observation cannot make a request look silent, and wall-clock
        // adjustments never participate in the watchdog decision.
        let Some(silence) = now.checked_duration_since(self.last_meaningful_progress_at) else {
            return false;
        };
        if silence < CHAT_SILENCE_WATCHDOG {
            return false;
        }
        self.state = ChatWatchdogState::Diagnostic;
        true
    }

    fn is_diagnostic_for(self, request_id: ChatStreamRequestId) -> bool {
        self.request_id == request_id && self.state == ChatWatchdogState::Diagnostic
    }
}

/// A watchdog retry is a one-shot hand-off, bound to the diagnosed request.
/// It is consumed only when that request settles, so retry never revives a
/// cancelled worker or lets its late callback affect the next request.
struct PendingChatWatchdogRetry {
    request_id: ChatStreamRequestId,
    surface: ChatStreamSurface,
    body: zeroize::Zeroizing<String>,
    /// Frozen with the request body so a watchdog retry cannot consult a
    /// privacy widget which the operator may have changed meanwhile.
    incognito: bool,
}

/// The retryable input belongs to the same request as the watchdog. The
/// legacy recall buffer is intentionally not an authority for retry because
/// it is presentation state rather than a request-bound capability.
struct RequestBoundChatRetryInput {
    request_id: ChatStreamRequestId,
    surface: ChatStreamSurface,
    body: zeroize::Zeroizing<String>,
    /// The request's dispatch privacy mode, not presentation state.
    incognito: bool,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct RequestBoundChatWatchdogRetryStop {
    request_id: ChatStreamRequestId,
    surface: ChatStreamSurface,
}

/// Deduplicates the two authenticated terminal boundaries retained by the
/// incremental parser. A later raw read may reparse those bytes, but it must
/// not manufacture another liveness signal.
#[derive(Default)]
struct ChatTerminalSignalTracker {
    provider_done_seen: bool,
    done_seen: bool,
}

impl ChatTerminalSignalTracker {
    fn observe(&mut self, provider_done: bool, done: bool) -> bool {
        let provider_done_progress = provider_done && !self.provider_done_seen;
        let done_progress = done && !self.done_seen;
        self.provider_done_seen |= provider_done;
        self.done_seen |= done;
        provider_done_progress || done_progress
    }
}

fn clear_pending_watchdog_retry_for_request(
    retry: &mut Option<PendingChatWatchdogRetry>,
    request_id: ChatStreamRequestId,
    surface: ChatStreamSurface,
) {
    if retry
        .as_ref()
        .is_some_and(|retry| retry.request_id == request_id && retry.surface == surface)
    {
        *retry = None;
    }
}

fn clear_watchdog_input_for_request(
    input: &mut Option<RequestBoundChatRetryInput>,
    request_id: ChatStreamRequestId,
    surface: ChatStreamSurface,
) {
    if input
        .as_ref()
        .is_some_and(|input| input.request_id == request_id && input.surface == surface)
    {
        *input = None;
    }
}

fn clear_watchdog_retry_stop_for_request(
    retry_stop: &mut Option<RequestBoundChatWatchdogRetryStop>,
    request_id: ChatStreamRequestId,
    surface: ChatStreamSurface,
) {
    if retry_stop.as_ref().is_some_and(|retry_stop| {
        retry_stop.request_id == request_id && retry_stop.surface == surface
    }) {
        *retry_stop = None;
    }
}

fn take_watchdog_retry_after_cancelled_settlement(
    retry: &mut Option<PendingChatWatchdogRetry>,
    request_id: ChatStreamRequestId,
    surface: ChatStreamSurface,
    terminal_phase: ChatStreamPhase,
) -> Option<PendingChatWatchdogRetry> {
    if !retry
        .as_ref()
        .is_some_and(|retry| retry.request_id == request_id && retry.surface == surface)
    {
        return None;
    }
    let retry = retry.take()?;
    (terminal_phase == ChatStreamPhase::Cancelled).then_some(retry)
}

/// Recover the request-bound watchdog deliberately. The state only controls a
/// UI diagnostic, but silently dropping it would remove the 120-second safety
/// signal for a live request. Clearing the poison after recovering the inner
/// value makes the next observer use the same repaired state.
fn lock_chat_signal_clock(
    signal_clock: &std::sync::Mutex<Option<ChatTurnWatchdog>>,
) -> std::sync::MutexGuard<'_, Option<ChatTurnWatchdog>> {
    match signal_clock.lock() {
        Ok(clock) => clock,
        Err(poisoned) => {
            tracing::warn!("recovering poisoned chat watchdog clock");
            let clock = poisoned.into_inner();
            signal_clock.clear_poison();
            clock
        }
    }
}

fn lock_chat_watchdog_retry(
    retry_mutex: &std::sync::Mutex<Option<PendingChatWatchdogRetry>>,
) -> std::sync::MutexGuard<'_, Option<PendingChatWatchdogRetry>> {
    match retry_mutex.lock() {
        Ok(retry) => retry,
        Err(poisoned) => {
            tracing::warn!("recovering poisoned chat watchdog retry queue");
            let retry = poisoned.into_inner();
            retry_mutex.clear_poison();
            retry
        }
    }
}

fn lock_chat_watchdog_input(
    input_mutex: &std::sync::Mutex<Option<RequestBoundChatRetryInput>>,
) -> std::sync::MutexGuard<'_, Option<RequestBoundChatRetryInput>> {
    match input_mutex.lock() {
        Ok(input) => input,
        Err(poisoned) => {
            tracing::warn!("recovering poisoned chat watchdog retry input");
            let input = poisoned.into_inner();
            input_mutex.clear_poison();
            input
        }
    }
}

fn lock_chat_watchdog_retry_stop(
    retry_stop_mutex: &std::sync::Mutex<Option<RequestBoundChatWatchdogRetryStop>>,
) -> std::sync::MutexGuard<'_, Option<RequestBoundChatWatchdogRetryStop>> {
    match retry_stop_mutex.lock() {
        Ok(retry_stop) => retry_stop,
        Err(poisoned) => {
            tracing::warn!("recovering poisoned chat watchdog retry-stop marker");
            let retry_stop = poisoned.into_inner();
            retry_stop_mutex.clear_poison();
            retry_stop
        }
    }
}

fn settle_chat_watchdog_retry_state(
    retry: &std::sync::Mutex<Option<PendingChatWatchdogRetry>>,
    input: &std::sync::Mutex<Option<RequestBoundChatRetryInput>>,
    retry_stop: &std::sync::Mutex<Option<RequestBoundChatWatchdogRetryStop>>,
    request_id: ChatStreamRequestId,
    surface: ChatStreamSurface,
    terminal_phase: ChatStreamPhase,
) -> Option<PendingChatWatchdogRetry> {
    let released_retry = take_watchdog_retry_after_cancelled_settlement(
        &mut lock_chat_watchdog_retry(retry),
        request_id,
        surface,
        terminal_phase,
    );
    clear_watchdog_input_for_request(&mut lock_chat_watchdog_input(input), request_id, surface);
    clear_watchdog_retry_stop_for_request(
        &mut lock_chat_watchdog_retry_stop(retry_stop),
        request_id,
        surface,
    );
    released_retry
}

/// Narrow recovery for the typed controller reads/mutations used by the
/// watchdog timer and operator Stop controls. Every caller must still
/// revalidate the exact active request, surface, phase, and request identity.
/// Provider/worker lifecycle paths intentionally keep their existing locking
/// policy and do not use this helper.
fn lock_chat_stream_for_watchdog_operator_control(
    stream: &std::sync::Mutex<ChatStreamController>,
) -> std::sync::MutexGuard<'_, ChatStreamController> {
    match stream.lock() {
        Ok(controller) => controller,
        Err(poisoned) => {
            tracing::error!(
                "recovering poisoned chat stream controller for watchdog/operator control"
            );
            let controller = poisoned.into_inner();
            stream.clear_poison();
            controller
        }
    }
}

/// Recover controller authority only at a worker's terminal boundary. The
/// exact request and surface are revalidated before settlement so recovery
/// cannot let a late worker settle a newer or cross-surface request.
fn settle_chat_stream_worker_terminal(
    stream: &std::sync::Mutex<ChatStreamController>,
    request_id: ChatStreamRequestId,
    surface: ChatStreamSurface,
    succeeded: bool,
) -> Option<chat_stream_phase::ChatStreamUpdate> {
    let mut controller = match stream.lock() {
        Ok(controller) => controller,
        Err(poisoned) => {
            tracing::error!(
                request_id = request_id.get(),
                ?surface,
                "recovering poisoned chat stream controller for exact worker terminal settlement"
            );
            let controller = poisoned.into_inner();
            stream.clear_poison();
            controller
        }
    };
    let exact_request = controller
        .active_request()
        .is_some_and(|request| request.request_id == request_id && request.surface == surface);
    exact_request
        .then(|| controller.settle(request_id, succeeded))
        .flatten()
}

fn diagnosed_chat_watchdog_request_for_surface(
    stream: &std::sync::Mutex<ChatStreamController>,
    signal_clock: &std::sync::Mutex<Option<ChatTurnWatchdog>>,
    expected_surface: ChatStreamSurface,
) -> Option<chat_stream_phase::ChatStreamUpdate> {
    let request = lock_chat_stream_for_watchdog_operator_control(stream).active_request()?;
    if request.surface != expected_surface || request.cancel_requested {
        return None;
    }
    lock_chat_signal_clock(signal_clock)
        .as_ref()
        .is_some_and(|watchdog| watchdog.is_diagnostic_for(request.request_id))
        .then_some(request)
}

fn prepare_chat_watchdog_retry_for_surface(
    stream: &std::sync::Mutex<ChatStreamController>,
    signal_clock: &std::sync::Mutex<Option<ChatTurnWatchdog>>,
    input: &std::sync::Mutex<Option<RequestBoundChatRetryInput>>,
    retry: &std::sync::Mutex<Option<PendingChatWatchdogRetry>>,
    retry_stop: &std::sync::Mutex<Option<RequestBoundChatWatchdogRetryStop>>,
    expected_surface: ChatStreamSurface,
) -> Option<chat_stream_phase::ChatStreamUpdate> {
    let request =
        diagnosed_chat_watchdog_request_for_surface(stream, signal_clock, expected_surface)?;
    let (body, incognito) = lock_chat_watchdog_input(input)
        .as_ref()
        .filter(|input| input.request_id == request.request_id && input.surface == expected_surface)
        .and_then(|input| {
            let body = zeroize::Zeroizing::new(input.body.trim().to_owned());
            (!body.is_empty()).then_some((body, input.incognito))
        })?;
    *lock_chat_watchdog_retry(retry) = Some(PendingChatWatchdogRetry {
        request_id: request.request_id,
        surface: expected_surface,
        body,
        incognito,
    });
    *lock_chat_watchdog_retry_stop(retry_stop) = Some(RequestBoundChatWatchdogRetryStop {
        request_id: request.request_id,
        surface: expected_surface,
    });

    let current =
        diagnosed_chat_watchdog_request_for_surface(stream, signal_clock, expected_surface);
    if current.is_none() {
        clear_pending_watchdog_retry_for_request(
            &mut lock_chat_watchdog_retry(retry),
            request.request_id,
            expected_surface,
        );
        clear_watchdog_retry_stop_for_request(
            &mut lock_chat_watchdog_retry_stop(retry_stop),
            request.request_id,
            expected_surface,
        );
    }
    current
}

fn authorize_chat_watchdog_stop_for_surface(
    stream: &std::sync::Mutex<ChatStreamController>,
    signal_clock: &std::sync::Mutex<Option<ChatTurnWatchdog>>,
    expected_surface: ChatStreamSurface,
) -> Option<chat_stream_phase::ChatStreamUpdate> {
    diagnosed_chat_watchdog_request_for_surface(stream, signal_clock, expected_surface)
}

fn mark_chat_stream_progress(
    watchdog: &std::sync::Arc<std::sync::Mutex<Option<ChatTurnWatchdog>>>,
    request_id: ChatStreamRequestId,
) {
    let mut watchdog = lock_chat_signal_clock(watchdog.as_ref());
    if let Some(watchdog) = watchdog.as_mut() {
        watchdog.rearm_for_meaningful_progress(request_id, std::time::Instant::now());
    }
}

#[cfg(windows)]
mod win_private {
    use std::fs::File;
    use std::io;
    use std::os::windows::ffi::OsStrExt;
    use std::os::windows::io::{AsRawHandle, FromRawHandle};
    use std::path::Path;

    use windows_sys::Win32::Foundation::{
        CloseHandle, ERROR_ALREADY_EXISTS, ERROR_FILE_EXISTS, ERROR_INSUFFICIENT_BUFFER,
        ERROR_SUCCESS, GetLastError, HANDLE, HLOCAL, INVALID_HANDLE_VALUE, LocalFree,
    };
    use windows_sys::Win32::Security::Authorization::{
        EXPLICIT_ACCESS_W, GRANT_ACCESS, GetNamedSecurityInfoW, GetSecurityInfo,
        NO_MULTIPLE_TRUSTEE, SE_FILE_OBJECT, SetEntriesInAclW, SetNamedSecurityInfoW,
        TRUSTEE_IS_SID, TRUSTEE_IS_UNKNOWN, TRUSTEE_W,
    };
    use windows_sys::Win32::Security::{
        ACCESS_ALLOWED_ACE, ACL, ACL_SIZE_INFORMATION, AclSizeInformation, CONTAINER_INHERIT_ACE,
        DACL_SECURITY_INFORMATION, EqualSid, GetAce, GetAclInformation, GetLengthSid,
        GetSecurityDescriptorControl, GetTokenInformation, INHERITED_ACE,
        InitializeSecurityDescriptor, IsValidSid, NO_INHERITANCE, OBJECT_INHERIT_ACE,
        PROTECTED_DACL_SECURITY_INFORMATION, SE_DACL_PROTECTED, SECURITY_ATTRIBUTES,
        SECURITY_DESCRIPTOR, SetSecurityDescriptorControl, SetSecurityDescriptorDacl, TOKEN_QUERY,
        TOKEN_USER, TokenUser,
    };
    use windows_sys::Win32::Storage::FileSystem::{
        CREATE_NEW, CreateFileW, DELETE, FILE_ALL_ACCESS, FILE_ATTRIBUTE_NORMAL, FILE_GENERIC_READ,
        FILE_GENERIC_WRITE, FILE_RENAME_INFO, FILE_RENAME_INFO_0, FileRenameInfoEx,
        FlushFileBuffers, SetFileInformationByHandle,
    };
    use windows_sys::Win32::System::Threading::{GetCurrentProcess, OpenProcessToken};

    pub fn create_private_file_new(path: &Path) -> io::Result<File> {
        let path_w = path_to_wide_nul(path)?;
        let sid = current_process_token_sid()?;
        let acl = single_trustee_acl(sid.as_ptr() as *mut u16, NO_INHERITANCE)?;
        let mut descriptor: SECURITY_DESCRIPTOR = unsafe { std::mem::zeroed() };
        let descriptor_ptr = std::ptr::addr_of_mut!(descriptor) as *mut std::ffi::c_void;
        const SECURITY_DESCRIPTOR_REVISION: u32 = 1;
        if unsafe { InitializeSecurityDescriptor(descriptor_ptr, SECURITY_DESCRIPTOR_REVISION) }
            == 0
        {
            return Err(last_win32_error("InitializeSecurityDescriptor"));
        }
        if unsafe { SetSecurityDescriptorDacl(descriptor_ptr, 1, acl.0, 0) } == 0 {
            return Err(last_win32_error("SetSecurityDescriptorDacl"));
        }
        if unsafe {
            SetSecurityDescriptorControl(descriptor_ptr, SE_DACL_PROTECTED, SE_DACL_PROTECTED)
        } == 0
        {
            return Err(last_win32_error("SetSecurityDescriptorControl"));
        }
        let security_attributes = SECURITY_ATTRIBUTES {
            nLength: std::mem::size_of::<SECURITY_ATTRIBUTES>() as u32,
            lpSecurityDescriptor: descriptor_ptr,
            bInheritHandle: 0,
        };
        let raw = unsafe {
            CreateFileW(
                path_w.as_ptr(),
                FILE_GENERIC_READ | FILE_GENERIC_WRITE | DELETE,
                0,
                &security_attributes,
                CREATE_NEW,
                FILE_ATTRIBUTE_NORMAL,
                std::ptr::null_mut(),
            )
        };
        if raw == INVALID_HANDLE_VALUE {
            let code = unsafe { GetLastError() };
            return Err(io::Error::new(
                win32_io_err(code).kind(),
                format!(
                    "CreateFileW(CREATE_NEW): Win32 error {code:#010x} ({})",
                    win32_io_err(code)
                ),
            ));
        }
        let owned = OwnedHandle(raw);
        if let Err(error) = verify_private_handle_for_sid(raw, &sid) {
            drop(owned);
            let _ = std::fs::remove_file(path);
            return Err(error);
        }
        Ok(owned.into_file())
    }

    pub fn replace_private_file_handle(file: &File, target: &Path) -> io::Result<()> {
        rename_private_file_handle(file, target, true)
    }

    pub fn create_private_file_handle(file: &File, target: &Path) -> io::Result<()> {
        rename_private_file_handle(file, target, false)
    }

    pub fn set_private_directory_dacl(path: &Path) -> io::Result<()> {
        let mut path_w = path_to_wide_nul(path)?;
        let sid = current_process_token_sid()?;
        let acl = single_trustee_acl(
            sid.as_ptr() as *mut u16,
            OBJECT_INHERIT_ACE | CONTAINER_INHERIT_ACE,
        )?;
        let rc = unsafe {
            SetNamedSecurityInfoW(
                path_w.as_mut_ptr(),
                SE_FILE_OBJECT,
                DACL_SECURITY_INFORMATION | PROTECTED_DACL_SECURITY_INFORMATION,
                std::ptr::null_mut(),
                std::ptr::null_mut(),
                acl.0,
                std::ptr::null_mut(),
            )
        };
        map_win32(rc, "SetNamedSecurityInfoW")?;
        verify_private_directory_dacl(path)
    }

    fn rename_private_file_handle(
        file: &File,
        target: &Path,
        replace_existing: bool,
    ) -> io::Result<()> {
        verify_private_file_handle(file)?;
        if unsafe { FlushFileBuffers(file.as_raw_handle() as HANDLE) } == 0 {
            return Err(last_win32_error("FlushFileBuffers"));
        }
        let absolute_target = std::path::absolute(target)?;
        let target_w = path_to_wide_nul(&absolute_target)?;
        let file_name_units = target_w
            .len()
            .checked_sub(1)
            .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "empty target path"))?;
        let file_name_bytes = file_name_units
            .checked_mul(std::mem::size_of::<u16>())
            .and_then(|length| u32::try_from(length).ok())
            .ok_or_else(|| {
                io::Error::new(io::ErrorKind::InvalidInput, "target path is too long")
            })?;
        let file_name_offset = u32::try_from(std::mem::offset_of!(FILE_RENAME_INFO, FileName))
            .expect("FILE_RENAME_INFO offset fits in u32");
        let buffer_size = file_name_offset
            .checked_add(file_name_bytes)
            .and_then(|length| length.checked_add(std::mem::size_of::<u16>() as u32))
            .ok_or_else(|| {
                io::Error::new(io::ErrorKind::InvalidInput, "target path is too long")
            })?;
        let mut storage =
            vec![0usize; (buffer_size as usize).div_ceil(std::mem::size_of::<usize>())];
        let rename_info = storage.as_mut_ptr().cast::<FILE_RENAME_INFO>();
        const FILE_RENAME_FLAG_REPLACE_IF_EXISTS: u32 = 0x1;
        const FILE_RENAME_FLAG_POSIX_SEMANTICS: u32 = 0x2;
        let flags = FILE_RENAME_FLAG_POSIX_SEMANTICS
            | if replace_existing {
                FILE_RENAME_FLAG_REPLACE_IF_EXISTS
            } else {
                0
            };
        unsafe {
            std::ptr::addr_of_mut!((*rename_info).Anonymous)
                .write(FILE_RENAME_INFO_0 { Flags: flags });
            std::ptr::addr_of_mut!((*rename_info).RootDirectory).write(std::ptr::null_mut());
            std::ptr::addr_of_mut!((*rename_info).FileNameLength).write(file_name_bytes);
            target_w.as_ptr().copy_to_nonoverlapping(
                std::ptr::addr_of_mut!((*rename_info).FileName).cast::<u16>(),
                target_w.len(),
            );
        }
        let rc = unsafe {
            SetFileInformationByHandle(
                file.as_raw_handle() as HANDLE,
                FileRenameInfoEx,
                rename_info.cast::<std::ffi::c_void>(),
                buffer_size,
            )
        };
        if rc == 0 {
            let code = unsafe { GetLastError() };
            let kind = if !replace_existing
                && (code == ERROR_ALREADY_EXISTS || code == ERROR_FILE_EXISTS)
            {
                io::ErrorKind::AlreadyExists
            } else {
                io::ErrorKind::PermissionDenied
            };
            return Err(io::Error::new(
                kind,
                format!(
                    "SetFileInformationByHandle(FileRenameInfoEx): Win32 error {code:#010x} ({})",
                    win32_io_err(code)
                ),
            ));
        }
        Ok(())
    }

    fn verify_private_file_handle(file: &File) -> io::Result<()> {
        verify_private_handle_for_sid(
            file.as_raw_handle() as HANDLE,
            &current_process_token_sid()?,
        )
    }

    fn verify_private_directory_dacl(path: &Path) -> io::Result<()> {
        let path_w = path_to_wide_nul(path)?;
        let mut dacl: *mut ACL = std::ptr::null_mut();
        let mut descriptor: *mut std::ffi::c_void = std::ptr::null_mut();
        let rc = unsafe {
            GetNamedSecurityInfoW(
                path_w.as_ptr(),
                SE_FILE_OBJECT,
                DACL_SECURITY_INFORMATION,
                std::ptr::null_mut(),
                std::ptr::null_mut(),
                &mut dacl,
                std::ptr::null_mut(),
                &mut descriptor,
            )
        };
        let descriptor = OwnedLocalDescriptor(descriptor);
        map_win32(rc, "GetNamedSecurityInfoW")?;
        verify_private_descriptor(
            descriptor.0,
            dacl,
            &current_process_token_sid()?,
            (OBJECT_INHERIT_ACE | CONTAINER_INHERIT_ACE) as u8,
        )
    }

    fn verify_private_handle_for_sid(handle: HANDLE, expected_sid: &[u8]) -> io::Result<()> {
        let mut dacl: *mut ACL = std::ptr::null_mut();
        let mut descriptor: *mut std::ffi::c_void = std::ptr::null_mut();
        let rc = unsafe {
            GetSecurityInfo(
                handle,
                SE_FILE_OBJECT,
                DACL_SECURITY_INFORMATION,
                std::ptr::null_mut(),
                std::ptr::null_mut(),
                &mut dacl,
                std::ptr::null_mut(),
                &mut descriptor,
            )
        };
        let descriptor = OwnedLocalDescriptor(descriptor);
        map_win32(rc, "GetSecurityInfo")?;
        verify_private_descriptor(descriptor.0, dacl, expected_sid, NO_INHERITANCE as u8)
    }

    fn verify_private_descriptor(
        descriptor: *mut std::ffi::c_void,
        dacl: *mut ACL,
        expected_sid: &[u8],
        expected_flags: u8,
    ) -> io::Result<()> {
        if descriptor.is_null() || dacl.is_null() {
            return Err(io::Error::new(
                io::ErrorKind::PermissionDenied,
                "private DACL missing",
            ));
        }
        let mut control = 0u16;
        let mut revision = 0u32;
        if unsafe { GetSecurityDescriptorControl(descriptor, &mut control, &mut revision) } == 0 {
            return Err(last_win32_error("GetSecurityDescriptorControl"));
        }
        if control & SE_DACL_PROTECTED == 0 {
            return Err(io::Error::new(
                io::ErrorKind::PermissionDenied,
                "private DACL is not protected",
            ));
        }
        let mut info: ACL_SIZE_INFORMATION = unsafe { std::mem::zeroed() };
        if unsafe {
            GetAclInformation(
                dacl,
                &mut info as *mut ACL_SIZE_INFORMATION as *mut std::ffi::c_void,
                std::mem::size_of::<ACL_SIZE_INFORMATION>() as u32,
                AclSizeInformation,
            )
        } == 0
        {
            return Err(last_win32_error("GetAclInformation"));
        }
        if info.AceCount == 0 || (expected_flags == NO_INHERITANCE as u8 && info.AceCount != 1) {
            return Err(io::Error::new(
                io::ErrorKind::PermissionDenied,
                format!("unexpected private DACL ACE count {}", info.AceCount),
            ));
        }
        const ACCESS_ALLOWED_ACE_TYPE: u8 = 0;
        const GENERIC_ALL: u32 = 0x1000_0000;
        const INHERIT_ONLY_ACE_FLAG: u8 = 0x08;
        let allowed_flags = if expected_flags == NO_INHERITANCE as u8 {
            expected_flags
        } else {
            expected_flags | INHERIT_ONLY_ACE_FLAG
        };
        let mut combined_flags = 0u8;
        for index in 0..info.AceCount {
            let mut ace_ptr: *mut std::ffi::c_void = std::ptr::null_mut();
            if unsafe { GetAce(dacl, index, &mut ace_ptr) } == 0 || ace_ptr.is_null() {
                return Err(last_win32_error("GetAce"));
            }
            let ace = unsafe { &*(ace_ptr as *const ACCESS_ALLOWED_ACE) };
            if ace.Header.AceType != ACCESS_ALLOWED_ACE_TYPE
                || ace.Header.AceFlags as u32 & INHERITED_ACE != 0
                || ace.Header.AceFlags & !allowed_flags != 0
            {
                return Err(io::Error::new(
                    io::ErrorKind::PermissionDenied,
                    "unsafe private DACL ACE",
                ));
            }
            combined_flags |= ace.Header.AceFlags & expected_flags;
            if ace.Mask & GENERIC_ALL != GENERIC_ALL
                && ace.Mask & FILE_ALL_ACCESS != FILE_ALL_ACCESS
            {
                return Err(io::Error::new(
                    io::ErrorKind::PermissionDenied,
                    "private DACL lacks full control",
                ));
            }
            let ace_sid = std::ptr::addr_of!(ace.SidStart) as *mut std::ffi::c_void;
            if unsafe { IsValidSid(ace_sid) } == 0
                || unsafe { EqualSid(ace_sid, expected_sid.as_ptr() as *mut std::ffi::c_void) } == 0
            {
                return Err(io::Error::new(
                    io::ErrorKind::PermissionDenied,
                    "private DACL SID mismatch",
                ));
            }
        }
        if combined_flags != expected_flags {
            return Err(io::Error::new(
                io::ErrorKind::PermissionDenied,
                "private DACL inheritance flags mismatch",
            ));
        }
        Ok(())
    }

    fn single_trustee_acl(sid: *mut u16, inheritance: u32) -> io::Result<OwnedLocalAcl> {
        let trustee = TRUSTEE_W {
            pMultipleTrustee: std::ptr::null_mut(),
            MultipleTrusteeOperation: NO_MULTIPLE_TRUSTEE,
            TrusteeForm: TRUSTEE_IS_SID,
            TrusteeType: TRUSTEE_IS_UNKNOWN,
            ptstrName: sid,
        };
        let entry = EXPLICIT_ACCESS_W {
            grfAccessPermissions: FILE_ALL_ACCESS,
            grfAccessMode: GRANT_ACCESS,
            grfInheritance: inheritance,
            Trustee: trustee,
        };
        let mut acl: *mut ACL = std::ptr::null_mut();
        let rc = unsafe { SetEntriesInAclW(1, &entry, std::ptr::null_mut(), &mut acl) };
        let acl = OwnedLocalAcl(acl);
        map_win32(rc, "SetEntriesInAclW")?;
        if acl.0.is_null() {
            Err(io::Error::other("SetEntriesInAclW returned null ACL"))
        } else {
            Ok(acl)
        }
    }

    fn current_process_token_sid() -> io::Result<Vec<u8>> {
        let mut token: HANDLE = std::ptr::null_mut();
        if unsafe { OpenProcessToken(GetCurrentProcess(), TOKEN_QUERY, &mut token) } == 0 {
            return Err(last_win32_error("OpenProcessToken"));
        }
        let token = OwnedHandle(token);
        let mut needed = 0u32;
        let first = unsafe {
            GetTokenInformation(token.0, TokenUser, std::ptr::null_mut(), 0, &mut needed)
        };
        if first != 0 || unsafe { GetLastError() } != ERROR_INSUFFICIENT_BUFFER || needed == 0 {
            return Err(last_win32_error("GetTokenInformation(size)"));
        }
        let mut buffer = vec![0u8; needed as usize];
        if unsafe {
            GetTokenInformation(
                token.0,
                TokenUser,
                buffer.as_mut_ptr().cast::<std::ffi::c_void>(),
                needed,
                &mut needed,
            )
        } == 0
        {
            return Err(last_win32_error("GetTokenInformation(TokenUser)"));
        }
        let token_user = unsafe { &*(buffer.as_ptr() as *const TOKEN_USER) };
        if unsafe { IsValidSid(token_user.User.Sid) } == 0 {
            return Err(io::Error::new(
                io::ErrorKind::InvalidData,
                "invalid TokenUser SID",
            ));
        }
        let sid_len = unsafe { GetLengthSid(token_user.User.Sid) };
        let mut sid = vec![0u8; sid_len as usize];
        unsafe {
            std::ptr::copy_nonoverlapping(
                token_user.User.Sid.cast::<u8>(),
                sid.as_mut_ptr(),
                sid.len(),
            );
        }
        Ok(sid)
    }

    fn path_to_wide_nul(path: &Path) -> io::Result<Vec<u16>> {
        let mut wide: Vec<u16> = path.as_os_str().encode_wide().collect();
        if wide.contains(&0) {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                "path contains NUL",
            ));
        }
        wide.push(0);
        Ok(wide)
    }

    fn map_win32(code: u32, context: &'static str) -> io::Result<()> {
        if code == ERROR_SUCCESS {
            Ok(())
        } else {
            Err(io::Error::new(
                io::ErrorKind::PermissionDenied,
                format!(
                    "{context}: Win32 error {code:#010x} ({})",
                    win32_io_err(code)
                ),
            ))
        }
    }

    fn last_win32_error(context: &'static str) -> io::Error {
        let code = unsafe { GetLastError() };
        io::Error::new(
            io::ErrorKind::PermissionDenied,
            format!(
                "{context}: Win32 error {code:#010x} ({})",
                win32_io_err(code)
            ),
        )
    }

    fn win32_io_err(code: u32) -> io::Error {
        io::Error::from_raw_os_error(code as i32)
    }

    struct OwnedHandle(HANDLE);

    impl OwnedHandle {
        fn into_file(self) -> File {
            let owned = std::mem::ManuallyDrop::new(self);
            unsafe { File::from_raw_handle(owned.0) }
        }
    }

    impl Drop for OwnedHandle {
        fn drop(&mut self) {
            if !self.0.is_null() && self.0 != INVALID_HANDLE_VALUE {
                unsafe { CloseHandle(self.0) };
            }
        }
    }

    struct OwnedLocalAcl(*mut ACL);

    impl Drop for OwnedLocalAcl {
        fn drop(&mut self) {
            if !self.0.is_null() {
                unsafe { LocalFree(self.0.cast::<std::ffi::c_void>() as HLOCAL) };
            }
        }
    }

    struct OwnedLocalDescriptor(*mut std::ffi::c_void);

    impl Drop for OwnedLocalDescriptor {
        fn drop(&mut self) {
            if !self.0.is_null() {
                unsafe { LocalFree(self.0 as HLOCAL) };
            }
        }
    }
}

