    window.on_open_license_url(|| {
        let url = "https://github.com/The-Geek-Freaks/NEOTH#license";
        let mut command = if cfg!(target_os = "windows") {
            let mut command = std::process::Command::new("cmd");
            command.args(["/C", "start", "", url]);
            command
        } else if cfg!(target_os = "macos") {
            let mut command = std::process::Command::new("open");
            command.arg(url);
            command
        } else {
            let mut command = std::process::Command::new("xdg-open");
            command.arg(url);
            command
        };
        scrub_gui_control_environment(&mut command);
        suppress_console_window(&mut command);
        let result = command.spawn();
        if let Err(e) = result {
            tracing::warn!(error = %e, url, "failed to open license URL");
        }
    });

    // Reviewer-3 P1-B (2026-05-20): Identity validation. The copy
    // promises `^[a-z0-9-]{3,32}$`; the gate used to accept any
    // non-empty string. Now we round-trip through Rust on every
    // keystroke + push the verdict back as `operator-id-valid`.
    // No regex crate dep — the pattern is tiny + character-class only.
    fn validate_operator_id(s: &str) -> bool {
        let len = s.chars().count();
        if !(3..=32).contains(&len) {
            return false;
        }
        s.chars()
            .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '-')
    }
    let weak_id = window.as_weak();
    window.on_operator_id_edited(move |text| {
        if let Some(w) = weak_id.upgrade() {
            w.set_operator_id_valid(validate_operator_id(&text));
        }
    });

    // Step 5 (2026-05-20): keep the last-applied snapshot alive in a
    // mutex so the task-click handler can resolve `task-id` → full
    // task detail (title/status/hemisphere) without re-walking the
    // Slint Model. Multiple writers (initial fetch / Refresh / 2s
    // tick) push through `store_kanban_snapshot`; the click handler
    // reads via `latest_kanban_snapshot`.
    use std::sync::{Arc, Mutex};
    let kanban_snapshot: Arc<Mutex<KanbanBoardSnapshot>> =
        Arc::new(Mutex::new(KanbanBoardSnapshot::default()));

    // Pick #8 step 2 — Code Sessions tab data binding.
    //   - At startup: fetch once so the tab shows real data the first
    //     time the operator opens it.
    //   - On Refresh button: re-fetch + re-populate.
    // Live WAL-driven updates land in step 4.
    //
    // H-4 fix — initial fetch + Refresh-click both run on a worker
    // thread so a slow `neothd kanban` subprocess can never block
    // the UI thread. The snapshot lands back on the main thread via
    // `invoke_from_event_loop`.
    let weak_kanban_init = window.as_weak();
    let mutex_init = kanban_snapshot.clone();
    let generation_init = current_kanban_selection_generation();
    std::thread::spawn(move || {
        let snap = fetch_kanban_board_snapshot();
        let snap_for_state = snap.clone();
        let weak = weak_kanban_init.clone();
        let _ = slint::invoke_from_event_loop(move || {
            if !kanban_generation_matches(generation_init, current_kanban_selection_generation()) {
                tracing::debug!(
                    generation_init,
                    "kanban: discarded stale startup snapshot after selection change"
                );
                return;
            }
            if let Ok(mut g) = mutex_init.lock() {
                *g = snap_for_state;
            }
            if let Some(w) = weak.upgrade() {
                apply_kanban_snapshot(&w, snap);
            }
        });
    });

    // GR-10 + GU-01 — one-shot startup fetch of the read-only settings panels
    // (Safety Rails / Hemispheres / Skills). Off the UI thread (three quick
    // subprocesses), each result marshalled back via invoke_from_event_loop.
    let weak_omi_draft = window.as_weak();
    window.on_omi_draft_edited(move || {
        OMI_DRAFT_REVISION.fetch_add(1, std::sync::atomic::Ordering::AcqRel);
        if let Some(window) = weak_omi_draft.upgrade() {
            window.set_omi_draft_dirty(true);
        }
    });
    let weak_panels_init = window.as_weak();
    let overlay_weak_panels_init = overlay.as_weak();
    let omi_startup_revision = OMI_UI_REVISION.load(std::sync::atomic::Ordering::Acquire);
    let omi_startup_draft_revision = OMI_DRAFT_REVISION.load(std::sync::atomic::Ordering::Acquire);
    std::thread::spawn(move || {
        let rails = fetch_safe_mode_snapshot();
        let trust = fetch_trust_snapshot();
        let omi = fetch_verified_omi_snapshot(&default_neoth_home());
        let hardware = fetch_hardware_snapshot();
        let topology = fetch_topology_snapshot();
        let usage = fetch_usage_meter();
        let council_budget = fetch_council_budget();
        let profile_presets = fetch_profile_presets();
        let hemis = fetch_hemispheres_snapshot();
        let provider_ids = fetch_provider_ids();
        let skills = fetch_skills();
        let plugins = fetch_plugins();
        let memory = fetch_memory_snapshot();
        // Channels come from the canonical daemon probe. This includes
        // keychain-backed credentials, feature availability, and partial/error
        // states without exposing secret values.
        let channels = fetch_channel_status();
        let weak = weak_panels_init.clone();
        let _ = slint::invoke_from_event_loop(move || {
            if let Some(w) = weak.upgrade() {
                apply_safe_mode(&w, rails);
                apply_trust(&w, trust);
                if OMI_UI_REVISION.load(std::sync::atomic::Ordering::Acquire)
                    == omi_startup_revision
                {
                    match omi {
                        Ok(snapshot) => {
                            let replace_draft = omi_draft_is_unchanged(
                                omi_startup_draft_revision,
                                OMI_DRAFT_REVISION.load(std::sync::atomic::Ordering::Acquire),
                                w.get_omi_draft_dirty(),
                            );
                            apply_omi_snapshot(&w, snapshot, replace_draft);
                        }
                        Err(error) => {
                            mark_omi_status_unverified(
                                &w,
                                &format!("OMI startup verification failed: {error}"),
                            );
                            w.set_omi_runtime_state("unverified".into());
                            w.set_omi_runtime_detail(
                                "No live OMI state was applied; repair the configuration or CLI and refresh."
                                    .into(),
                            );
                            w.set_status_line(
                                format!("OMI startup verification failed: {error}").into(),
                            );
                        }
                    }
                }
                apply_hardware(&w, hardware);
                match topology {
                    Ok(rows) => {
                        apply_topology(&w, rows);
                        w.set_cluster_topology_valid(true);
                        w.set_cluster_topology_error("".into());
                    }
                    Err(error) => {
                        // Invalid exits or envelopes retain every LKG peer row.
                        w.set_cluster_topology_valid(false);
                        w.set_cluster_topology_error(error.into());
                    }
                }
                apply_usage_meter(&w, usage);
                apply_council_budget(&w, council_budget);
                apply_profile_presets(&w, profile_presets);
                apply_hemispheres(&w, hemis);
                apply_provider_ids(&w, provider_ids);
                let overlay = overlay_weak_panels_init.upgrade();
                let _ = apply_skills(&w, overlay.as_ref(), skills);
                apply_plugins(&w, plugins);
                apply_memory(&w, memory);
                apply_channels(&w, channels);
            }
        });
    });

    // OMI-MULTIMODAL-01 — complete Privacy-tab wiring. All filesystem and
    // subprocess work runs off the UI thread. Secret updates use bounded child
    // stdin and the daemon's credential backend; they never enter argv or UI
    // read-back state.
    let omi_mutation_active = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
    let weak_omi_refresh = window.as_weak();
    let omi_mutation_active_for_refresh = std::sync::Arc::clone(&omi_mutation_active);
    window.on_omi_refresh(move || {
        if omi_mutation_active_for_refresh.load(std::sync::atomic::Ordering::Acquire) {
            push_toast(
                &weak_omi_refresh,
                "warn",
                "OMI change in progress",
                "Wait for the mutation receipt before refreshing status.",
            );
            return;
        }
        if OMI_STATUS_OPERATION_ACTIVE.swap(true, std::sync::atomic::Ordering::AcqRel) {
            push_toast(
                &weak_omi_refresh,
                "info",
                "OMI refresh already running",
                "The current strict status readback is still in progress.",
            );
            return;
        }
        let revision = OMI_UI_REVISION
            .fetch_add(1, std::sync::atomic::Ordering::AcqRel)
            .wrapping_add(1);
        if let Some(window) = weak_omi_refresh.upgrade() {
            window.set_omi_status_operation_in_flight(true);
            window.set_status_line(
                if window.get_omi_draft_dirty() {
                    "Discarding the OMI draft and loading verified state…"
                } else {
                    "Refreshing verified OMI state…"
                }
                .into(),
            );
        }
        let weak = weak_omi_refresh.clone();
        std::thread::spawn(move || {
            let snapshot = fetch_verified_omi_snapshot(&default_neoth_home());
            let _ = slint::invoke_from_event_loop(move || {
                OMI_STATUS_OPERATION_ACTIVE.store(false, std::sync::atomic::Ordering::Release);
                if let Some(window) = weak.upgrade() {
                    window.set_omi_status_operation_in_flight(false);
                }
                if OMI_UI_REVISION.load(std::sync::atomic::Ordering::Acquire) != revision {
                    return;
                }
                if let Some(window) = weak.upgrade() {
                    match snapshot {
                        Ok(snapshot) => {
                            apply_omi_snapshot(&window, snapshot, true);
                            window.set_status_line("OMI state refreshed and verified.".into());
                        }
                        Err(error) => {
                            let detail = format!(
                                "OMI refresh failed; the last verified state was preserved: {error}"
                            );
                            mark_omi_status_unverified(&window, &detail);
                            window.set_status_line(detail.into());
                        }
                    }
                }
            });
        });
    });

    let weak_omi_save = window.as_weak();
    let omi_mutation_active_for_save = std::sync::Arc::clone(&omi_mutation_active);
    window.on_omi_save(
        move |enabled,
              mode,
              endpoint,
              listen_addr,
              retention_days,
              retain_transcripts,
              audio_enabled,
              image_enabled,
              video_enabled,
              allow_cloud_api,
              allow_cloud_summary,
              create_actions,
              seed_groundtruth,
              summary_enabled,
              developer_key,
              native_token| {
            let Some(revision) = begin_omi_mutation(
                &weak_omi_save,
                &omi_mutation_active_for_save,
                "Save OMI settings",
            ) else {
                return;
            };
            let weak = weak_omi_save.clone();
            let draft = OmiSettingsDraft {
                enabled,
                mode: mode.to_string(),
                endpoint: endpoint.to_string(),
                listen_addr: listen_addr.to_string(),
                retention_days: retention_days.to_string(),
                retain_transcripts,
                audio_enabled,
                image_enabled,
                video_enabled,
                allow_cloud_api,
                allow_cloud_summary,
                create_actions,
                seed_groundtruth,
                summary_enabled,
                developer_key: zeroize::Zeroizing::new(developer_key.to_string()),
                native_token: zeroize::Zeroizing::new(native_token.to_string()),
            };
            if let Some(window) = weak_omi_save.upgrade() {
                // The worker owns the only remaining zeroizing copy. Never
                // retain write-only credentials in Slint while I/O is pending.
                window.set_omi_developer_key_draft("".into());
                window.set_omi_native_token_draft("".into());
                window.set_omi_save_in_flight(true);
                window.set_omi_draft_dirty(true);
            }
            let mutation_active = std::sync::Arc::clone(&omi_mutation_active_for_save);
            std::thread::spawn(move || {
                let home = default_neoth_home();
                let result = (|| {
                    // Serialize this external canonical transaction with every
                    // legacy GUI read/modify/write worker. The CLI supplies its
                    // own cross-process locks; this guard prevents a GUI worker
                    // that read the previous generation from publishing after
                    // the acknowledged OMI commit.
                    let _gui_write_guard = FREEDOM_WRITE_LOCK
                        .lock()
                        .unwrap_or_else(|error| error.into_inner());
                    let receipt = save_omi_settings(&home, &draft)?;
                    let snapshot = fetch_verified_omi_snapshot(&home).map_err(|error| {
                        anyhow::anyhow!(
                            "configuration was acknowledged, but live-state readback failed: {error}"
                        )
                    })?;
                    Ok::<_, anyhow::Error>((receipt, snapshot))
                })();
                let _ = slint::invoke_from_event_loop(move || {
                    mutation_active.store(false, std::sync::atomic::Ordering::Release);
                    if let Some(window) = weak.upgrade() {
                        window.set_omi_mutation_in_flight(false);
                        window.set_omi_save_in_flight(false);
                        if OMI_UI_REVISION.load(std::sync::atomic::Ordering::Acquire) != revision {
                            return;
                        }
                        match result {
                            Ok((receipt, snapshot)) => {
                                apply_omi_snapshot(&window, snapshot, true);
                                window.set_status_line(
                                    format!(
                                        "OMI settings saved, read back, and reload requested (generation {}).",
                                        receipt.config_sha256.chars().take(12).collect::<String>()
                                    )
                                    .into(),
                                );
                            }
                            Err(error) => {
                                let detail = format!(
                                    "OMI settings could not be verified; the non-secret draft remains visible, credential drafts were cleared, and the last verified runtime status was preserved: {error:#}"
                                );
                                mark_omi_status_unverified(&window, &detail);
                                window.set_status_line(detail.into());
                            }
                        }
                    }
                });
            });
        },
    );

    let weak_omi_probe = window.as_weak();
    let omi_mutation_active_for_probe = std::sync::Arc::clone(&omi_mutation_active);
    window.on_omi_probe(move || {
        if omi_mutation_active_for_probe.load(std::sync::atomic::Ordering::Acquire) {
            push_toast(
                &weak_omi_probe,
                "info",
                "OMI operation in progress",
                "Wait for the current status or mutation receipt before probing.",
            );
            return;
        }
        if OMI_STATUS_OPERATION_ACTIVE.swap(true, std::sync::atomic::Ordering::AcqRel) {
            push_toast(
                &weak_omi_probe,
                "info",
                "OMI status operation in progress",
                "Wait for the current refresh or probe to complete.",
            );
            return;
        }
        let revision = OMI_UI_REVISION.load(std::sync::atomic::Ordering::Acquire);
        if let Some(window) = weak_omi_probe.upgrade() {
            window.set_omi_status_operation_in_flight(true);
            window.set_status_line("Probing the configured OMI transports…".into());
        }
        let weak = weak_omi_probe.clone();
        std::thread::spawn(move || {
            let result: std::result::Result<String, String> = (|| {
                let acknowledgement = run_omi_json_action::<gui_action::OmiProbeAck>(
                    &default_neoth_home(),
                    &["probe".to_string()],
                    "OMI probe",
                )?;
                acknowledgement.verify()?;
                Ok::<_, String>(acknowledgement.summary())
            })();
            let status = result.unwrap_or_else(|error| format!("OMI probe failed: {error}"));
            let _ = slint::invoke_from_event_loop(move || {
                OMI_STATUS_OPERATION_ACTIVE.store(false, std::sync::atomic::Ordering::Release);
                if let Some(window) = weak.upgrade() {
                    window.set_omi_status_operation_in_flight(false);
                }
                if OMI_UI_REVISION.load(std::sync::atomic::Ordering::Acquire) != revision {
                    return;
                }
                if let Some(window) = weak.upgrade() {
                    window.set_status_line(status.into());
                }
            });
        });
    });

    let weak_omi_resume = window.as_weak();
    let omi_mutation_active_for_resume = std::sync::Arc::clone(&omi_mutation_active);
    window.on_omi_resume(move |note| {
        let Some(revision) = begin_omi_mutation(
            &weak_omi_resume,
            &omi_mutation_active_for_resume,
            "Resume OMI sanitizer",
        ) else {
            return;
        };
        let weak = weak_omi_resume.clone();
        let note = note.to_string();
        let mutation_active = std::sync::Arc::clone(&omi_mutation_active_for_resume);
        std::thread::spawn(move || {
            let home = default_neoth_home();
            let result = (|| {
                let acknowledgement = run_omi_json_action::<gui_action::OmiResumeAck>(
                    &home,
                    &["resume".into(), "--review-note".into(), note],
                    "OMI resume",
                )?;
                acknowledgement.verify()?;
                let snapshot = fetch_verified_omi_snapshot(&home).map_err(|error| {
                    format!("resume was acknowledged, but live-state readback failed: {error}")
                })?;
                Ok::<_, String>((acknowledgement, snapshot))
            })();
            let _ = slint::invoke_from_event_loop(move || {
                mutation_active.store(false, std::sync::atomic::Ordering::Release);
                if let Some(window) = weak.upgrade() {
                    window.set_omi_mutation_in_flight(false);
                    if OMI_UI_REVISION.load(std::sync::atomic::Ordering::Acquire) != revision {
                        return;
                    }
                    match result {
                        Ok((acknowledgement, snapshot)) => {
                            let replace_draft = !window.get_omi_draft_dirty();
                            apply_omi_snapshot(&window, snapshot, replace_draft);
                            window.set_omi_review_note("".into());
                            let status = if acknowledgement.resumed {
                                "OMI sanitizer resumed; review evidence retained."
                            } else {
                                "OMI sanitizer was already active; no state changed."
                            };
                            window.set_status_line(status.into());
                        }
                        Err(error) => {
                            let detail = format!(
                                "OMI resume could not be verified; the last verified state was preserved: {error}"
                            );
                            mark_omi_status_unverified(&window, &detail);
                            window.set_status_line(detail.into());
                        }
                    }
                }
            });
        });
    });

    let weak_omi_retention = window.as_weak();
    let omi_mutation_active_for_retention = std::sync::Arc::clone(&omi_mutation_active);
    window.on_omi_retention(move || {
        let Some(revision) = begin_omi_mutation(
            &weak_omi_retention,
            &omi_mutation_active_for_retention,
            "Enforce OMI retention",
        ) else {
            return;
        };
        let weak = weak_omi_retention.clone();
        let mutation_active = std::sync::Arc::clone(&omi_mutation_active_for_retention);
        std::thread::spawn(move || {
            let home = default_neoth_home();
            let result = (|| {
                let acknowledgement = run_omi_json_action::<gui_action::OmiDeletionAck>(
                    &home,
                    &["enforce-retention".into()],
                    "OMI retention",
                )?;
                acknowledgement.verify("retention", None)?;
                let snapshot = fetch_verified_omi_snapshot(&home).map_err(|error| {
                    format!(
                        "retention was acknowledged, but live-state readback failed: {error}"
                    )
                })?;
                Ok::<_, String>((acknowledgement, snapshot))
            })();
            let _ = slint::invoke_from_event_loop(move || {
                mutation_active.store(false, std::sync::atomic::Ordering::Release);
                if let Some(window) = weak.upgrade() {
                    window.set_omi_mutation_in_flight(false);
                    if OMI_UI_REVISION.load(std::sync::atomic::Ordering::Acquire) != revision {
                        return;
                    }
                    match result {
                        Ok((acknowledgement, snapshot)) => {
                            let removed = acknowledgement.total_removed();
                            let replace_draft = !window.get_omi_draft_dirty();
                            apply_omi_snapshot(&window, snapshot, replace_draft);
                            window.set_status_line(
                                format!(
                                    "OMI retention completed and verified; {removed} local record(s) removed."
                                )
                                .into(),
                            );
                        }
                        Err(error) => {
                            let detail = format!(
                                "OMI retention could not be verified; the last verified state was preserved: {error}"
                            );
                            mark_omi_status_unverified(&window, &detail);
                            window.set_status_line(detail.into());
                        }
                    }
                }
            });
        });
    });

    let weak_omi_purge = window.as_weak();
    let omi_mutation_active_for_purge = std::sync::Arc::clone(&omi_mutation_active);
    window.on_omi_purge(move |conversation_id| {
        if conversation_id.trim().is_empty() {
            push_toast(
                &weak_omi_purge,
                "warn",
                "Conversation id required",
                "Enter the exact OMI conversation id before permanent purge.",
            );
            return;
        }
        let Some(revision) = begin_omi_mutation(
            &weak_omi_purge,
            &omi_mutation_active_for_purge,
            "Purge OMI conversation",
        ) else {
            return;
        };
        let weak = weak_omi_purge.clone();
        let conversation_id = conversation_id.to_string();
        let mutation_active = std::sync::Arc::clone(&omi_mutation_active_for_purge);
        std::thread::spawn(move || {
            let home = default_neoth_home();
            let result = (|| {
                let acknowledgement = run_omi_json_action::<gui_action::OmiDeletionAck>(
                    &home,
                    &[
                        "purge".into(),
                        conversation_id.clone(),
                        "--yes".into(),
                    ],
                    "OMI purge",
                )?;
                acknowledgement.verify("purge", Some(&conversation_id))?;
                let snapshot = fetch_verified_omi_snapshot(&home).map_err(|error| {
                    format!("purge was acknowledged, but live-state readback failed: {error}")
                })?;
                Ok::<_, String>((acknowledgement, snapshot))
            })();
            let _ = slint::invoke_from_event_loop(move || {
                mutation_active.store(false, std::sync::atomic::Ordering::Release);
                if let Some(window) = weak.upgrade() {
                    window.set_omi_mutation_in_flight(false);
                    if OMI_UI_REVISION.load(std::sync::atomic::Ordering::Acquire) != revision {
                        return;
                    }
                    match result {
                        Ok((acknowledgement, snapshot)) => {
                            let removed = acknowledgement.total_removed();
                            let replace_draft = !window.get_omi_draft_dirty();
                            apply_omi_snapshot(&window, snapshot, replace_draft);
                            window.set_status_line(
                                format!(
                                    "OMI purge completed and verified; {removed} local record(s) removed."
                                )
                                .into(),
                            );
                        }
                        Err(error) => {
                            let detail = format!(
                                "OMI purge could not be verified; the last verified state was preserved: {error}"
                            );
                            mark_omi_status_unverified(&window, &detail);
                            window.set_status_line(detail.into());
                        }
                    }
                }
            });
        });
    });

    let weak_omi_reimport = window.as_weak();
    let omi_mutation_active_for_reimport = std::sync::Arc::clone(&omi_mutation_active);
    window.on_omi_reimport(move |conversation_id| {
        if conversation_id.trim().is_empty() {
            push_toast(
                &weak_omi_reimport,
                "warn",
                "Conversation id required",
                "Enter the exact OMI conversation id before allowing re-import.",
            );
            return;
        }
        let Some(revision) = begin_omi_mutation(
            &weak_omi_reimport,
            &omi_mutation_active_for_reimport,
            "Allow OMI re-import",
        ) else {
            return;
        };
        let weak = weak_omi_reimport.clone();
        let conversation_id = conversation_id.to_string();
        let mutation_active = std::sync::Arc::clone(&omi_mutation_active_for_reimport);
        std::thread::spawn(move || {
            let home = default_neoth_home();
            let result = (|| {
                let acknowledgement = run_omi_json_action::<gui_action::OmiAllowReimportAck>(
                    &home,
                    &[
                        "allow-reimport".into(),
                        conversation_id.clone(),
                        "--yes".into(),
                    ],
                    "OMI allow-reimport",
                )?;
                acknowledgement.verify(&conversation_id)?;
                let snapshot = fetch_verified_omi_snapshot(&home).map_err(|error| {
                    format!(
                        "allow-reimport was acknowledged, but live-state readback failed: {error}"
                    )
                })?;
                Ok::<_, String>((acknowledgement, snapshot))
            })();
            let _ = slint::invoke_from_event_loop(move || {
                mutation_active.store(false, std::sync::atomic::Ordering::Release);
                if let Some(window) = weak.upgrade() {
                    window.set_omi_mutation_in_flight(false);
                    if OMI_UI_REVISION.load(std::sync::atomic::Ordering::Acquire) != revision {
                        return;
                    }
                    match result {
                        Ok((acknowledgement, snapshot)) => {
                            let replace_draft = !window.get_omi_draft_dirty();
                            apply_omi_snapshot(&window, snapshot, replace_draft);
                            let detail = match (
                                acknowledgement.tombstone_cleared,
                                acknowledgement.stale_native_receipt_removed,
                            ) {
                                (true, true) => "tombstone and stale receipt cleared",
                                (true, false) => "tombstone cleared",
                                (false, true) => "stale receipt cleared; no tombstone existed",
                                (false, false) => "no stale recovery state existed",
                            };
                            window.set_status_line(
                                format!("OMI re-import permission verified; {detail}.").into(),
                            );
                        }
                        Err(error) => {
                            let detail = format!(
                                "OMI allow-reimport could not be verified; the last verified state was preserved: {error}"
                            );
                            mark_omi_status_unverified(&window, &detail);
                            window.set_status_line(detail.into());
                        }
                    }
                }
            });
        });
    });

    // SPEC-06 — operator rebound a role in the Hemispheres panel: shell
    // `neoth hemispheres set` then refresh the bindings so the panel reflects
    // the new wiring immediately.
    let weak_hemi_set = window.as_weak();
    window.on_hemisphere_set(move |role, provider, model| {
        // "(provider default)" sentinel (combo row 0) → leave the model unset.
        let model = if model == "(provider default)" {
            String::new()
        } else {
            model.to_string()
        };
        let role = role.to_string();
        let provider = provider.to_string();
        let weak = weak_hemi_set.clone();
        std::thread::spawn(move || {
            let status = set_hemisphere_via_subprocess(&role, &provider, &model);
            let hemis = fetch_hemispheres_snapshot();
            let _ = slint::invoke_from_event_loop(move || {
                if let Some(w) = weak.upgrade() {
                    w.set_status_line(status.into());
                    apply_hemispheres(&w, hemis);
                }
            });
        });
    });

    // P1-22: this is intentionally construction-only. It exercises the same
    // typed role resolver as `neoth hemispheres test`, but sends no prompt and
    // never turns a local configuration check into a reachability claim.
    let weak_hemi_readiness = window.as_weak();
    window.on_hemisphere_readiness(move |role| {
        let role = role.to_string();
        let weak = weak_hemi_readiness.clone();
        std::thread::spawn(move || {
            let status = check_hemisphere_readiness(&role);
            let _ = slint::invoke_from_event_loop(move || {
                if let Some(w) = weak.upgrade() {
                    w.set_status_line(status.into());
                }
            });
        });
    });

    // GOLD-GUI-OVERHAUL — operator picked a provider in the rebind row; refresh
    // the model combo with that provider's options (local GGUF refs / cloud
    // catalog) off-thread so the VRAM probe never freezes the UI.
    let weak_hemi_models = window.as_weak();
    window.on_hemisphere_provider_picked(move |provider| {
        let weak = weak_hemi_models.clone();
        let provider = provider.to_string();
        std::thread::spawn(move || {
            let models = fetch_hemisphere_model_ids(&provider);
            let _ = slint::invoke_from_event_loop(move || {
                if let Some(w) = weak.upgrade() {
                    use slint::{ModelRc, SharedString, VecModel};
                    let rows: Vec<SharedString> = models.into_iter().map(|s| s.into()).collect();
                    w.set_hemisphere_model_ids(ModelRc::new(VecModel::from(rows)));
                }
            });
        });
    });

    // A3 — session selector: row 0 is the explicit Latest (live) sentinel;
    // subsequent rows bind 1:1 to the concrete session ids. Advance the
    // generation before refreshing so any old warm/cold fetch is rejected.
    let weak_sess_sel = window.as_weak();
    window.on_kanban_session_selected(move |idx| {
        let id = {
            let ids = KANBAN_SESSION_IDS.lock().unwrap_or_else(|e| e.into_inner());
            kanban_selector_session_id(&ids, idx)
        };
        if let Some(id) = id {
            let previous = KANBAN_SESSION_OVERRIDE.swap(id, std::sync::atomic::Ordering::AcqRel);
            if previous != id {
                KANBAN_SELECTION_GENERATION.fetch_add(1, std::sync::atomic::Ordering::AcqRel);
            }
            if let Some(w) = weak_sess_sel.upgrade() {
                w.invoke_kanban_refresh_clicked();
            }
        }
    });

    let weak_kanban_refresh = window.as_weak();
    let mutex_refresh = kanban_snapshot.clone();
    window.on_kanban_refresh_clicked(move || {
        if let Some(w) = weak_kanban_refresh.upgrade() {
            buddy(&w, GuiActivity::AgentParallel);
        }
        let weak = weak_kanban_refresh.clone();
        let mutex = mutex_refresh.clone();
        let expected_generation = current_kanban_selection_generation();
        std::thread::spawn(move || {
            let snap = fetch_kanban_board_snapshot();
            info!(summary = %snap.summary, "kanban: refresh requested");
            let snap_for_state = snap.clone();
            let _ = slint::invoke_from_event_loop(move || {
                if !kanban_generation_matches(
                    expected_generation,
                    current_kanban_selection_generation(),
                ) {
                    tracing::debug!(
                        expected_generation,
                        "kanban: discarded stale refresh snapshot after selection change"
                    );
                    return;
                }
                if let Ok(mut g) = mutex.lock() {
                    *g = snap_for_state;
                }
                if let Some(w) = weak.upgrade() {
                    apply_kanban_snapshot(&w, snap);
                }
            });
        });
    });

