/// DES-09 helper — read a nested f64 from freedom.yaml.
/// Returns `default` on missing file / key / malformed YAML.
/// Used for fields like `council.daily_usd_cap` which are stored as YAML floats.
fn read_nested_f64_in_freedom(path: &Path, dotted_key: &str) -> Option<f64> {
    let Ok(body) = std::fs::read_to_string(path) else {
        return None;
    };
    let Ok(root) = serde_yaml::from_str::<serde_yaml::Value>(&body) else {
        return None;
    };
    let segments: Vec<&str> = dotted_key.splitn(8, '.').collect();
    let leaf = match segments.as_slice() {
        [leaf] => root.get(serde_yaml::Value::from(*leaf)),
        [k1, leaf] => root
            .get(k1)
            .and_then(|v| v.get(serde_yaml::Value::from(*leaf))),
        [k1, k2, leaf] => root
            .get(k1)
            .and_then(|v| v.get(*k2))
            .and_then(|v| v.get(serde_yaml::Value::from(*leaf))),
        _ => None,
    };
    leaf.and_then(|v| v.as_f64())
}

/// Format an f64 cap value for display: strip the trailing ".0" for whole
/// numbers so "10" shows instead of "10.0", but "10.5" stays "10.5".
fn format_cap_f64(v: f64) -> String {
    if v.fract() == 0.0 && v.abs() < 1e15 {
        format!("{}", v as i64)
    } else {
        format!("{v}")
    }
}

/// GUI-DES-SETTINGS-PRELOAD-01 — read a top-level YAML sequence as Vec<String>.
///
/// Only top-level keys are supported (no dotted paths) because
/// `knowledge_preload_dirs` is a bare list at the root of freedom.yaml.
/// Returns an empty vec on missing file / missing key / non-sequence / malformed YAML.
fn read_nested_seq_in_freedom(path: &Path, key: &str) -> Vec<String> {
    let Ok(body) = std::fs::read_to_string(path) else {
        return Vec::new();
    };
    let Ok(root) = serde_yaml::from_str::<serde_yaml::Value>(&body) else {
        return Vec::new();
    };
    let serde_yaml::Value::Mapping(map) = root else {
        return Vec::new();
    };
    map.get(serde_yaml::Value::from(key))
        .and_then(|v| v.as_sequence())
        .map(|seq| {
            seq.iter()
                .filter_map(|v| v.as_str())
                .map(str::to_string)
                .collect()
        })
        .unwrap_or_default()
}

/// GUI-DES-SETTINGS-PRELOAD-01 — unit tests for preload helpers.
#[cfg(test)]
mod preload01_tests {
    use super::*;
    use tempfile::TempDir;

    #[test]
    fn truncate_chars_never_slices_mid_codepoint() {
        // WS-BUG P0 regression: byte-index slices panicked on non-ASCII.
        assert_eq!(truncate_chars("hello", 80), "hello");
        assert_eq!(truncate_chars("hello", 3), "hel");
        // 77 ASCII + a 4-byte emoji: the limit counts CHARS (78 total),
        // so 80 keeps everything, 77 drops the emoji, and no byte-index
        // slice can ever land mid-codepoint.
        let s = format!("{}🌍", "x".repeat(77));
        assert_eq!(truncate_chars(&s, 80), s.as_str()); // 78 chars fit
        assert_eq!(truncate_chars(&s, 77), &"x".repeat(77)); // emoji dropped, no panic
        assert_eq!(truncate_chars(&s, 78).chars().count(), 78); // includes the emoji
        assert_eq!(truncate_chars("日本語テスト", 3), "日本語");
        assert_eq!(truncate_chars("", 5), "");
    }

    fn write_yaml(dir: &TempDir, content: &str) -> std::path::PathBuf {
        let path = dir.path().join("freedom.yaml");
        std::fs::write(&path, content).unwrap();
        path
    }

    #[test]
    fn seq_reads_list_as_vec() {
        let dir = TempDir::new().unwrap();
        let path = write_yaml(
            &dir,
            "knowledge_preload_dirs:\n  - /home/user/docs\n  - /var/data/kb\n",
        );
        let got = read_nested_seq_in_freedom(&path, "knowledge_preload_dirs");
        assert_eq!(got, vec!["/home/user/docs", "/var/data/kb"]);
    }

    #[test]
    fn seq_returns_empty_for_missing_key() {
        let dir = TempDir::new().unwrap();
        let path = write_yaml(&dir, "other_key: value\n");
        let got = read_nested_seq_in_freedom(&path, "knowledge_preload_dirs");
        assert!(got.is_empty(), "expected empty vec, got {got:?}");
    }

    #[test]
    fn seq_returns_empty_for_missing_file() {
        let dir = TempDir::new().unwrap();
        let path = dir.path().join("does_not_exist.yaml");
        let got = read_nested_seq_in_freedom(&path, "knowledge_preload_dirs");
        assert!(got.is_empty());
    }

    #[test]
    fn seq_join_roundtrip() {
        // Write a seq to yaml, read it back, join with "\n" — matches newline-sep UI text.
        let dir = TempDir::new().unwrap();
        let path = write_yaml(&dir, "knowledge_preload_dirs:\n  - /alpha\n  - /beta\n");
        let got = read_nested_seq_in_freedom(&path, "knowledge_preload_dirs");
        assert_eq!(got.join("\n"), "/alpha\n/beta");
    }

    #[test]
    fn newline_list_to_seq_round_trips() {
        // Simulates on_obs_knowledge_preload_dirs_changed: multiline editor → Vec<String>.
        let raw = "/home/user/docs\n/var/data/kb\n\n  ";
        let paths: Vec<String> = raw
            .lines()
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .map(str::to_string)
            .collect();
        assert_eq!(paths, vec!["/home/user/docs", "/var/data/kb"]);
    }

    #[test]
    fn newline_list_empty_gives_empty_vec() {
        let raw = "\n  \n\t\n";
        let paths: Vec<String> = raw
            .lines()
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .map(str::to_string)
            .collect();
        assert!(paths.is_empty());
    }
}

#[cfg(test)]
mod des09_tests {
    use super::*;
    use tempfile::TempDir;

    fn write_yaml(dir: &TempDir, content: &str) -> std::path::PathBuf {
        let path = dir.path().join("freedom.yaml");
        std::fs::write(&path, content).unwrap();
        path
    }

    // Helper that uses std write (no ACL) so tests pass on all platforms.
    fn set_nested_test(path: &Path, key: &str, value: serde_yaml::Value) -> Result<()> {
        let body = if path.exists() {
            std::fs::read_to_string(path).unwrap()
        } else {
            String::new()
        };
        let mut root: serde_yaml::Value = if body.trim().is_empty() {
            serde_yaml::Value::Mapping(serde_yaml::Mapping::new())
        } else {
            serde_yaml::from_str(&body).unwrap()
        };
        let map = match &mut root {
            serde_yaml::Value::Mapping(m) => m,
            _ => panic!("not a mapping"),
        };
        let segs: Vec<&str> = key.splitn(8, '.').collect();
        match segs.as_slice() {
            [leaf] => {
                map.insert(serde_yaml::Value::from(*leaf), value);
            }
            [k1, leaf] => {
                let k1v = serde_yaml::Value::from(*k1);
                let mut inner = map
                    .get(&k1v)
                    .and_then(|v| v.as_mapping())
                    .cloned()
                    .unwrap_or_default();
                inner.insert(serde_yaml::Value::from(*leaf), value);
                map.insert(k1v, serde_yaml::Value::Mapping(inner));
            }
            [k1, k2, leaf] => {
                let k1v = serde_yaml::Value::from(*k1);
                let mut m1 = map
                    .get(&k1v)
                    .and_then(|v| v.as_mapping())
                    .cloned()
                    .unwrap_or_default();
                let k2v = serde_yaml::Value::from(*k2);
                let mut m2 = m1
                    .get(&k2v)
                    .and_then(|v| v.as_mapping())
                    .cloned()
                    .unwrap_or_default();
                m2.insert(serde_yaml::Value::from(*leaf), value);
                m1.insert(k2v, serde_yaml::Value::Mapping(m2));
                map.insert(k1v, serde_yaml::Value::Mapping(m1));
            }
            _ => panic!("depth > 3"),
        }
        let out = serde_yaml::to_string(&root).unwrap();
        std::fs::write(path, out).unwrap();
        Ok(())
    }

    #[test]
    fn nested_create_two_level() {
        let dir = TempDir::new().unwrap();
        let path = dir.path().join("freedom.yaml");
        set_nested_test(
            &path,
            "council.daily_usd_cap",
            serde_yaml::Value::from(5.0f64),
        )
        .unwrap();
        let body = std::fs::read_to_string(&path).unwrap();
        let root: serde_yaml::Value = serde_yaml::from_str(&body).unwrap();
        let got = root
            .get("council")
            .and_then(|v| v.get("daily_usd_cap"))
            .and_then(|v| v.as_f64())
            .unwrap();
        assert!((got - 5.0).abs() < 1e-9, "expected 5.0 got {got}");
    }

    #[test]
    fn nested_update_preserves_siblings() {
        let dir = TempDir::new().unwrap();
        let path = write_yaml(
            &dir,
            "council:\n  daily_usd_cap: 3.0\n  max_calls: 10\nother_key: kept\n",
        );
        set_nested_test(
            &path,
            "council.daily_usd_cap",
            serde_yaml::Value::from(9.0f64),
        )
        .unwrap();
        let body = std::fs::read_to_string(&path).unwrap();
        let root: serde_yaml::Value = serde_yaml::from_str(&body).unwrap();
        // other_key preserved
        assert_eq!(root.get("other_key").and_then(|v| v.as_str()), Some("kept"));
        // sibling inside council preserved
        assert_eq!(
            root.get("council")
                .and_then(|v| v.get("max_calls"))
                .and_then(|v| v.as_i64()),
            Some(10)
        );
        // updated value
        let cap = root
            .get("council")
            .and_then(|v| v.get("daily_usd_cap"))
            .and_then(|v| v.as_f64())
            .unwrap();
        assert!((cap - 9.0).abs() < 1e-9);
    }

    #[test]
    fn top_level_key() {
        let dir = TempDir::new().unwrap();
        let path = write_yaml(&dir, "provider_kind: claude_cli\n");
        set_nested_test(&path, "user_tz", serde_yaml::Value::from("Europe/Berlin")).unwrap();
        let body = std::fs::read_to_string(&path).unwrap();
        let root: serde_yaml::Value = serde_yaml::from_str(&body).unwrap();
        assert_eq!(
            root.get("user_tz").and_then(|v| v.as_str()),
            Some("Europe/Berlin")
        );
        // provider_kind survives
        assert_eq!(
            root.get("provider_kind").and_then(|v| v.as_str()),
            Some("claude_cli")
        );
    }

    #[test]
    fn three_level_nested() {
        let dir = TempDir::new().unwrap();
        let path = dir.path().join("freedom.yaml");
        set_nested_test(
            &path,
            "memory.vector_index.backend",
            serde_yaml::Value::from("hnsw"),
        )
        .unwrap();
        let body = std::fs::read_to_string(&path).unwrap();
        let root: serde_yaml::Value = serde_yaml::from_str(&body).unwrap();
        let got = root
            .get("memory")
            .and_then(|v| v.get("vector_index"))
            .and_then(|v| v.get("backend"))
            .and_then(|v| v.as_str())
            .unwrap();
        assert_eq!(got, "hnsw");
    }

    // ── FIX 4 tests — read_nested_f64_in_freedom + format_cap_f64 ──────────

    #[test]
    fn read_f64_returns_value_for_float_node() {
        let dir = TempDir::new().unwrap();
        let path = write_yaml(&dir, "council:\n  daily_usd_cap: 10.0\n");
        let v = read_nested_f64_in_freedom(&path, "council.daily_usd_cap");
        assert!(v.is_some(), "expected Some, got None");
        assert!((v.unwrap() - 10.0).abs() < 1e-9);
    }

    #[test]
    fn read_f64_returns_none_for_missing_key() {
        let dir = TempDir::new().unwrap();
        let path = write_yaml(&dir, "council:\n  max_calls: 5\n");
        let v = read_nested_f64_in_freedom(&path, "council.daily_usd_cap");
        assert!(v.is_none(), "expected None for missing key");
    }

    #[test]
    fn format_cap_strips_dot_zero_for_whole() {
        assert_eq!(format_cap_f64(10.0), "10");
        assert_eq!(format_cap_f64(0.0), "0");
        assert_eq!(format_cap_f64(100.0), "100");
    }

    #[test]
    fn format_cap_preserves_fractional() {
        assert_eq!(format_cap_f64(10.5), "10.5");
        assert_eq!(format_cap_f64(3.75), "3.75");
    }

    // ── FIX 2 / FIX 3 tests — Null write deserialized as YAML null ─────────

    #[test]
    fn null_write_round_trips_as_yaml_null() {
        let dir = TempDir::new().unwrap();
        let path = dir.path().join("freedom.yaml");
        // Write Null to a key; read back and verify it is YAML null / absent.
        set_nested_test(&path, "persona_mode", serde_yaml::Value::Null).unwrap();
        let body = std::fs::read_to_string(&path).unwrap();
        let root: serde_yaml::Value = serde_yaml::from_str(&body).unwrap();
        // serde_yaml::Value::Null means Option<T> deserializes as None.
        let node = root.get("persona_mode");
        // Either the key is absent or its value is Null — both are valid representations.
        let is_null_or_absent = node.is_none_or(|v| v.is_null());
        assert!(is_null_or_absent, "expected null or absent, got {:?}", node);
    }

    #[test]
    fn null_write_for_obsidian_sync_is_yaml_null() {
        let dir = TempDir::new().unwrap();
        let path = dir.path().join("freedom.yaml");
        set_nested_test(&path, "obsidian_auto_sync_secs", serde_yaml::Value::Null).unwrap();
        let body = std::fs::read_to_string(&path).unwrap();
        let root: serde_yaml::Value = serde_yaml::from_str(&body).unwrap();
        let node = root.get("obsidian_auto_sync_secs");
        let is_null_or_absent = node.is_none_or(|v| v.is_null());
        assert!(is_null_or_absent, "expected null or absent, got {:?}", node);
    }
}

/// Per-process-unique sibling temp path for an atomic credentials write
/// (GOLD-SEC-15 / A-34) — mirrors the daemon helper.
#[cfg(unix)]
fn atomic_tmp_path(path: &Path) -> std::path::PathBuf {
    let name = path
        .file_name()
        .and_then(|n| n.to_str())
        .unwrap_or("credentials.yaml");
    path.with_file_name(format!(".{name}.tmp{}", std::process::id()))
}

#[cfg(unix)]
fn write_mode_0600(path: &Path, body: &[u8]) -> Result<()> {
    use std::io::Write;
    use std::os::unix::fs::OpenOptionsExt;
    // Atomic 0600 write: temp (mode 0600 at create) → write+fsync → rename
    // (GOLD-SEC-15 / A-34). Secrets are never on disk under a wider mode,
    // and a crash mid-write leaves the old file intact.
    let tmp = atomic_tmp_path(path);
    let _ = std::fs::remove_file(&tmp);
    let mut file = std::fs::OpenOptions::new()
        .create_new(true)
        .write(true)
        .mode(0o600)
        .open(&tmp)
        .with_context(|| format!("create {} mode 0600", tmp.display()))?;
    file.write_all(body)
        .with_context(|| format!("write body to {}", tmp.display()))?;
    file.sync_all()
        .with_context(|| format!("fsync {}", tmp.display()))?;
    drop(file);
    std::fs::rename(&tmp, path)
        .with_context(|| format!("atomically replace {}", path.display()))?;
    Ok(())
}

#[cfg(windows)]
fn write_mode_0600(path: &Path, body: &[u8]) -> Result<()> {
    use std::io::Write;
    let mut random = [0u8; 16];
    getrandom::getrandom(&mut random)
        .map_err(|error| anyhow::anyhow!("OS RNG unavailable for private temp name: {error}"))?;
    let name = path
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or("private");
    let tmp = path.with_file_name(format!(".{name}.{}.tmp", hex::encode(random)));
    let mut file = win_private::create_private_file_new(&tmp)
        .with_context(|| format!("secure create {}", tmp.display()))?;
    file.write_all(body)
        .with_context(|| format!("write body to {}", tmp.display()))?;
    file.flush()
        .with_context(|| format!("flush {}", tmp.display()))?;
    file.sync_all()
        .with_context(|| format!("fsync {}", tmp.display()))?;
    if let Err(error) = win_private::replace_private_file_handle(&file, path) {
        drop(file);
        let _ = std::fs::remove_file(&tmp);
        return Err(error).with_context(|| format!("atomically replace {}", path.display()));
    }
    Ok(())
}

/// Wall-clock HH:MM:SS for chat bubble timestamps. Pure GUI display —
/// the daemon owns the canonical PROVIDER_REQUEST timestamp in the
/// WAL; this string just gives the operator a local read-receipt
/// next to their bubble. R2-P0-1 (2026-05-22): chat_via_subprocess
/// dispatches to `neothd chat` so the bubble round-trip now hits
/// the real provider + WAL + permission gates.
fn format_now_hms() -> String {
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| i64::try_from(d.as_secs()).unwrap_or(i64::MAX))
        .unwrap_or(0);
    format_unix_hms(now)
}

fn format_unix_hms(ts_unix: i64) -> String {
    let seconds = ts_unix.rem_euclid(24 * 60 * 60);
    let s = seconds % 60;
    let m = (seconds / 60) % 60;
    let h = seconds / 3600;
    format!("{h:02}:{m:02}:{s:02}")
}

/// G-6 fix — every subprocess we spawn against the `neothd` binary
/// MUST opt out of ANSI colour output. Without these env vars
/// tracing-subscriber emits `[2m...[0m` escape sequences into stdout,
/// which then surface verbatim in GUI text widgets (FooterBar,
/// hardware summary, kanban session summary). Centralised here so
/// every call site stays consistent.
fn suppress_console_window(command: &mut std::process::Command) {
    #[cfg(windows)]
    {
        use std::os::windows::process::CommandExt;
        const CREATE_NO_WINDOW: u32 = 0x0800_0000;
        command.creation_flags(CREATE_NO_WINDOW);
    }
    #[cfg(not(windows))]
    let _ = command;
}

const TERMINAL_READY_FILE_ENV: &str = "NEOTH_READY_FILE";
const TERMINAL_READY_TOKEN_ENV: &str = "NEOTH_READY_TOKEN";
const INTERFACE_OVERRIDE_ENV: &str = "NEOTH_INTERFACE";

/// Launcher and one-shot transaction variables are capabilities, not ambient
/// configuration. Every unrelated child starts with them explicitly removed;
/// terminal launchers add only their fresh Ready pair back afterwards.
fn scrub_gui_control_environment(command: &mut std::process::Command) {
    for variable in [
        GUI_READY_FILE_ENV,
        GUI_READY_TOKEN_ENV,
        GUI_PARENT_COMMIT_ENV,
        PRODUCT_LAUNCHER_ENV,
        TERMINAL_READY_FILE_ENV,
        TERMINAL_READY_TOKEN_ENV,
        INTERFACE_OVERRIDE_ENV,
    ] {
        command.env_remove(variable);
    }
}

/// Char-boundary-safe prefix — never slices mid-codepoint. WS-BUG P0:
/// byte-index slices (`&s[..N]`) panicked the Slint UI thread on
/// non-ASCII input (emoji/CJK/umlaut) where byte N fell inside a
/// multi-byte sequence.
fn truncate_chars(s: &str, max_chars: usize) -> &str {
    match s.char_indices().nth(max_chars) {
        Some((i, _)) => &s[..i],
        None => s,
    }
}

fn spawn_neothd_plain(bin: &Path) -> std::process::Command {
    let mut cmd = std::process::Command::new(bin);
    scrub_gui_control_environment(&mut cmd);
    cmd.env("NO_COLOR", "1")
        .env("RUST_LOG_STYLE", "never")
        .env("CLICOLOR", "0")
        // A parent launcher token is single-purpose. GUI-internal daemon
        // subprocesses must never inherit authority to acknowledge startup.
        // CRITICAL for stdout parsing: the daemon's `init_tracing` writes
        // tracing events (incl. the `INFO neothd: Neoth ready. Sup.`
        // startup banner) to STDOUT, not stderr. At the default
        // `info,neothd=debug` level those lines would prepend the
        // machine-readable JSON / streamed chat deltas every GUI
        // subprocess parses — corrupting `serde_json::from_slice` and the
        // `gui-stream` NDJSON channel alike. `error` suppresses the
        // banner + info/debug noise so stdout carries only the payload.
        // Genuine clap/anyhow failures still surface on stderr + via exit
        // code, so the GUI's error handling is unaffected.
        .env("NEOTH_LOG", "error");
    suppress_console_window(&mut cmd);
    cmd
}

/// Configure the two GUI-owned chat entry points identically before either
/// may spawn. `incognito` is a request-bound snapshot, never a late read of a
/// mutable widget property, so the CLI remains the sole privacy authority for
/// the launched turn.
fn configure_gui_chat_launch_args(command: &mut std::process::Command, incognito: bool) {
    command.arg("chat").arg("--stream");
    if incognito {
        command.arg("--incognito");
    }
    command
        .arg("--gui-launch-envelope-stdin")
        .stdin(std::process::Stdio::piped());
}

fn append_chat_prompt_args(
    command: &mut std::process::Command,
    explicit_skill_id: Option<&str>,
    body: &str,
) {
    if let Some(skill_id) = explicit_skill_id {
        command.arg("--skill").arg(skill_id);
    }
    command.arg("--").arg(body);
}

fn channel_credential_command(bin: &Path) -> std::process::Command {
    let mut command = spawn_neothd_plain(bin);
    command
        .arg("channel")
        .arg("set-credentials")
        .arg("--output")
        .arg("json")
        .stdin(std::process::Stdio::piped())
        .stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::piped());
    command
}

fn channel_remove_command(bin: &Path, channel: &str) -> std::process::Command {
    let mut command = spawn_neothd_plain(bin);
    command
        .arg("channel")
        .arg("remove")
        .arg(channel)
        .arg("--output")
        .arg("json");
    command
}

/// Send channel credentials through the child's private stdin. The body is
/// zeroized on every return and unwind path, including lookup/spawn failures.
fn persist_channel_credentials_via_cli(
    body: zeroize::Zeroizing<Vec<u8>>,
) -> Result<std::process::Output, String> {
    use std::io::Write as _;

    let child_result = (|| {
        let bin = which_neothd()
            .ok_or_else(|| "NEOTH CLI not found; reinstall or repair PATH".to_string())?;
        let mut child = channel_credential_command(&bin)
            .spawn()
            .map_err(|error| format!("start private channel credential update: {error}"))?;
        let write_result = child
            .stdin
            .take()
            .ok_or_else(|| "open private channel credential stdin".to_string())
            .and_then(|mut stdin| {
                stdin
                    .write_all(body.as_slice())
                    .map_err(|error| format!("write private channel credential stdin: {error}"))
            });
        if let Err(error) = write_result {
            let _ = child.kill();
            let _ = child.wait();
            return Err(error);
        }
        Ok(child)
    })();
    drop(body);
    child_result?
        .wait_with_output()
        .map_err(|error| format!("wait for private channel credential update: {error}"))
}

/// Run `neothd kanban list/show --output json` + group tasks by status.
/// Returns an empty snapshot with a friendly summary when the operator
/// hasn't opened a coding session yet, OR when the daemon binary is
/// missing — the GUI degrades gracefully instead of erroring out.
/// GR-10 — fetch the daemon's safety-rail state via `neoth security safe-mode
/// --json`. Returns an empty snapshot when the binary is absent or the call
/// fails (the panel renders a "no data" state, never crashes). The PARSE is the
/// unit-tested `panel_logic::parse_safe_mode`; this is the thin subprocess shell.
fn fetch_safe_mode_snapshot() -> panel_logic::SafeModeSnapshot {
    let Some(bin) = which_neothd() else {
        return panel_logic::SafeModeSnapshot::default();
    };
    match spawn_neothd_plain(&bin)
        .arg("security")
        .arg("safe-mode")
        .arg("--json")
        .output()
    {
        Ok(o) if o.status.success() => {
            panel_logic::parse_safe_mode(&String::from_utf8_lossy(&o.stdout))
        }
        _ => panel_logic::SafeModeSnapshot::default(),
    }
}

/// Run a read-only `neothd <args…>` probe; return combined stdout/stderr (or a
/// friendly error). Backs the Agents / Automation tabs (off the UI thread).
fn run_neothd_probe(args: &[&str]) -> String {
    match which_neothd().and_then(|bin| {
        let mut c = spawn_neothd_plain(&bin);
        for a in args {
            c.arg(a);
        }
        c.output().ok()
    }) {
        Some(o) => {
            let mut s = String::from_utf8_lossy(&o.stdout).to_string();
            let err = String::from_utf8_lossy(&o.stderr);
            if !err.trim().is_empty() {
                s.push('\n');
                s.push_str(&err);
            }
            if s.trim().is_empty() {
                "(no output)".to_string()
            } else {
                s
            }
        }
        None => "neothd binary not on PATH.".to_string(),
    }
}

// ADOPT31-D2 reads the cost rollup from a daemon subprocess, an untrusted I/O
// boundary even though the binary was resolved locally.  `Command::output()`
// would buffer arbitrarily large stdout/stderr before the JSON parser gets its
// 1 MiB limit, so usage probes have their own bounded capture and deadline.
fn wait_for_usage_refresh(
    cancellation: &trusted_probe_supervisor::ProbeCancellation,
    duration: std::time::Duration,
) -> bool {
    let Some(deadline) = std::time::Instant::now().checked_add(duration) else {
        cancellation.cancel();
        return false;
    };
    while std::time::Instant::now() < deadline {
        if cancellation.is_cancelled()
            || !D2_USAGE_WINDOW_LIVE.load(std::sync::atomic::Ordering::Acquire)
        {
            cancellation.cancel();
            return false;
        }
        let remaining = deadline.saturating_duration_since(std::time::Instant::now());
        std::thread::sleep(remaining.min(std::time::Duration::from_millis(100)));
    }
    true
}

/// Run one read-only dashboard JSON probe with a hard stdout/stderr budget and a
/// short deadline through the owned, platform-aware probe supervisor.
fn run_bounded_dashboard_json_probe(
    args: &[&str],
    cancellation: &trusted_probe_supervisor::ProbeCancellation,
) -> std::result::Result<String, &'static str> {
    use trusted_probe_supervisor::run as run_trusted_probe;

    let Some(bin) = which_trusted_usage_neothd() else {
        return Err("daemon not found");
    };
    let mut command = spawn_neothd_plain(&bin);
    // The call sites below are internal literals plus decimal timestamps; this
    // guard makes an accidental future reuse with a different command fail
    // closed before any subprocess is launched.
    let exact_dashboard_json = match args {
        ["meter", "--format", "json"]
        | ["cost", "top-sessions", "--output", "json"]
        | ["usage", "--format", "json", "--days", "1"] => true,
        [
            "usage",
            "--since-unix",
            since,
            "--until-unix",
            until,
            "--format",
            "json",
        ] => since
            .parse::<u64>()
            .ok()
            .zip(until.parse::<u64>().ok())
            .is_some_and(|(since, until)| since <= until),
        _ => false,
    };
    if !exact_dashboard_json {
        return Err("dashboard probe command rejected");
    }
    command.args(args);
    let policy = trusted_probe_supervisor::fixed_usage_probe_policy();
    let output = run_trusted_probe(&mut command, policy, cancellation)
        .map_err(|error| error.as_static_message())?;
    String::from_utf8(output.stdout).map_err(|_| "dashboard probe returned non-UTF-8 JSON")
}

/// Build the argv for a live, proposal-bound SourceEdit apply.
///
/// The caller validates every dynamic value before invoking the executable.
/// Keep the proposal ID and expected digest in this same argument vector: the
/// CLI uses the pair to consume exactly the accepted proposal receipt before
/// any source mutation is allowed.
fn source_edit_apply_args<'a>(
    proposal_id: &'a str,
    patch_path: &'a str,
    sha256: &'a str,
) -> [&'a str; 8] {
    [
        "self-edit",
        "--diff",
        patch_path,
        "--yes",
        "--proposal-id",
        proposal_id,
        "--expect-hash",
        sha256,
    ]
}

/// Execute one GUI-triggered CLI action through the structured automation
/// contract. A successful exit without a valid typed acknowledgement is still
/// a failure; callers must additionally verify action-specific fields.
fn run_neothd_json_action<T>(args: &[&str], action: &str) -> std::result::Result<T, String>
where
    T: serde::de::DeserializeOwned,
{
    let mut command = neothd_json_command(args)?;
    gui_action::run_json(&mut command, action)
}

fn fetch_dream_cron_status() -> std::result::Result<gui_action::DreamStatusAck, String> {
    let status = run_neothd_json_action::<gui_action::DreamStatusAck>(
        &["dream", "status"],
        "Read Dream cron status",
    )?;
    status.verify()?;
    Ok(status)
}

fn mutate_dream_cron_with<Mutate, Readback>(
    enabled: bool,
    mutate: Mutate,
    readback: Readback,
) -> std::result::Result<(gui_action::DreamCronAck, gui_action::DreamStatusAck), String>
where
    Mutate: FnOnce(bool) -> std::result::Result<gui_action::DreamCronAck, String>,
    Readback: FnOnce() -> std::result::Result<gui_action::DreamStatusAck, String>,
{
    let receipt = mutate(enabled)?;
    receipt.verify(enabled)?;
    let status = readback()?;
    status.verify()?;
    if !status.config_present
        || status.cron_enabled != enabled
        || status.config_path != receipt.config_path
        || status.autonomy != receipt.autonomy
        || status.autonomy_allows_scheduler != receipt.autonomy_allows_scheduler
    {
        return Err(
            "Dream cron mutation was acknowledged, but canonical readback did not match it"
                .to_string(),
        );
    }
    Ok((receipt, status))
}

fn mutate_dream_cron(
    enabled: bool,
) -> std::result::Result<(gui_action::DreamCronAck, gui_action::DreamStatusAck), String> {
    // Serialize with every other GUI freedom.yaml writer. The CLI owns the
    // cross-process atomic mutation and canonical legacy-key normalization.
    let _guard = FREEDOM_WRITE_LOCK
        .lock()
        .unwrap_or_else(|poison| poison.into_inner());
    mutate_dream_cron_with(
        enabled,
        |desired| {
            let action = if desired { "enable" } else { "disable" };
            run_neothd_json_action::<gui_action::DreamCronAck>(
                &["dream", "cron", action],
                "Change Dream cron",
            )
        },
        fetch_dream_cron_status,
    )
}

fn persist_wizard_dream_cron(enabled: bool) -> Result<gui_action::DreamStatusAck> {
    let (_, status) = mutate_dream_cron(enabled)
        .map_err(anyhow::Error::msg)
        .context("persist and verify the GUI Dream cron choice")?;
    Ok(status)
}

fn apply_dream_cron_status(window: &MainWindow, status: gui_action::DreamStatusAck) {
    window.set_dream_cron_enabled(status.cron_enabled);
    window.set_dream_cron_config_present(status.config_present);
    window.set_dream_cron_status_verified(true);
    window.set_dream_cron_status_error("".into());
    window.set_dream_cron_scheduler_state(status.scheduler_state.into());
    window.set_dream_cron_autonomy(status.autonomy.into());
    window.set_dream_cron_schedule(format!("{} {}", status.cron_at, status.timezone).into());
}

fn start_dream_cron_refresh(weak: slint::Weak<MainWindow>, announce: bool) {
    if DREAM_CRON_OPERATION_ACTIVE.swap(true, std::sync::atomic::Ordering::AcqRel) {
        if announce {
            push_toast(
                &weak,
                "info",
                "Dream status read in progress",
                "Wait for the current verified readback to finish.",
            );
        }
        return;
    }
    let revision = DREAM_CRON_UI_REVISION
        .fetch_add(1, std::sync::atomic::Ordering::AcqRel)
        .wrapping_add(1);
    if let Some(window) = weak.upgrade() {
        window.set_dream_cron_operation_in_flight(true);
        if announce {
            window.set_status_line("Refreshing verified Dream cron state…".into());
        }
    }
    std::thread::spawn(move || {
        let result = fetch_dream_cron_status();
        DREAM_CRON_OPERATION_ACTIVE.store(false, std::sync::atomic::Ordering::Release);
        let _ = slint::invoke_from_event_loop(move || {
            if DREAM_CRON_UI_REVISION.load(std::sync::atomic::Ordering::Acquire) != revision {
                return;
            }
            let Some(window) = weak.upgrade() else {
                return;
            };
            window.set_dream_cron_operation_in_flight(false);
            match result {
                Ok(status) => {
                    apply_dream_cron_status(&window, status);
                    if announce {
                        window.set_status_line("Dream cron state refreshed and verified.".into());
                    }
                }
                Err(error) => {
                    window.set_dream_cron_status_verified(false);
                    window.set_dream_cron_status_error(error.clone().into());
                    window.set_status_line(format!("Dream cron status failed: {error}").into());
                }
            }
        });
    });
}

fn start_dream_cron_mutation(weak: slint::Weak<MainWindow>, enabled: bool) {
    if DREAM_CRON_OPERATION_ACTIVE.swap(true, std::sync::atomic::Ordering::AcqRel) {
        push_toast(
            &weak,
            "info",
            "Dream operation in progress",
            "Wait for the current verified Dream operation to finish.",
        );
        return;
    }
    let revision = DREAM_CRON_UI_REVISION
        .fetch_add(1, std::sync::atomic::Ordering::AcqRel)
        .wrapping_add(1);
    if let Some(window) = weak.upgrade() {
        window.set_dream_cron_operation_in_flight(true);
        window.set_dream_cron_status_verified(false);
        window.set_dream_cron_status_error(
            "A Dream cron change is awaiting persistence, reload, and readback.".into(),
        );
        window.set_status_line("Applying and verifying Dream cron state…".into());
    }
    std::thread::spawn(move || {
        let result = mutate_dream_cron(enabled);
        DREAM_CRON_OPERATION_ACTIVE.store(false, std::sync::atomic::Ordering::Release);
        let _ = slint::invoke_from_event_loop(move || {
            if DREAM_CRON_UI_REVISION.load(std::sync::atomic::Ordering::Acquire) != revision {
                return;
            }
            let Some(window) = weak.upgrade() else {
                return;
            };
            window.set_dream_cron_operation_in_flight(false);
            match result {
                Ok((_receipt, status)) => {
                    let blocked = status.cron_enabled && !status.autonomy_allows_scheduler;
                    let autonomy = status.autonomy.clone();
                    apply_dream_cron_status(&window, status);
                    // A day-two mutation becomes the next wizard re-entry
                    // draft. Read-only refreshes never touch that draft, so a
                    // late startup probe cannot undo an onboarding click.
                    window.set_wizard_dream_cron_enabled(enabled);
                    if blocked {
                        window.set_status_line(
                            format!(
                                "Dream cron is configured ON and reload was requested, but autonomy `{autonomy}` keeps unattended scheduling blocked."
                            )
                            .into(),
                        );
                        push_toast(
                            &weak,
                            "info",
                            "Dream cron saved but blocked",
                            "Strict and Custom do not permit unattended scheduling.",
                        );
                    } else {
                        window.set_status_line(
                            format!(
                                "Dream cron {} was persisted, reload requested, and read back.",
                                if enabled { "enable" } else { "disable" }
                            )
                            .into(),
                        );
                        push_toast(
                            &weak,
                            "success",
                            "Dream cron",
                            "Saved, reload requested, and verified.",
                        );
                    }
                }
                Err(error) => {
                    window.set_dream_cron_status_verified(false);
                    window.set_dream_cron_status_error(error.clone().into());
                    window.set_status_line(format!("Dream cron change failed: {error}").into());
                    push_toast(
                        &weak,
                        "warn",
                        "Dream cron change failed",
                        "No unverified state was published; refresh and retry.",
                    );
                }
            }
        });
    });
}

fn run_neothd_json_action_with_private_stdin<T>(
    args: &[&str],
    action: &str,
    stdin_body: &mut [u8],
) -> std::result::Result<T, String>
where
    T: serde::de::DeserializeOwned,
{
    let mut command = neothd_json_command(args)?;
    gui_action::run_json_with_private_stdin(&mut command, action, stdin_body)
}

fn now_unix_secs() -> std::result::Result<u64, String> {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|duration| duration.as_secs())
        .map_err(|error| format!("system clock is before the Unix epoch: {error}"))
}

fn preflight_chat_consent_verified()
-> std::result::Result<gui_action::VerifiedConsentChatPreflight, String> {
    let acknowledgement = run_neothd_json_action::<gui_action::ConsentChatPreflightAck>(
        &["consent", "preflight-chat", "--source", "gui"],
        "Chat consent preflight",
    )?;
    acknowledgement.verify(now_unix_secs()?)
}

fn decide_chat_consent_verified(
    mut preflight: gui_action::VerifiedConsentChatPreflight,
    decision: &str,
) -> std::result::Result<gui_action::VerifiedConsentChatDecision, String> {
    let challenge_id = preflight
        .challenge_id
        .clone()
        .ok_or_else(|| "chat consent preflight omitted its challenge id".to_string())?;
    let mut challenge_token = preflight
        .challenge_token
        .take()
        .ok_or_else(|| "chat consent preflight omitted its private challenge token".to_string())?;
    let args = [
        "consent",
        "decide-chat",
        "--challenge-id",
        challenge_id.as_str(),
        "--decision",
        decision,
        "--source",
        "gui",
    ];
    let acknowledgement =
        run_neothd_json_action_with_private_stdin::<gui_action::ConsentChatDecisionAck>(
            &args,
            "Chat consent decision",
            challenge_token.as_mut_slice(),
        )?;
    acknowledgement.verify(&preflight, decision, now_unix_secs()?)
}

fn consent_route_summary(routes: &[gui_action::ConsentRouteBinding]) -> String {
    routes
        .iter()
        .map(|route| match route.endpoint_origin.as_deref() {
            Some(origin) => format!("{} @ {origin}", route.provider),
            None => route.provider.clone(),
        })
        .collect::<Vec<_>>()
        .join("\n")
}

fn spawn_chat_stderr_reader<F>(
    stderr: std::process::ChildStderr,
    on_diagnostic: F,
) -> std::thread::JoinHandle<String>
where
    F: Fn(String) + Send + 'static,
{
    std::thread::spawn(move || {
        use std::io::BufRead as _;

        const MAX_CAPTURED_CHARS: usize = 8_192;
        let mut captured = String::new();
        for line in std::io::BufReader::new(stderr).lines() {
            let Ok(line) = line else {
                break;
            };
            let Some(diagnostic) = gui_action::operator_diagnostic(line.as_bytes()) else {
                continue;
            };
            on_diagnostic(diagnostic.clone());
            if captured.chars().count() < MAX_CAPTURED_CHARS {
                if !captured.is_empty() {
                    captured.push('\n');
                }
                let remaining = MAX_CAPTURED_CHARS.saturating_sub(captured.chars().count());
                captured.extend(diagnostic.chars().take(remaining));
            }
        }
        captured
    })
}

fn with_chat_diagnostic(base: impl Into<String>, diagnostic: &str) -> String {
    let base = base.into();
    let diagnostic = diagnostic.trim();
    if diagnostic.is_empty() || base.contains(diagnostic) {
        base
    } else {
        format!("{base}\n{diagnostic}")
    }
}

/// Keep Buddy's EOF-without-`done` outcome as informative as the Main chat
/// surface: the stream is still failed, but an already rendered provider body
/// remains recoverable in the terminal error instead of being discarded.
fn buddy_incomplete_stream_message(exit_code: i32, partial_reply: &str) -> String {
    let base = format!("Buddy chat stream ended before completion (exit {exit_code}).");
    if partial_reply.trim().is_empty() {
        base
    } else {
        format!("{base} Partial reply:\n\n{partial_reply}")
    }
}

