/// Install or explicitly replace a skill through the typed CLI receipt. The
/// caller owns the human confirmation before setting `force`; no GUI path may
/// silently turn an ordinary install into destructive replacement.
fn inspect_skill_install_from_gui(
    source: &std::path::Path,
) -> std::result::Result<gui_action::VerifiedSkillInstallPreflight, String> {
    let source_text = source.to_string_lossy();
    let target_skills_dir = neothd::skills::installer::default_skills_dir();
    run_neothd_json_action::<gui_action::SkillInstallPreflightAck>(
        &["skills", "--inspect-install", source_text.as_ref()],
        "Skill install preflight",
    )
    .and_then(|ack| ack.verify_source(source, &target_skills_dir))
}

fn inspect_skill_target_from_gui(
    id: &str,
) -> std::result::Result<gui_action::VerifiedSkillTargetPreflight, String> {
    let target_skills_dir = neothd::skills::installer::default_skills_dir();
    run_neothd_json_action::<gui_action::SkillTargetPreflightAck>(
        &["skills", "--inspect-target", id],
        "Skill target preflight",
    )
    .and_then(|ack| ack.verify_target(&target_skills_dir, id))
}

#[derive(Debug, PartialEq, Eq)]
enum SkillUninstallDispatch<T> {
    Cancelled,
    Executed(T),
}

/// Keep a declined exact-generation uninstall distinct from a failed
/// mutation. The dispatch closure is deliberately never evaluated on cancel,
/// so neither the CLI mutation nor its post-mutation inventory refresh runs.
fn dispatch_confirmed_skill_uninstall<T>(
    confirmed: bool,
    dispatch: impl FnOnce() -> T,
) -> SkillUninstallDispatch<T> {
    if confirmed {
        SkillUninstallDispatch::Executed(dispatch())
    } else {
        SkillUninstallDispatch::Cancelled
    }
}

fn skill_uninstall_cli_args(id: &str, generation_sha256: &str) -> Vec<String> {
    vec![
        "skills".to_string(),
        "--uninstall".to_string(),
        id.to_string(),
        "--expected-uninstall-id".to_string(),
        id.to_string(),
        "--expected-uninstall-generation-sha256".to_string(),
        generation_sha256.to_string(),
    ]
}

fn skill_create_cli_args(
    id: &str,
    description: &str,
    keywords: &str,
    system_prompt: &str,
    preflight: &gui_action::VerifiedSkillTargetPreflight,
    replacement_authorized: bool,
) -> Vec<String> {
    let mut args = vec![
        "skills".to_string(),
        "--create".to_string(),
        "--non-interactive".to_string(),
        "--create-id".to_string(),
        id.to_string(),
        "--create-description".to_string(),
        description.to_string(),
        "--create-system-prompt".to_string(),
        system_prompt.to_string(),
        "--expected-create-id".to_string(),
        preflight.id.clone(),
        "--expected-create-target-generation-sha256".to_string(),
        preflight
            .target_generation_sha256
            .clone()
            .unwrap_or_else(|| "absent".to_string()),
    ];
    if replacement_authorized {
        args.push("--force".to_string());
    }
    if !keywords.is_empty() {
        args.push("--create-keywords".to_string());
        args.push(keywords.to_string());
    }
    args
}

fn skill_install_cli_args(
    source: &str,
    preflight: &gui_action::VerifiedSkillInstallPreflight,
    replacement_authorized: bool,
) -> std::result::Result<Vec<String>, String> {
    if preflight.replacing_existing != replacement_authorized {
        return Err(if preflight.replacing_existing {
            format!(
                "skill `{}` requires explicit replacement confirmation",
                preflight.id
            )
        } else {
            format!(
                "skill `{}` was not a replacement during preflight; refusing an unbound --force",
                preflight.id
            )
        });
    }
    let mut args = vec![
        "skills".to_string(),
        "--install".to_string(),
        source.to_string(),
        "--expected-id".to_string(),
        preflight.id.clone(),
        "--expected-generation-sha256".to_string(),
        preflight.source_generation_sha256.clone(),
        "--expected-target-generation-sha256".to_string(),
        preflight
            .target_generation_sha256
            .clone()
            .unwrap_or_else(|| "absent".to_string()),
    ];
    if replacement_authorized {
        args.push("--force".to_string());
    }
    Ok(args)
}

fn install_skill_from_gui(
    source: &str,
    preflight: &gui_action::VerifiedSkillInstallPreflight,
    replacement_authorized: bool,
) -> std::result::Result<gui_action::VerifiedSkillInstall, String> {
    let args = skill_install_cli_args(source, preflight, replacement_authorized)?;
    let args = args.iter().map(String::as_str).collect::<Vec<_>>();
    run_neothd_json_action::<gui_action::SkillInstallAck>(&args, "Skill install").and_then(|ack| {
        let expected_install_dir = neothd::config::FreedomConfig::default_neoth_home()
            .join("skills")
            .join(&preflight.id);
        ack.verify_and_read_back(
            &preflight.id,
            &preflight.source_manifest_sha256,
            &preflight.source_generation_sha256,
            preflight.target_generation_sha256.as_deref(),
            &expected_install_dir,
            replacement_authorized,
        )
    })
}

/// Tolerant `autonomy show --output json` snapshot for post-mutation readback.
/// A query surface may grow fields, so this deliberately skips
/// `deny_unknown_fields`; the mutation acks stay exact.
#[derive(Debug, serde::Deserialize)]
struct AutonomyShowSnapshot {
    mode: String,
    autonomy: String,
}

/// Re-load freedom.yaml through the CLI and confirm the persisted state
/// matches what the mutation acknowledged. `expected_mode: None` for raw
/// level sets — their mode label also depends on the skill-breadth flag.
fn read_back_autonomy(
    expected_mode: Option<&str>,
    expected_level: &str,
) -> std::result::Result<(), String> {
    let snap =
        run_neothd_json_action::<AutonomyShowSnapshot>(&["autonomy", "show"], "Autonomy readback")?;
    if let Some(mode) = expected_mode
        && snap.mode != mode
    {
        return Err(format!(
            "autonomy readback reports mode `{}`, expected `{mode}` — freedom.yaml did not settle",
            snap.mode
        ));
    }
    if snap.autonomy != expected_level {
        return Err(format!(
            "autonomy readback reports level `{}`, expected `{expected_level}` — freedom.yaml did not settle",
            snap.autonomy
        ));
    }
    Ok(())
}

#[derive(Debug)]
struct VerifiedConsentMutation {
    provider: String,
    changed_origins: Vec<String>,
    audit_pending: bool,
}

impl VerifiedConsentMutation {
    fn success_message(&self, prefix: &str) -> String {
        let mut message = format!("{prefix} for `{}`.", self.provider);
        if !self.changed_origins.is_empty() {
            message.push_str(&format!(" Endpoints: {}.", self.changed_origins.join(", ")));
        }
        if self.audit_pending {
            message.push_str(" The durable audit record is queued for WAL delivery.");
        }
        message
    }
}

fn read_consent_ui_rows() -> std::result::Result<Vec<panel_logic::ConsentUiRow>, String> {
    let rows = run_neothd_json_action::<Vec<panel_logic::ConsentUiRow>>(
        &["consent", "list"],
        "Consent readback",
    )?;
    panel_logic::validate_consent_rows(&rows)?;
    Ok(rows)
}

fn read_consent_mutation_binding()
-> std::result::Result<gui_action::VerifiedConsentMutationBinding, String> {
    run_neothd_json_action::<gui_action::ConsentMutationBindingAck>(
        &["consent", "mutation-binding", "--source", "gui"],
        "Consent mutation binding",
    )
    .and_then(gui_action::ConsentMutationBindingAck::verify)
}

fn consent_ui_row(
    rows: &[panel_logic::ConsentUiRow],
    provider: &str,
) -> std::result::Result<panel_logic::ConsentUiRow, String> {
    rows.iter()
        .find(|row| row.provider == provider)
        .cloned()
        .ok_or_else(|| {
            format!("consent list has no configured or persisted row for provider `{provider}`")
        })
}

fn verify_consent_row_binding(
    expected: &panel_logic::ConsentUiRow,
    binding: &gui_action::VerifiedConsentMutationBinding,
) -> std::result::Result<(), String> {
    let provider_routes = binding
        .required_routes
        .iter()
        .filter(|route| route.provider == expected.provider)
        .collect::<Vec<_>>();
    if expected.consent_required == provider_routes.is_empty() {
        return Err(format!(
            "consent UI snapshot for `{}` no longer matches the bound required route set",
            expected.provider
        ));
    }

    let bound_origins = provider_routes
        .iter()
        .filter_map(|route| route.endpoint_origin.clone())
        .collect::<std::collections::BTreeSet<_>>();
    let expected_origins = expected
        .configured_endpoint_origins
        .iter()
        .cloned()
        .collect::<std::collections::BTreeSet<_>>();
    if bound_origins != expected_origins {
        return Err(format!(
            "consent UI snapshot for `{}` no longer matches its bound endpoint origins",
            expected.provider
        ));
    }

    let bound_current_grant = !provider_routes.is_empty()
        && provider_routes.iter().all(|route| {
            binding.readback.iter().any(|row| {
                row.provider == route.provider
                    && row.endpoint_origin == route.endpoint_origin
                    && row.granted
            })
        });
    if bound_current_grant != expected.current_route_granted {
        return Err(format!(
            "consent UI snapshot for `{}` no longer matches the bound grant readback",
            expected.provider
        ));
    }
    Ok(())
}

fn grant_consent_verified(provider: &str) -> std::result::Result<VerifiedConsentMutation, String> {
    let before = read_consent_ui_rows()?;
    let expected = consent_ui_row(&before, provider)?;
    if !expected.grantable && !expected.current_route_granted {
        return Err(format!(
            "provider `{provider}` is not grantable (status `{}`)",
            expected.status
        ));
    }
    let expected_origins = expected.configured_endpoint_origins.clone();
    let binding = read_consent_mutation_binding()?;
    verify_consent_row_binding(&expected, &binding)?;

    let args = [
        "consent",
        "grant",
        provider,
        "--source",
        "gui",
        "--expected-config-sha256",
        binding.config_sha256.as_str(),
        "--expected-route-set-sha256",
        binding.route_set_sha256.as_str(),
    ];
    let ack = run_neothd_json_action::<gui_action::ConsentGrantAck>(&args, "Consent grant")?;
    let verified = ack.verify(
        provider,
        &expected_origins,
        &expected.granted_endpoint_origins,
        expected.current_route_granted,
        &binding.config_sha256,
        &binding.route_set_sha256,
    )?;

    let after = read_consent_ui_rows()?;
    let current = consent_ui_row(&after, provider)?;
    if current.configured_endpoint_origins != expected_origins {
        return Err(format!(
            "consent readback for `{provider}` changed configured origins from {:?} to {:?}; refusing a stale success state",
            expected_origins, current.configured_endpoint_origins
        ));
    }
    if !current.current_route_granted {
        return Err(format!(
            "consent readback for `{provider}` does not grant the current route"
        ));
    }
    let expected_final: std::collections::BTreeSet<_> = expected
        .granted_endpoint_origins
        .iter()
        .chain(expected_origins.iter())
        .cloned()
        .collect();
    let current_final: std::collections::BTreeSet<_> =
        current.granted_endpoint_origins.iter().cloned().collect();
    if current_final != expected_final
        || verified
            .endpoint_origins
            .iter()
            .cloned()
            .collect::<std::collections::BTreeSet<_>>()
            != expected_final
    {
        return Err(format!(
            "consent readback for `{provider}` does not match the exact expected final origin set"
        ));
    }

    Ok(VerifiedConsentMutation {
        provider: provider.to_string(),
        changed_origins: verified.added_endpoint_origins,
        audit_pending: verified.audit_pending,
    })
}

fn revoke_consent_verified(provider: &str) -> std::result::Result<VerifiedConsentMutation, String> {
    // Revocation is an emergency authority-reduction path. It must remain
    // available even when freedom.yaml is corrupt/missing, so it intentionally
    // carries no config binding and relies on Core's exact marker/audit receipt.
    let args = ["consent", "revoke", provider, "--source", "gui"];
    let ack = run_neothd_json_action::<gui_action::ConsentRevokeAck>(&args, "Consent revoke")?;
    let verified = ack.verify_emergency(provider)?;

    // When config parsing still works, add the independent list readback. A
    // broken config cannot invalidate a successful, authority-free revoke ACK.
    if let Ok(after) = read_consent_ui_rows()
        && let Some(current) = after.iter().find(|row| row.provider == provider)
        && (current.current_route_granted
            || current.revokable
            || !current.granted_endpoint_origins.is_empty())
    {
        return Err(format!(
            "consent readback for `{provider}` still reports a persisted grant"
        ));
    }

    Ok(VerifiedConsentMutation {
        provider: provider.to_string(),
        changed_origins: verified.removed_endpoint_origins,
        audit_pending: verified.audit_pending,
    })
}

/// GR-RESID-D34 — mint the single-use, short-TTL FULL-AUTO token from the
/// live daemon through the typed boundary. The in-GUI confirm dialog IS the
/// consent; the token exists only to be passed straight back to the CLI.
fn mint_fullauto_token_verified() -> std::result::Result<String, String> {
    let ack = run_neothd_json_action::<gui_action::FullautoTokenAck>(
        &["autonomy", "mint-fullauto-token"],
        "Full-auto token mint",
    )?;
    ack.verify()?;
    Ok(ack.token)
}

/// GAP-09 / GR-RESID-D34 — the one FULL-AUTO ceremony: mint → `autonomy
/// full-auto` → verify the typed receipt → read the persisted state back.
/// Shared by the settings radio, the chat consent strip, and the FULL-AUTO
/// switch so no surface can drift to a weaker gate than the others.
fn enable_full_auto_verified() -> std::result::Result<(), String> {
    let token = mint_fullauto_token_verified()?;
    let ack = run_neothd_json_action::<gui_action::OperatingModeAck>(
        &[
            "autonomy",
            "full-auto",
            "--gui-confirmed",
            "--gui-token",
            &token,
        ],
        "Full-auto switch",
    )?;
    ack.verify_full_auto()?;
    read_back_autonomy(Some("full-auto"), "full")
}

/// Safe-direction switch to GATED, receipt-verified + read back. No
/// confirmation ceremony by design — lowering autonomy never needs one.
fn switch_to_gated_verified() -> std::result::Result<(), String> {
    let ack = run_neothd_json_action::<gui_action::OperatingModeAck>(
        &["autonomy", "gated"],
        "Gated switch",
    )?;
    ack.verify_gated()?;
    read_back_autonomy(Some("gated"), "standard")
}

/// Load one complete memory-graph snapshot through the typed GUI/CLI boundary.
/// Both refresh and export share this function so neither surface can accept a
/// success-looking partial graph that the other rejects.
fn fetch_memory_graph() -> std::result::Result<panel_logic::MemoryGraphWire, String> {
    let graph = run_neothd_json_action::<panel_logic::MemoryGraphWire>(
        &["memory", "--graph"],
        "Memory graph",
    )?;
    graph.verify()?;
    Ok(graph)
}

/// Convert the multiline cluster editors into exact string arrays. No trim is
/// applied: commas, case and intentional leading/trailing spaces are data.
/// Empty rows are ignored and exact duplicates collapse in first-seen order.
fn parse_exact_cluster_lines(raw: &str) -> Vec<String> {
    let mut seen = std::collections::HashSet::new();
    raw.lines()
        .filter(|line| !line.is_empty())
        .filter(|line| seen.insert((*line).to_string()))
        .map(str::to_string)
        .collect()
}

/// Refresh only non-secret cluster readiness/runtime fields. The CLI status
/// contract never returns the shared passphrase itself.
fn refresh_cluster_config_status(weak: slint::Weak<MainWindow>) {
    let revision = CLUSTER_UI_REVISION.load(std::sync::atomic::Ordering::Acquire);
    std::thread::spawn(move || {
        let result = run_neothd_json_action::<gui_action::ClusterStatusAck>(
            &["cluster", "status"],
            "Cluster status",
        );
        let _ = slint::invoke_from_event_loop(move || {
            if CLUSTER_UI_REVISION.load(std::sync::atomic::Ordering::Acquire) != revision {
                return;
            }
            let Some(window) = weak.upgrade() else {
                return;
            };
            match result {
                Ok(status) => {
                    if let Err(error) = status.validate() {
                        window.set_cfg_cluster_apply_status(
                            format!("Cluster readiness returned inconsistent state: {error}")
                                .into(),
                        );
                        return;
                    }
                    let runtime = status.runtime;
                    window.set_cfg_cluster_passphrase_set(runtime.cluster_passphrase_set);
                    window.set_cfg_cluster_replicate_raw_ingress(
                        runtime.gossip.replicate_raw_ingress,
                    );
                    window.set_cfg_cluster_replay_days_text(
                        runtime.gossip.replay_budget_days.to_string().into(),
                    );
                    let readiness = if runtime.transport_active {
                        format!(
                            "Runtime verified: {} Raw sync: {}; replay: {} days.",
                            runtime.transport,
                            if runtime.gossip.replicate_raw_ingress {
                                "on"
                            } else {
                                "off"
                            },
                            runtime.gossip.replay_budget_days
                        )
                    } else if runtime.restart_required {
                        format!(
                            "{} Restart required for carrier lifecycle; gossip policy reloads live.",
                            runtime.transport
                        )
                    } else {
                        runtime.transport
                    };
                    window.set_cfg_cluster_apply_status(readiness.into());
                }
                Err(error) => {
                    window.set_cfg_cluster_apply_status(
                        format!("Cluster readiness could not be verified: {error}").into(),
                    );
                }
            }
        });
    });
}

fn neothd_json_command(args: &[&str]) -> std::result::Result<std::process::Command, String> {
    let bin = which_neothd()
        .ok_or_else(|| "NEOTH CLI not found. Reinstall or repair PATH, then retry.".to_string())?;
    let mut command = spawn_neothd_plain(&bin);
    command.args(["--output", "json"]);
    command.args(args);
    Ok(command)
}

fn validate_neothd_probe_exit(
    subject: &str,
    success: bool,
    stderr: &[u8],
    code: Option<i32>,
) -> std::result::Result<(), String> {
    if success {
        return Ok(());
    }
    let diagnostic = String::from_utf8_lossy(stderr)
        .lines()
        .map(str::trim)
        .find(|line| !line.is_empty())
        .map(|line| line.chars().take(400).collect::<String>())
        .unwrap_or_else(|| "NEOTH CLI returned no diagnostic".to_string());
    let exit = code
        .map(|code| code.to_string())
        .unwrap_or_else(|| "?".to_string());
    Err(format!("{subject} failed (exit {exit}): {diagnostic}"))
}

/// The Buddy status command is read-only but still requires a successful
/// subprocess exit before its status snapshot may be parsed.
fn validate_buddy_exit(
    action: &str,
    success: bool,
    stderr: &[u8],
    code: Option<i32>,
) -> std::result::Result<(), String> {
    validate_neothd_probe_exit(&format!("Buddy {action}"), success, stderr, code)
}

fn fetch_buddy_status() -> std::result::Result<panel_logic::BuddyStatusSnap, String> {
    let bin = which_neothd().ok_or_else(|| {
        "NEOTH CLI not found. Reinstall or repair PATH, then refresh.".to_string()
    })?;
    let output = spawn_neothd_plain(&bin)
        .args(["--output", "json", "buddy", "status"])
        .output()
        .map_err(|error| format!("could not start NEOTH Buddy status probe: {error}"))?;
    validate_buddy_exit(
        "status probe",
        output.status.success(),
        &output.stderr,
        output.status.code(),
    )?;
    panel_logic::parse_buddy_status(&String::from_utf8_lossy(&output.stdout))
}

fn fetch_buddy_cluster_status() -> std::result::Result<panel_logic::BuddyClusterStatusSnap, String>
{
    let binary = which_neothd().ok_or_else(|| {
        "NEOTH CLI not found. Reinstall or repair PATH, then refresh.".to_string()
    })?;
    let output = spawn_neothd_plain(&binary)
        .args(["--output", "json", "buddy", "cluster", "status"])
        .output()
        .map_err(|error| format!("could not start Buddy cluster status probe: {error}"))?;
    validate_buddy_exit(
        "cluster status",
        output.status.success(),
        &output.stderr,
        output.status.code(),
    )?;
    panel_logic::parse_buddy_cluster_status(&String::from_utf8_lossy(&output.stdout))
}

fn fetch_buddy_revocation_status(
    request_id: &str,
) -> std::result::Result<neothd::cluster::membership::MembershipRevocationStatusEnvelope, String> {
    neothd::cluster::membership::validate_revocation_request_id(request_id)
        .map_err(|error| format!("invalid revocation request id: {error:#}"))?;
    let acknowledgement =
        run_neothd_json_action::<neothd::cluster::membership::MembershipRevocationStatusEnvelope>(
            &["buddy", "cluster", "revoke-status", request_id],
            "Buddy cluster revocation status",
        )?;
    acknowledgement
        .validate()
        .map_err(|error| format!("invalid durable revocation status: {error:#}"))?;
    if acknowledgement.request_id != request_id {
        return Err("durable revocation status is bound to a different request".into());
    }
    Ok(acknowledgement)
}

fn fetch_buddy_revocation_health()
-> std::result::Result<neothd::cluster::membership::MembershipRuntimeHealth, String> {
    let health = run_neothd_json_action::<neothd::cluster::membership::MembershipRuntimeHealth>(
        &["buddy", "cluster", "revoke-unresolved"],
        "Buddy unresolved revocations",
    )?;
    health
        .validate()
        .map_err(|error| format!("invalid membership runtime health: {error:#}"))?;
    Ok(health)
}

fn buddy_revocation_status_presentation(
    acknowledgement: &neothd::cluster::membership::MembershipRevocationStatusEnvelope,
) -> std::result::Result<(String, String, bool), String> {
    acknowledgement
        .validate()
        .map_err(|error| format!("invalid durable revocation status: {error:#}"))?;
    let Some(status) = acknowledgement.status.as_ref() else {
        return Ok((
            "not_found".into(),
            "No durable revocation intent exists for this UUIDv7 request.".into(),
            false,
        ));
    };
    let state = status.state.as_str().to_string();
    let detail = match status.state {
        neothd::cluster::membership::RevocationIntentState::Pending => format!(
            "Durable Pending intent; admission is closed while cancellation and external-effect classification finish. Tombstone committed={}.",
            status.tombstone_committed
        ),
        neothd::cluster::membership::RevocationIntentState::Indeterminate => format!(
            "Remote effect outcome requires reconciliation: {} Tombstone committed={}; receipt={}.",
            status.indeterminate_reason.as_deref().unwrap_or("unknown"),
            status.tombstone_committed,
            status.receipt_id.as_deref().unwrap_or("-")
        ),
        neothd::cluster::membership::RevocationIntentState::Completed => format!(
            "Revocation completed durably; tombstone committed and receipt {} recorded.",
            status.receipt_id.as_deref().unwrap_or("-")
        ),
        neothd::cluster::membership::RevocationIntentState::NotFound => {
            "Authority recorded that the requested membership target was not found.".into()
        }
    };
    Ok((
        state,
        detail,
        matches!(
            status.state,
            neothd::cluster::membership::RevocationIntentState::Pending
                | neothd::cluster::membership::RevocationIntentState::Indeterminate
        ),
    ))
}

fn buddy_revocation_health_presentation(
    health: &neothd::cluster::membership::MembershipRuntimeHealth,
) -> std::result::Result<Option<(String, String, String, bool)>, String> {
    health
        .validate()
        .map_err(|error| format!("invalid membership runtime health: {error:#}"))?;
    let Some(status) = health.unresolved_revocations.first() else {
        return Ok(None);
    };
    let acknowledgement = neothd::cluster::membership::MembershipRevocationStatusEnvelope::new(
        status.request_id.clone(),
        Some(status.clone()),
    )
    .map_err(|error| format!("invalid unresolved revocation status: {error:#}"))?;
    let (state, mut detail, unresolved) = buddy_revocation_status_presentation(&acknowledgement)?;
    if health.unresolved_revocations.len() > 1 {
        detail = format!(
            "{} unresolved durable revocation requests exist; showing the oldest. {detail}",
            health.unresolved_revocations.len()
        );
    }
    Ok(Some((status.request_id.clone(), state, detail, unresolved)))
}

fn publish_buddy_revocation_status(
    weak: slint::Weak<MainWindow>,
    request_id: String,
    result: std::result::Result<
        neothd::cluster::membership::MembershipRevocationStatusEnvelope,
        String,
    >,
) {
    let _ = slint::invoke_from_event_loop(move || {
        let Some(window) = weak.upgrade() else {
            return;
        };
        let current_request_id = window.get_bc_cluster_revocation_request_id().to_string();
        if !current_request_id.is_empty() && current_request_id != request_id {
            tracing::debug!(
                current_request_id = %current_request_id,
                stale_request_id = %request_id,
                "discarding stale Buddy revocation status"
            );
            return;
        }
        window.set_bc_cluster_revocation_request_id(request_id.into());
        match result.and_then(|status| {
            let presentation = buddy_revocation_status_presentation(&status)?;
            Ok((status, presentation))
        }) {
            Ok((_status, (state, detail, unresolved))) => {
                window.set_bc_cluster_revocation_state(state.into());
                window.set_bc_cluster_revocation_detail(detail.into());
                window.set_bc_cluster_revocation_unresolved(unresolved);
            }
            Err(error) => {
                window.set_bc_cluster_revocation_state("status_unavailable".into());
                window.set_bc_cluster_revocation_detail(
                    format!(
                        "{error} Destructive membership controls remain disabled; use Refresh to retry the authoritative Buddy health read."
                    )
                    .into(),
                );
                window.set_bc_cluster_revocation_unresolved(true);
            }
        }
    });
}

fn publish_buddy_revocation_health(
    weak: slint::Weak<MainWindow>,
    result: std::result::Result<neothd::cluster::membership::MembershipRuntimeHealth, String>,
) {
    let _ = slint::invoke_from_event_loop(move || {
        let Some(window) = weak.upgrade() else {
            return;
        };
        let current_request_id = window.get_bc_cluster_revocation_request_id().to_string();
        let current_state = window.get_bc_cluster_revocation_state().to_string();
        let presentation = result.and_then(|health| buddy_revocation_health_presentation(&health));
        let authoritative_unresolved = match &presentation {
            Ok(Some(_)) => Some(true),
            Ok(None) => Some(false),
            Err(_) => None,
        };
        if !buddy_revocation_health_may_replace(
            &current_request_id,
            &current_state,
            authoritative_unresolved,
        ) {
            return;
        }
        match presentation {
            Ok(Some((request_id, state, detail, unresolved))) => {
                window.set_bc_cluster_revocation_request_id(request_id.into());
                window.set_bc_cluster_revocation_state(state.into());
                window.set_bc_cluster_revocation_detail(detail.into());
                window.set_bc_cluster_revocation_unresolved(unresolved);
            }
            Ok(None) => {
                window.set_bc_cluster_revocation_state("none".into());
                window.set_bc_cluster_revocation_detail(
                    "No unresolved durable revocation requests.".into(),
                );
                window.set_bc_cluster_revocation_unresolved(false);
            }
            Err(error) => {
                window.set_bc_cluster_revocation_state("status_unavailable".into());
                window.set_bc_cluster_revocation_detail(
                    format!(
                        "{error} Destructive membership controls remain disabled; use Refresh to retry the authoritative Buddy health read."
                    )
                    .into(),
                );
                window.set_bc_cluster_revocation_unresolved(true);
            }
        }
    });
}

fn buddy_revocation_health_may_replace(
    current_request_id: &str,
    current_state: &str,
    authoritative_unresolved: Option<bool>,
) -> bool {
    if current_state == "submitting" {
        return false;
    }
    match authoritative_unresolved {
        Some(true) => true,
        Some(false) => current_request_id.is_empty(),
        None => true,
    }
}

fn next_membership_ui_revision() -> u64 {
    MEMBERSHIP_UI_REVISION
        .fetch_add(1, std::sync::atomic::Ordering::AcqRel)
        .wrapping_add(1)
}

fn apply_buddy_cluster_result(
    window: &MainWindow,
    result: std::result::Result<panel_logic::BuddyClusterStatusSnap, String>,
) {
    match result {
        Ok(snapshot) => {
            window.set_bc_cluster_summary(snapshot.summary.into());
            window.set_bc_cluster_pending_id(snapshot.pending_id.into());
            window.set_bc_cluster_revocable_id(snapshot.revocable_id.into());
            window.set_bc_cluster_revocable_state(snapshot.revocable_state.into());
            window.set_bc_cluster_snapshot_version(i32::from(snapshot.snapshot_version));
            window.set_bc_cluster_snapshot_digest(snapshot.snapshot_digest.into());
            window.set_bc_cluster_status_valid(true);
            window.set_bc_cluster_status_error("".into());
        }
        Err(error) => {
            // Preserve every last-known-good membership value and binding.
            window.set_bc_cluster_status_valid(false);
            window.set_bc_cluster_status_error(error.into());
        }
    }
}

fn publish_buddy_cluster_result(
    weak: slint::Weak<MainWindow>,
    revision: u64,
    result: std::result::Result<panel_logic::BuddyClusterStatusSnap, String>,
) {
    let _ = slint::invoke_from_event_loop(move || {
        if MEMBERSHIP_UI_REVISION.load(std::sync::atomic::Ordering::Acquire) != revision {
            return;
        }
        let Some(window) = weak.upgrade() else {
            return;
        };
        apply_buddy_cluster_result(&window, result);
    });
}

fn run_code_map_recall(
    explicit_root: &str,
    prompt: &str,
) -> std::result::Result<panel_logic::CodeMapRecallEnvelope, String> {
    let root_path = Path::new(explicit_root);
    if !root_path.is_dir() {
        return Err(format!(
            "Repository root does not exist or is not a directory: {explicit_root}"
        ));
    }
    let bin = which_neothd().ok_or_else(|| {
        "neothd binary not on PATH — repository recall is unavailable.".to_string()
    })?;
    let args = panel_logic::code_map_recall_args(prompt, explicit_root);
    let output = spawn_neothd_plain(&bin)
        .args(&args)
        .output()
        .map_err(|error| format!("Could not start repository recall: {error}"))?;
    if !output.status.success() {
        let stderr = String::from_utf8_lossy(&output.stderr);
        let detail = stderr.trim();
        return Err(if detail.is_empty() {
            format!("Repository recall exited with {}.", output.status)
        } else {
            format!("Repository recall failed: {detail}")
        });
    }
    let stdout = std::str::from_utf8(&output.stdout)
        .map_err(|error| format!("Repository recall returned non-UTF-8 JSON: {error}"))?;
    panel_logic::parse_code_map_recall(stdout)
        .map_err(|error| format!("Repository recall contract error: {error}"))
}

fn clear_code_map_recall_receipt(window: &MainWindow) {
    window.set_code_map_has_receipt(false);
    window.set_code_map_stale(false);
    window.set_code_map_truncated(false);
    window.set_code_map_canonical_root("".into());
    window.set_code_map_root_identity("".into());
    window.set_code_map_index_generation("".into());
    window.set_code_map_graph_generation("".into());
    window.set_code_map_hits(slint::ModelRc::new(slint::VecModel::from(Vec::<
        CodeMapHitRow,
    >::new())));
}

/// Central Buddy driver — the ONE place a GUI event becomes an orb reaction.
/// Every handler that wants the Buddy to react calls `buddy(&w, GuiActivity::X)`
/// instead of poking `set_buddy_mood` directly, so the orb's vocabulary stays
/// consistent (see `buddy_activity::GuiActivity`).
fn buddy(window: &MainWindow, activity: GuiActivity) {
    let (mood, caption) = activity.mood();
    window.set_buddy_mood(mood.into());
    window.set_buddy_caption(caption.into());
}

/// Completion captions can carry receipt data while mood selection remains on
/// the same audited `GuiActivity` bus. This never triggers another query.
fn buddy_with_caption(window: &MainWindow, activity: GuiActivity, caption: &str) {
    buddy(window, activity);
    window.set_buddy_caption(caption.into());
}

