/// Map the tagged CLI diagnostic inventory into GUI rows. A malformed or
/// duplicate row invalidates the complete snapshot so the UI never presents a
/// partial list as authoritative.
fn skill_summaries_from_inventory(
    inventory: Vec<neothd::skills::loader::SkillInventoryRow>,
) -> std::result::Result<Vec<panel_logic::SkillSummary>, String> {
    skill_summaries_from_inventory_at(inventory, &neothd::skills::installer::default_skills_dir())
}

fn skill_summaries_from_inventory_at(
    inventory: Vec<neothd::skills::loader::SkillInventoryRow>,
    skills_dir: &std::path::Path,
) -> std::result::Result<Vec<panel_logic::SkillSummary>, String> {
    let mut ids = std::collections::BTreeSet::new();
    inventory
        .into_iter()
        .enumerate()
        .map(|(index, row)| {
            let summary = match row {
                neothd::skills::loader::SkillInventoryRow::Healthy {
                    manifest,
                    origin,
                    path,
                    runtime_state,
                    package_generation_sha256,
                    install_incarnation,
                    install_terminal_receipt_sha256,
                } => {
                    let id = manifest.id.trim();
                    if !panel_logic::valid_skill_operation_id(id) {
                        return Err(format!(
                            "skill inventory row {} has an invalid id",
                            index + 1
                        ));
                    }
                    if manifest.description.trim().is_empty() {
                        return Err(format!(
                            "skill inventory row `{id}` has an empty description"
                        ));
                    }
                    let origin_runtime_valid = matches!(
                        (origin, runtime_state),
                        (
                            neothd::skills::loader::SkillInventoryOrigin::Bundled,
                            neothd::skills::loader::SkillInventoryRuntimeState::TrustedBundledActive
                                | neothd::skills::loader::SkillInventoryRuntimeState::Disabled
                        ) | (
                            neothd::skills::loader::SkillInventoryOrigin::User,
                            neothd::skills::loader::SkillInventoryRuntimeState::InstalledActive
                                | neothd::skills::loader::SkillInventoryRuntimeState::BundledFallbackActive
                                | neothd::skills::loader::SkillInventoryRuntimeState::Disabled
                        )
                    );
                    if !origin_runtime_valid {
                        return Err(format!(
                            "skill inventory row `{id}` has an invalid origin/runtime binding"
                        ));
                    }
                    let (
                        authority_generation,
                        authority_incarnation,
                        authority_install_receipt,
                    ) = match origin {
                        neothd::skills::loader::SkillInventoryOrigin::Bundled => {
                            if package_generation_sha256.is_some()
                                || install_incarnation.is_some()
                                || install_terminal_receipt_sha256.is_some()
                            {
                                return Err(format!(
                                    "bundled skill inventory row `{id}` carries installed authority"
                                ));
                            }
                            (String::new(), String::new(), String::new())
                        }
                        neothd::skills::loader::SkillInventoryOrigin::User => {
                            let generation = package_generation_sha256.as_deref().ok_or_else(|| {
                                format!(
                                    "installed skill inventory row `{id}` lacks its package generation"
                                )
                            })?;
                            if !valid_lower_sha256(generation) {
                                return Err(format!(
                                    "installed skill inventory row `{id}` has an invalid package generation"
                                ));
                            }
                            match (
                                install_incarnation,
                                install_terminal_receipt_sha256.as_deref(),
                            ) {
                                (Some(incarnation), Some(receipt))
                                    if incarnation > 0 && valid_lower_sha256(receipt) =>
                                {
                                    (
                                        generation.to_string(),
                                        incarnation.to_string(),
                                        receipt.to_string(),
                                    )
                                }
                                (None, None)
                                    if runtime_state
                                        != neothd::skills::loader::SkillInventoryRuntimeState::InstalledActive =>
                                {
                                    (generation.to_string(), String::new(), String::new())
                                }
                                _ => {
                                    return Err(format!(
                                        "installed skill inventory row `{id}` has an incomplete install receipt"
                                    ));
                                }
                            }
                        }
                    };
                    let (origin, path) = match (origin, path) {
                        (neothd::skills::loader::SkillInventoryOrigin::Bundled, None) => {
                            ("bundled".to_string(), String::new())
                        }
                        (neothd::skills::loader::SkillInventoryOrigin::User, Some(path))
                            if skill_inventory_path_matches(&path, skills_dir, id) =>
                        {
                            (
                                "user".to_string(),
                                diagnostic_skill_display_text(&path.display().to_string(), 512),
                            )
                        }
                        _ => {
                            return Err(format!(
                                "skill inventory row `{id}` has an invalid origin/path binding"
                            ));
                        }
                    };
                    panel_logic::SkillSummary {
                        id: manifest.id.clone(),
                        operation_id: manifest.id,
                        description: manifest.description,
                        enabled: matches!(
                            runtime_state,
                            neothd::skills::loader::SkillInventoryRuntimeState::TrustedBundledActive
                                | neothd::skills::loader::SkillInventoryRuntimeState::InstalledActive
                        ),
                        keywords: manifest.trigger_keywords.join(", "),
                        tags: manifest.tags,
                        broken: false,
                        error: String::new(),
                        path,
                        origin,
                        repairable: false,
                        runtime_state: match runtime_state {
                            neothd::skills::loader::SkillInventoryRuntimeState::TrustedBundledActive => {
                                "trusted_bundled_active"
                            }
                            neothd::skills::loader::SkillInventoryRuntimeState::InstalledActive => {
                                "installed_active"
                            }
                            neothd::skills::loader::SkillInventoryRuntimeState::BundledFallbackActive => {
                                "bundled_fallback_active"
                            }
                            neothd::skills::loader::SkillInventoryRuntimeState::Disabled => {
                                "disabled"
                            }
                        }
                        .to_string(),
                        authority_generation,
                        authority_incarnation,
                        authority_install_receipt,
                    }
                }
                neothd::skills::loader::SkillInventoryRow::Broken {
                    id,
                    error,
                    path,
                    repairability,
                    runtime_state,
                    package_generation_sha256: _,
                    install_incarnation: _,
                    install_terminal_receipt_sha256: _,
                } => {
                    if id.is_empty()
                        || error.trim().is_empty()
                        || !skill_inventory_path_matches(&path, skills_dir, &id)
                    {
                        return Err(format!(
                            "broken skill inventory row {} is incomplete",
                            index + 1
                        ));
                    }
                    if !matches!(
                        runtime_state,
                        neothd::skills::loader::SkillInventoryRuntimeState::BundledFallbackActive
                            | neothd::skills::loader::SkillInventoryRuntimeState::Disabled
                    ) {
                        return Err(format!(
                            "broken skill inventory row `{id}` has an invalid runtime binding"
                        ));
                    }
                    panel_logic::SkillSummary {
                        id: diagnostic_skill_display_id(&id),
                        operation_id: id.clone(),
                        description: String::new(),
                        enabled: false,
                        keywords: String::new(),
                        tags: Vec::new(),
                        broken: true,
                        error: diagnostic_skill_display_text(&error, 512),
                        path: diagnostic_skill_display_text(&path.display().to_string(), 512),
                        origin: "user".to_string(),
                        repairable: panel_logic::valid_skill_operation_id(&id)
                            && repairability
                                == neothd::skills::installer::SkillRepairability::ManifestReplaceable,
                        runtime_state: match runtime_state {
                            neothd::skills::loader::SkillInventoryRuntimeState::BundledFallbackActive => {
                                "bundled_fallback_active"
                            }
                            _ => "broken",
                        }
                        .to_string(),
                        authority_generation: String::new(),
                        authority_incarnation: String::new(),
                        authority_install_receipt: String::new(),
                    }
                }
            };
            if !ids.insert(summary.operation_id.to_lowercase()) {
                return Err(format!(
                    "skill inventory contains duplicate id `{}`",
                    summary.id
                ));
            }
            Ok(summary)
        })
        .collect()
}

fn skill_inventory_path_matches(
    actual: &std::path::Path,
    skills_dir: &std::path::Path,
    id: &str,
) -> bool {
    if !valid_skill_uninstall_id(id) {
        return false;
    }
    let Ok(actual) = std::path::absolute(actual) else {
        return false;
    };
    let Ok(expected) = std::path::absolute(skills_dir.join(id)) else {
        return false;
    };
    #[cfg(windows)]
    {
        actual
            .to_string_lossy()
            .eq_ignore_ascii_case(&expected.to_string_lossy())
    }
    #[cfg(not(windows))]
    {
        actual == expected
    }
}

fn valid_skill_uninstall_id(id: &str) -> bool {
    if id.is_empty() || id.contains(['\0', '/', '\\', ':']) || matches!(id, "." | "..") {
        return false;
    }
    let mut components = std::path::Path::new(id).components();
    matches!(components.next(), Some(std::path::Component::Normal(_)))
        && components.next().is_none()
}

fn valid_lower_sha256(value: &str) -> bool {
    value.len() == 64
        && value
            .bytes()
            .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
}

fn diagnostic_skill_display_id(id: &str) -> String {
    diagnostic_skill_display_text(id, 128)
}

fn diagnostic_skill_display_text(value: &str, max_chars: usize) -> String {
    value
        .chars()
        .map(|ch| if ch.is_control() { '�' } else { ch })
        .take(max_chars)
        .collect()
}

/// Fetch installed skills through the same typed subprocess boundary as GUI
/// mutations. Missing binaries, non-zero exits, malformed JSON, and corrupt
/// rows are errors; a valid `[]` is the only state rendered as no skills.
fn fetch_skills() -> std::result::Result<Vec<panel_logic::SkillSummary>, String> {
    let inventory = run_neothd_json_action::<Vec<neothd::skills::loader::SkillInventoryRow>>(
        &["skills", "--list"],
        "Skill inventory",
    )?;
    skill_summaries_from_inventory(inventory)
}

/// GOLD-ADAPT-AOS-01 — full verified skill list cache so search and
/// replacement confirmation do not infer state from CLI error strings.
/// `None` is distinct from a verified empty inventory.
static SKILLS_CACHE: std::sync::Mutex<Option<Vec<panel_logic::SkillSummary>>> =
    std::sync::Mutex::new(None);

#[derive(Clone, Debug, PartialEq, Eq)]
struct SkillPickerSnapshot {
    options: Vec<String>,
    selected_index: usize,
    selected_id: Option<String>,
}

#[derive(Debug, Default)]
struct SkillPickerState {
    options: Vec<String>,
    selected_id: Option<String>,
}

impl SkillPickerState {
    fn refresh(&mut self, options: Vec<String>) -> (SkillPickerSnapshot, bool) {
        debug_assert_eq!(options.first().map(String::as_str), Some("Automatic"));
        let previous = self.selected_id.clone();
        let selected_index = previous
            .as_ref()
            .and_then(|selected| options.iter().position(|option| option == selected))
            .unwrap_or(0);
        let selection_removed = previous.is_some() && selected_index == 0;
        if selection_removed {
            self.selected_id = None;
        }
        self.options = options;
        (self.snapshot(), selection_removed)
    }

    fn select(&mut self, index: i32) -> std::result::Result<SkillPickerSnapshot, String> {
        let index = usize::try_from(index)
            .map_err(|_| "Skill picker returned a negative selection index".to_string())?;
        let selected = self
            .options
            .get(index)
            .ok_or_else(|| "Skill picker returned an out-of-range selection".to_string())?;
        self.selected_id = (index != 0).then(|| selected.clone());
        Ok(self.snapshot())
    }

    fn snapshot(&self) -> SkillPickerSnapshot {
        let selected_index = self
            .selected_id
            .as_ref()
            .and_then(|selected| self.options.iter().position(|option| option == selected))
            .unwrap_or(0);
        SkillPickerSnapshot {
            options: self.options.clone(),
            selected_index,
            selected_id: self.selected_id.clone(),
        }
    }
}

static SKILL_PICKER_STATE: std::sync::Mutex<SkillPickerState> =
    std::sync::Mutex::new(SkillPickerState {
        options: Vec::new(),
        selected_id: None,
    });

fn selected_skill_id_for_request() -> std::result::Result<Option<String>, String> {
    SKILL_PICKER_STATE
        .lock()
        .map(|state| state.selected_id.clone())
        .map_err(|_| "Skill picker state is unavailable".to_string())
}

fn select_skill_picker_index(index: i32) -> std::result::Result<SkillPickerSnapshot, String> {
    SKILL_PICKER_STATE
        .lock()
        .map_err(|_| "Skill picker state is unavailable".to_string())?
        .select(index)
}

fn set_main_skill_picker(window: &MainWindow, snapshot: &SkillPickerSnapshot) {
    use slint::{ModelRc, SharedString, VecModel};
    let options = snapshot
        .options
        .iter()
        .map(|option| SharedString::from(option.as_str()))
        .collect::<Vec<_>>();
    window.set_chat_skill_options(ModelRc::new(VecModel::from(options)));
    window.set_chat_selected_skill_index(snapshot.selected_index as i32);
}

fn set_buddy_skill_picker(overlay: &MiniOverlay, snapshot: &SkillPickerSnapshot) {
    use slint::{ModelRc, SharedString, VecModel};
    let options = snapshot
        .options
        .iter()
        .map(|option| SharedString::from(option.as_str()))
        .collect::<Vec<_>>();
    overlay.set_skill_options(ModelRc::new(VecModel::from(options)));
    overlay.set_selected_skill_index(snapshot.selected_index as i32);
}

#[derive(Clone, Debug)]
struct VerifiedSkillAuthorityExpectation {
    generation_sha256: String,
    incarnation: String,
    install_receipt_sha256: String,
}

fn verified_skill_authority_expectation_in_cache(
    id: &str,
) -> std::result::Result<Option<VerifiedSkillAuthorityExpectation>, String> {
    let cache = SKILLS_CACHE
        .lock()
        .map_err(|_| "skill inventory cache is unavailable".to_string())?;
    let skills = cache.as_ref().ok_or_else(|| {
        "skill inventory has not completed a verified refresh; authority change is unavailable"
            .to_string()
    })?;
    let skill = skills
        .iter()
        .find(|skill| skill.operation_id == id)
        .ok_or_else(|| format!("skill `{id}` is not present in the verified inventory"))?;
    if skill.broken && skill.runtime_state == "bundled_fallback_active" {
        return Ok(None);
    }
    if skill.broken {
        return Err(format!(
            "installed candidate `{id}` is broken; repair or remove it before changing authority"
        ));
    }
    if skill.origin == "bundled" {
        return Ok(None);
    }
    if skill.origin != "user"
        || !valid_lower_sha256(&skill.authority_generation)
        || skill
            .authority_incarnation
            .parse::<u64>()
            .ok()
            .filter(|&n| n > 0)
            .is_none()
        || !valid_lower_sha256(&skill.authority_install_receipt)
    {
        return Err(format!(
            "installed candidate `{id}` has no authenticated install receipt; reinstall it before changing authority"
        ));
    }
    Ok(Some(VerifiedSkillAuthorityExpectation {
        generation_sha256: skill.authority_generation.clone(),
        incarnation: skill.authority_incarnation.clone(),
        install_receipt_sha256: skill.authority_install_receipt.clone(),
    }))
}

fn skill_authority_cli_args(
    flag: &str,
    id: &str,
    expectation: Option<&VerifiedSkillAuthorityExpectation>,
) -> Vec<String> {
    let mut args = vec!["skills".to_string(), flag.to_string(), id.to_string()];
    if let Some(expectation) = expectation {
        args.extend([
            "--expected-authority-generation-sha256".to_string(),
            expectation.generation_sha256.clone(),
            "--expected-authority-incarnation".to_string(),
            expectation.incarnation.clone(),
            "--expected-authority-install-receipt-sha256".to_string(),
            expectation.install_receipt_sha256.clone(),
        ]);
    }
    args
}

static SKILL_AUTHORITY_ACTION_IN_FLIGHT: std::sync::Mutex<bool> = std::sync::Mutex::new(false);

struct SkillAuthorityActionLease;

impl Drop for SkillAuthorityActionLease {
    fn drop(&mut self) {
        if let Ok(mut in_flight) = SKILL_AUTHORITY_ACTION_IN_FLIGHT.lock() {
            *in_flight = false;
        }
    }
}

fn acquire_skill_authority_action() -> Option<SkillAuthorityActionLease> {
    let mut in_flight = SKILL_AUTHORITY_ACTION_IN_FLIGHT.lock().ok()?;
    if *in_flight {
        return None;
    }
    *in_flight = true;
    Some(SkillAuthorityActionLease)
}

fn skill_exists_in_inventory(skills: &[panel_logic::SkillSummary], id: &str) -> bool {
    skills.iter().any(|skill| skill.operation_id == id)
}

fn verify_skill_absent_after_uninstall(
    skills: &[panel_logic::SkillSummary],
    id: &str,
) -> std::result::Result<(), String> {
    if skill_exists_in_inventory(skills, id) {
        Err(format!(
            "skill `{id}` is still present after the uninstall acknowledgement"
        ))
    } else {
        Ok(())
    }
}

fn verified_skill_exists_in_cache(id: &str) -> std::result::Result<bool, String> {
    let cache = SKILLS_CACHE
        .lock()
        .map_err(|_| "skill inventory cache is unavailable".to_string())?;
    let skills = cache.as_ref().ok_or_else(|| {
        "skill inventory has not completed a verified refresh; replacement is unavailable"
            .to_string()
    })?;
    Ok(skill_exists_in_inventory(skills, id))
}

fn verify_skill_uninstall_target(
    skills: &[panel_logic::SkillSummary],
    id: &str,
) -> std::result::Result<(), String> {
    let skill = skills
        .iter()
        .find(|skill| skill.operation_id == id)
        .ok_or_else(|| format!("skill `{id}` is not present in the verified inventory"))?;
    if skill.origin != "user" {
        return Err(format!(
            "skill `{id}` is bundled and has no removable user installation"
        ));
    }
    if skill.path.is_empty() {
        return Err(format!(
            "skill `{id}` has no verified user installation path"
        ));
    }
    Ok(())
}

fn verified_skill_uninstall_target_in_cache(id: &str) -> std::result::Result<(), String> {
    let cache = SKILLS_CACHE
        .lock()
        .map_err(|_| "skill inventory cache is unavailable".to_string())?;
    let skills = cache.as_ref().ok_or_else(|| {
        "skill inventory has not completed a verified refresh; uninstall is unavailable".to_string()
    })?;
    verify_skill_uninstall_target(skills, id)
}

/// GU-01 — push a verified installed-skill list onto the MainWindow. UI-thread
/// only. Failed refreshes preserve the previous model and cache, and remain
/// operator-visible instead of masquerading as a successful empty inventory.
fn apply_skills(
    window: &MainWindow,
    overlay: Option<&MiniOverlay>,
    skills: std::result::Result<Vec<panel_logic::SkillSummary>, String>,
) -> std::result::Result<(), String> {
    let skills = match skills {
        Ok(skills) => skills,
        Err(error) => {
            window.set_status_line(
                format!(
                    "Skill inventory unavailable: {error}. Keeping the previous verified list."
                )
                .into(),
            );
            return Err(error);
        }
    };
    let total = skills.len() as i32;
    let picker_options = panel_logic::skill_picker_options(&skills);
    let mut cache = match SKILLS_CACHE.lock() {
        Ok(cache) => cache,
        Err(_) => {
            let error = "skill inventory cache is unavailable".to_string();
            window.set_status_line(
                "Skill inventory cache is unavailable. Keeping the previous visible list.".into(),
            );
            return Err(error);
        }
    };
    let mut picker_state = match SKILL_PICKER_STATE.lock() {
        Ok(state) => state,
        Err(_) => {
            let error = "Skill picker state is unavailable".to_string();
            window.set_status_line(
                "Skill picker state is unavailable. Keeping the previous verified list.".into(),
            );
            return Err(error);
        }
    };
    *cache = Some(skills);
    let (picker_snapshot, selection_removed) = picker_state.refresh(picker_options);
    drop(cache);
    drop(picker_state);
    window.set_skills_total(total);
    set_main_skill_picker(window, &picker_snapshot);
    if let Some(overlay) = overlay {
        set_buddy_skill_picker(overlay, &picker_snapshot);
    }
    if selection_removed {
        let status = "Skill: Automatic · previous selection unavailable after refresh";
        window.set_chat_skill_route_status(status.into());
        if let Some(overlay) = overlay {
            overlay.set_skill_route_status(status.into());
        }
    }
    render_skill_index(window);
    Ok(())
}

/// AOS-01 — regroup the cached skills under the current filter and push
/// the flat header+row model. UI-thread only.
fn render_skill_index(window: &MainWindow) {
    use slint::{ModelRc, VecModel};
    let filter = window.get_skills_filter().to_string();
    // Clone out of the lock immediately — holding it across the grouping
    // would stall any future off-thread cache writer.
    let skills = match SKILLS_CACHE.lock() {
        Ok(cache) => cache.as_ref().cloned().unwrap_or_default(),
        Err(_) => {
            window.set_status_line(
                "Skill inventory cache is unavailable. Keeping the previous visible list.".into(),
            );
            return;
        }
    };
    let rows: Vec<SkillRow> = panel_logic::group_skill_rows(&skills, &filter)
        .into_iter()
        .map(|s| SkillRow {
            id: s.id.into(),
            operation_id: s.operation_id.into(),
            description: s.description.into(),
            enabled: s.enabled,
            keywords: s.keywords.into(),
            tags: s.tags.into(),
            is_header: s.is_header,
            broken: s.broken,
            error: s.error.into(),
            path: s.path.into(),
            origin: s.origin.into(),
            repairable: s.repairable,
            runtime_state: s.runtime_state.into(),
            authority_generation: s.authority_generation.into(),
            authority_incarnation: s.authority_incarnation.into(),
            authority_install_receipt: s.authority_install_receipt.into(),
        })
        .collect();
    window.set_skills(ModelRc::new(VecModel::from(rows)));
}

/// GU-01 — fetch discovered plugins via `neoth plugin list --output json`.
fn fetch_plugins() -> Vec<panel_logic::PluginSummary> {
    let Some(bin) = which_neothd() else {
        return Vec::new();
    };
    match spawn_neothd_plain(&bin)
        .arg("plugin")
        .arg("list")
        .arg("--output")
        .arg("json")
        .output()
    {
        Ok(o) if o.status.success() => {
            panel_logic::parse_plugins(&String::from_utf8_lossy(&o.stdout))
        }
        _ => Vec::new(),
    }
}

/// GU-01 — push the discovered-plugin list onto the MainWindow. UI-thread only.
fn apply_plugins(window: &MainWindow, plugins: Vec<panel_logic::PluginSummary>) {
    use slint::{ModelRc, VecModel};
    let rows: Vec<PluginRow> = plugins
        .into_iter()
        .map(|p| PluginRow {
            id: p.id.into(),
            name: p.name.into(),
            activation: p.activation.into(),
            requested_permission: p.requested_permission.into(),
            // DES-12
            has_ui_surface: p.has_ui_surface,
            ui_title: p.ui_title.into(),
        })
        .collect();
    window.set_plugins(ModelRc::new(VecModel::from(rows)));
}

/// DES-12 — fetch WAL-feed events for a plugin via
/// `neoth plugin events <id> --output json --last 30`.
fn fetch_plugin_events(id: &str) -> Vec<panel_logic::PluginEventRow> {
    let Some(bin) = which_neothd() else {
        return Vec::new();
    };
    match spawn_neothd_plain(&bin)
        .arg("plugin")
        .arg("events")
        .arg(id)
        .arg("--output")
        .arg("json")
        .arg("--last")
        .arg("30")
        .output()
    {
        Ok(o) if o.status.success() => {
            panel_logic::parse_plugin_events(&String::from_utf8_lossy(&o.stdout))
        }
        _ => Vec::new(),
    }
}

/// DES-12 — format a unix timestamp as HH:MM:SS (UTC).
/// Falls back to the raw seconds string when time parsing is unavailable.
fn fmt_ts_unix(ts: u64) -> String {
    // Simple modulo decomposition — avoids pulling in chrono just for display.
    let s = ts % 60;
    let m = (ts / 60) % 60;
    let h = (ts / 3600) % 24;
    format!("{h:02}:{m:02}:{s:02}")
}

/// DES-12 — format a byte count as a compact human-readable string.
fn fmt_event_bytes(n: u64) -> String {
    if n < 1024 {
        format!("{n} B")
    } else if n < 1024 * 1024 {
        format!("{:.1} KB", n as f64 / 1024.0)
    } else {
        format!("{:.1} MB", n as f64 / (1024.0 * 1024.0))
    }
}

/// GU-01 — fetch memory-block sizes via `neoth memory --size --output json`
/// (metadata only — no content leaves the daemon).
fn fetch_memory_snapshot() -> panel_logic::MemorySnapshot {
    let Some(bin) = which_neothd() else {
        return panel_logic::MemorySnapshot::default();
    };
    match spawn_neothd_plain(&bin)
        .arg("memory")
        .arg("--size")
        .arg("--output")
        .arg("json")
        .output()
    {
        Ok(o) if o.status.success() => {
            panel_logic::parse_memory_size(&String::from_utf8_lossy(&o.stdout))
        }
        _ => panel_logic::MemorySnapshot::default(),
    }
}

/// Human-readable byte size (B / KB / MB).
fn fmt_bytes(n: i64) -> String {
    if n < 1024 {
        format!("{n} B")
    } else if n < 1024 * 1024 {
        format!("{:.1} KB", n as f64 / 1024.0)
    } else {
        format!("{:.1} MB", n as f64 / (1024.0 * 1024.0))
    }
}

/// GU-01 — push the memory-block sizes onto the MainWindow. UI-thread only.
fn apply_memory(window: &MainWindow, snap: panel_logic::MemorySnapshot) {
    use slint::{ModelRc, VecModel};
    let rows: Vec<MemoryRow> = snap
        .blocks
        .into_iter()
        .map(|b| MemoryRow {
            source: b.source.into(),
            path: b.path.into(),
            bytes: fmt_bytes(b.bytes).into(),
        })
        .collect();
    window.set_memory_blocks(ModelRc::new(VecModel::from(rows)));
    window.set_memory_total(fmt_bytes(snap.total_bytes).into());
}

/// GOLD-R3-04 — push the canonical per-channel probe state onto MainWindow.
/// Errors clear stale rows and remain visible in-panel instead of degrading to
/// a false "not connected" state. UI-thread only.
fn build_chat_sidebar_channels(channels: &[panel_logic::ChannelStatus]) -> Vec<ChatChannelRow> {
    let mut rows = vec![ChatChannelRow {
        id: "cli".into(),
        label: "Local CLI".into(),
        detail: "Local chat · ready".into(),
        last_message: "".into(),
        last_timestamp: "".into(),
        route_bound: true,
        configurable: false,
    }];
    rows.extend(
        channels
            .iter()
            .filter(|channel| channel.configured)
            .map(|channel| ChatChannelRow {
                id: channel.name.as_str().into(),
                label: channel.name.as_str().into(),
                detail: "Configured · chat routing not available yet".into(),
                last_message: "".into(),
                last_timestamp: "".into(),
                route_bound: false,
                configurable: true,
            }),
    );
    rows
}

/// Replace the canonical live feed and mirror it into the visible pane only
/// when the operator is not inspecting a historical session.
fn set_live_chat_messages(window: &MainWindow, rows: Vec<ChatMessage>) {
    use slint::{ModelRc, VecModel};
    window.set_chat_live_messages(ModelRc::new(VecModel::from(rows.clone())));
    if !window.get_chat_history_active() {
        window.set_chat_messages(ModelRc::new(VecModel::from(rows)));
    }
}

const DURABLE_BACKGROUND_NOTICE_HISTORY_LIMIT: usize = 256;

/// Restore already-persisted background results before the first paint. The
/// transcript row is the restart-safe source of truth; the `.delivered` marker
/// is committed only after the canonical live model contains the same stable
/// notice id.
fn hydrate_durable_background_notices(window: &MainWindow, neoth_home: &std::path::Path) {
    let db_path = neoth_home.join("views.db");
    if !db_path.exists() {
        return;
    }
    let persisted = match neothd::memory::transcript_store::read_latest_background_notices_at(
        &db_path,
        DURABLE_BACKGROUND_NOTICE_HISTORY_LIMIT,
    ) {
        Ok(notices) => notices,
        Err(error) => {
            tracing::warn!(
                %error,
                path = %db_path.display(),
                "durable background-result history could not be restored"
            );
            set_live_chat_messages(
                window,
                vec![ChatMessage {
                    role: "error".into(),
                    text: "Stored background results could not be restored. Run `neoth doctor`."
                        .into(),
                    timestamp: format_now_hms().into(),
                    request_id: "notice:background_result:recovery-error".into(),
                    stream_phase: ChatStreamPhase::Failed.as_wire().into(),
                    ..Default::default()
                }],
            );
            return;
        }
    };
    if persisted.is_empty() {
        return;
    }

    // The store bounds newest-first internally and returns the retained rows
    // in canonical chronological order.
    let notices = persisted
        .into_iter()
        .map(|notice| StreamNotice {
            id: notice.job_id,
            kind: "background_result".to_string(),
            text: notice.text,
            durable: true,
            timestamp: Some(format_unix_hms(notice.ts_unix)),
        })
        .collect::<Vec<_>>();
    let startup_anchor =
        ChatStreamRequestId::parse_wire(&u64::MAX.to_string()).expect("u64::MAX is a valid id");
    materialize_stream_notices(window, startup_anchor, &notices);
    acknowledge_materialized_stream_notices(window, &notices);
}

/// Materialise authenticated, non-reply stream events ahead of the request
/// that caused their delivery. Stable notice ids make repeated parsing and
/// recoverable background-delivery retries idempotent.
fn materialize_stream_notices(
    window: &MainWindow,
    request_id: ChatStreamRequestId,
    notices: &[StreamNotice],
) -> usize {
    use slint::Model;

    if notices.is_empty() {
        return 0;
    }
    let mut rows: Vec<ChatMessage> = window.get_chat_live_messages().iter().collect();
    let inserted = insert_stream_notices(&mut rows, request_id, notices);
    if inserted > 0 {
        set_live_chat_messages(window, rows);
        recompute_live_chat_preview(window);
    }
    inserted
}

fn insert_stream_notices(
    rows: &mut Vec<ChatMessage>,
    request_id: ChatStreamRequestId,
    notices: &[StreamNotice],
) -> usize {
    let request_id_wire = request_id.as_wire();
    let request_incognito = rows
        .iter()
        .find(|row| row.request_id.as_str() == request_id_wire.as_str())
        .map(|row| row.incognito)
        .unwrap_or(false);
    let mut background_insertion_index = rows
        .iter()
        .position(|row| row.request_id.as_str() == request_id_wire.as_str())
        .unwrap_or(rows.len());
    let mut turn_event_insertion_index = rows
        .iter()
        .rposition(|row| row.request_id.as_str() == request_id_wire.as_str())
        .map_or(rows.len(), |index| index.saturating_add(1));
    let mut inserted = 0;
    for notice in notices {
        let notice_request_id = format!("notice:{}:{}", notice.kind, notice.id);
        if rows
            .iter()
            .any(|row| row.request_id.as_str() == notice_request_id.as_str())
        {
            continue;
        }
        let (role, text, insertion_index, is_background) = match notice.kind.as_str() {
            "background_result" => (
                "assistant",
                if notice.text.trim().is_empty() {
                    "[btw] Background task completed without output.".to_string()
                } else {
                    format!("[btw] {}", notice.text)
                },
                background_insertion_index,
                true,
            ),
            "review_result" => (
                "assistant",
                format!("[review]\n{}", notice.text),
                turn_event_insertion_index,
                false,
            ),
            "operator_notice" => (
                "assistant",
                format!("[notice]\n{}", notice.text),
                turn_event_insertion_index,
                false,
            ),
            "finalization_error" => (
                "error",
                format!("Finalization failed: {}", notice.text),
                turn_event_insertion_index,
                false,
            ),
            _ => continue,
        };
        rows.insert(
            insertion_index,
            ChatMessage {
                role: role.into(),
                text: text.into(),
                timestamp: notice
                    .timestamp
                    .clone()
                    .unwrap_or_else(format_now_hms)
                    .into(),
                request_id: notice_request_id.into(),
                stream_phase: ChatStreamPhase::Complete.as_wire().into(),
                incognito: request_incognito,
                ..Default::default()
            },
        );
        if is_background {
            background_insertion_index += 1;
            turn_event_insertion_index += 1;
        } else {
            turn_event_insertion_index += 1;
        }
        inserted += 1;
    }
    inserted
}

fn acknowledge_materialized_stream_notices(window: &MainWindow, notices: &[StreamNotice]) {
    use slint::Model;

    let rows: Vec<ChatMessage> = window.get_chat_live_messages().iter().collect();
    let bgjobs_home = default_neoth_home().join("bgjobs");
    for notice in notices {
        if notice.kind != "background_result" || !notice.durable {
            continue;
        }
        let delivering_path = bgjobs_home.join(format!("{}.delivering", notice.id));
        match std::fs::symlink_metadata(&delivering_path) {
            Ok(_) => {}
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => continue,
            Err(error) => {
                tracing::warn!(
                    job_id = %notice.id,
                    path = %delivering_path.display(),
                    %error,
                    "durable background-result delivery claim could not be inspected"
                );
                continue;
            }
        }
        let notice_request_id = format!("notice:{}:{}", notice.kind, notice.id);
        if !rows
            .iter()
            .any(|row| row.request_id.as_str() == notice_request_id.as_str())
        {
            continue;
        }
        if let Err(error) =
            neothd::cli::bg_session::acknowledge_bg_result_delivery(&bgjobs_home, &notice.id)
        {
            tracing::warn!(
                job_id = %notice.id,
                %error,
                "canonical background-result delivery remains recoverable because acknowledgement failed"
            );
        }
    }
}

/// Materialise one request in the canonical conversation regardless of which
/// surface initiated it. Repeated delivery of an accepted callback is
/// idempotent: a request id can own exactly one assistant placeholder.
fn begin_live_chat_request(
    window: &MainWindow,
    request_id: ChatStreamRequestId,
    body: &str,
    incognito: bool,
) -> bool {
    use slint::Model;
    let request_id_wire = request_id.as_wire();
    let mut rows: Vec<ChatMessage> = window.get_chat_live_messages().iter().collect();
    if rows.iter().any(|row| {
        row.request_id.as_str() == request_id_wire.as_str() && row.role.as_str() == "assistant"
    }) {
        return false;
    }
    let timestamp = format_now_hms();
    rows.push(ChatMessage {
        role: "operator".into(),
        text: body.into(),
        timestamp: timestamp.clone().into(),
        request_id: request_id_wire.clone().into(),
        stream_phase: ChatStreamPhase::Complete.as_wire().into(),
        incognito,
        ..Default::default()
    });
    rows.push(ChatMessage {
        role: "assistant".into(),
        text: "…".into(),
        timestamp: timestamp.into(),
        request_id: request_id_wire.into(),
        stream_phase: ChatStreamPhase::Waiting.as_wire().into(),
        incognito,
        ..Default::default()
    });
    set_live_chat_messages(window, rows);
    recompute_live_chat_preview(window);
    true
}

/// Settle every request-owned presentation flag together. Pre-launch and
/// terminal error paths must never leave an Incognito badge active after the
/// request itself has stopped owning the UI.
fn settle_main_chat_request_ui(window: &MainWindow) {
    window.set_chat_send_in_flight(false);
    window.set_chat_incognito_active(false);
}

fn activate_buddy_chat_request_ui(window: &MainWindow, overlay: &MiniOverlay, incognito: bool) {
    window.set_chat_incognito_active(incognito);
    overlay.set_incognito_active(incognito);
}

fn settle_buddy_chat_request_ui(window: &MainWindow, overlay: &MiniOverlay) {
    settle_main_chat_request_ui(window);
    overlay.set_send_in_flight(false);
    overlay.set_incognito_active(false);
}

fn detach_operator_recall_for_incognito(
    last_operator_input: &std::sync::Mutex<String>,
    selected: bool,
) {
    if selected {
        use zeroize::Zeroize as _;

        last_operator_input
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .zeroize();
    }
}

fn eligible_operator_recall(
    last_operator_input: &std::sync::Mutex<String>,
    incognito_selected: bool,
    incognito_active: bool,
) -> Option<String> {
    if incognito_selected || incognito_active {
        return None;
    }
    let value = last_operator_input
        .lock()
        .map(|value| value.clone())
        .unwrap_or_default();
    (!value.is_empty()).then_some(value)
}

/// Project a request-bound provider event into the canonical live feed. The
/// caller must validate the reducer state at UI-delivery time.
fn project_chat_stream_update(
    window: &MainWindow,
    request_id: ChatStreamRequestId,
    phase: ChatStreamPhase,
    visible_text: Option<&str>,
) -> bool {
    use slint::Model;
    let request_id = request_id.as_wire();
    let mut rows: Vec<ChatMessage> = window.get_chat_live_messages().iter().collect();
    let Some(row) = rows
        .iter_mut()
        .find(|row| row.request_id.as_str() == request_id && row.role.as_str() == "assistant")
    else {
        return false;
    };
    if let Some(text) = visible_text.filter(|text| !text.trim().is_empty()) {
        row.text = text.into();
    }
    row.stream_phase = phase.as_wire().into();
    set_live_chat_messages(window, rows);
    true
}

fn project_chat_stream_phase(
    window: &MainWindow,
    request_id: ChatStreamRequestId,
    phase: ChatStreamPhase,
) -> bool {
    project_chat_stream_update(window, request_id, phase, None)
}

fn live_chat_request_text(window: &MainWindow, request_id: ChatStreamRequestId) -> Option<String> {
    use slint::Model;
    let request_id = request_id.as_wire();
    window
        .get_chat_live_messages()
        .iter()
        .filter(|row| {
            row.request_id.as_str() == request_id.as_str()
                && matches!(row.role.as_str(), "assistant" | "error")
        })
        .last()
        .map(|row| row.text.to_string())
}

/// Settle the unsegmented Buddy reply in the same canonical conversation used
/// by Main Chat. Main Chat retains its richer segmentation/metrics path.
fn settle_live_chat_request(
    window: &MainWindow,
    request_id: ChatStreamRequestId,
    phase: ChatStreamPhase,
    terminal_text: Option<&str>,
) -> bool {
    use slint::Model;
    let request_id_wire = request_id.as_wire();
    let mut rows: Vec<ChatMessage> = window.get_chat_live_messages().iter().collect();
    let Some(row) = rows.iter_mut().find(|row| {
        row.request_id.as_str() == request_id_wire.as_str()
            && matches!(row.role.as_str(), "assistant" | "error")
    }) else {
        tracing::error!(
            request_id = request_id.get(),
            "request-bound Buddy placeholder disappeared; terminal reply suppressed"
        );
        return false;
    };
    match phase {
        ChatStreamPhase::Complete => {
            if let Some(text) = terminal_text.filter(|text| !text.trim().is_empty()) {
                row.text = text.into();
            }
            row.role = "assistant".into();
        }
        ChatStreamPhase::Cancelled => {
            if row.text.trim().is_empty() || row.text.as_str() == "…" {
                row.text = "Stopped before a reply arrived.".into();
            }
        }
        ChatStreamPhase::Failed => {
            row.role = "error".into();
            if let Some(text) = terminal_text.filter(|text| !text.trim().is_empty()) {
                row.text = text.into();
            }
        }
        ChatStreamPhase::Waiting | ChatStreamPhase::Receiving | ChatStreamPhase::Finalizing => {
            return false;
        }
    }
    row.stream_phase = phase.as_wire().into();
    set_live_chat_messages(window, rows);
    recompute_live_chat_preview(window);
    true
}

fn resize_companion_overlay(overlay: &MiniOverlay) {
    use slint::winit_030::WinitWindowAccessor;
    let height: f64 = if overlay.get_compact() {
        if overlay.get_bubble_text().is_empty() {
            64.0
        } else {
            148.0
        }
    } else {
        520.0
    };
    overlay.window().with_winit_window(|window| {
        let _ = window.request_inner_size(slint::winit_030::winit::dpi::LogicalSize::new(
            380.0, height,
        ));
    });
}

fn sync_companion_recent_lines_from_canonical(window: &MainWindow, overlay: &MiniOverlay) {
    use slint::{Model, ModelRc, VecModel};
    let mut lines: Vec<slint::SharedString> = window
        .get_chat_live_messages()
        .iter()
        .filter_map(|message| {
            let normalized = message
                .text
                .split_whitespace()
                .collect::<Vec<_>>()
                .join(" ");
            if normalized.is_empty() || normalized == "…" {
                return None;
            }
            let tail = utf8_suffix(&normalized, 160);
            let visible = if tail.len() < normalized.len() {
                format!("…{tail}")
            } else {
                normalized
            };
            Some(
                match message.role.as_str() {
                    "operator" => format!("▶ {visible}"),
                    "error" => format!("⚠ {visible}"),
                    _ => format!("NEOTH · {visible}"),
                }
                .into(),
            )
        })
        .collect();
    if lines.len() > 6 {
        let drain_count = lines.len() - 6;
        lines.drain(..drain_count);
    }
    overlay.set_recent_lines(ModelRc::new(VecModel::from(lines)));
}

/// Mirror the canonical request phase into the companion surface. This is a
/// projection only; the reducer remains the sole transition authority.
fn project_companion_chat_stream(
    overlay: &MiniOverlay,
    phase: ChatStreamPhase,
    visible_text: Option<&str>,
) {
    let activity = GuiActivity::from(phase);
    let (mood, caption) = activity.mood();
    overlay.set_send_in_flight(phase.is_active());
    if !phase.is_active() {
        // All pre-launch failures and terminal projections converge here, so
        // Buddy cannot retain a stale active-Incognito indicator.
        overlay.set_incognito_active(false);
    }
    overlay.set_buddy_mood(mood.into());
    overlay.set_status_text(caption.into());
    if phase == ChatStreamPhase::Waiting {
        overlay.set_bubble_text("".into());
    }
    if let Some(text) = visible_text.filter(|text| !text.trim().is_empty() && *text != "…") {
        let tail = utf8_suffix(text, 120);
        overlay.set_bubble_text(
            if tail.len() < text.len() {
                format!("…{tail}")
            } else {
                text.to_string()
            }
            .into(),
        );
    }
    resize_companion_overlay(overlay);
}

fn discard_chat_model_override(
    model_overrides: &std::sync::Mutex<std::collections::HashMap<ChatStreamRequestId, String>>,
    request_id: ChatStreamRequestId,
) {
    use zeroize::Zeroize as _;

    match model_overrides.lock() {
        Ok(mut overrides) => {
            if let Some(mut model) = overrides.remove(&request_id) {
                model.zeroize();
            }
        }
        Err(_) => tracing::error!(
            request_id = request_id.get(),
            "chat model override state is poisoned during request cleanup"
        ),
    }
}

fn current_live_chat_preview(window: &MainWindow) -> (String, String) {
    use slint::Model;
    let messages = window.get_chat_live_messages();
    let rows = messages.iter().collect::<Vec<_>>();
    panel_logic::latest_chat_sidebar_preview(
        rows.iter()
            .rev()
            // Sidebar state is durable enough to survive channel refreshes.
            // Never derive either field from a private row, including an
            // otherwise harmless-looking timestamp or active placeholder.
            .filter(|message| !message.incognito)
            .map(|message| {
                (
                    message.text.as_str(),
                    message.timestamp.as_str(),
                    ChatStreamPhase::is_active_wire(message.stream_phase.as_str()),
                )
            }),
    )
}

fn recompute_live_chat_preview(window: &MainWindow) {
    let (preview, timestamp) = current_live_chat_preview(window);
    set_local_chat_sidebar_preview(window, &preview, &timestamp);
}

fn set_local_chat_sidebar_preview(window: &MainWindow, preview: &str, timestamp: &str) {
    use slint::{Model, ModelRc, VecModel};
    let mut channels = window.get_chat_channels().iter().collect::<Vec<_>>();
    if let Some(local) = channels.iter_mut().find(|row| row.id == "cli") {
        local.last_message = preview.into();
        local.last_timestamp = timestamp.into();
        window.set_chat_channels(ModelRc::new(VecModel::from(channels)));
    }
}

/// Fill a newly materialised Local CLI row without overwriting a preview that
/// survived a channel-probe reload. Live state wins; retained history is only
/// a cold-start fallback.
fn hydrate_local_chat_sidebar_preview(
    channels: &mut [ChatChannelRow],
    live: Option<(String, String)>,
    history: Option<(String, String)>,
) {
    let Some(local) = channels.iter_mut().find(|row| row.id == "cli") else {
        return;
    };
    if !local.last_message.is_empty() {
        return;
    }
    let candidate = live
        .filter(|(preview, _)| !preview.is_empty())
        .or_else(|| history.filter(|(preview, _)| !preview.is_empty()));
    if let Some((preview, timestamp)) = candidate {
        local.last_message = preview.into();
        local.last_timestamp = timestamp.into();
    }
}

fn session_load_is_current(
    current_revision: u64,
    load_revision: u64,
    history_active: bool,
    active_session_id: &str,
    loaded_session_id: &str,
) -> bool {
    history_active && current_revision == load_revision && active_session_id == loaded_session_id
}

fn refresh_chat_session_history(weak: slint::Weak<MainWindow>) {
    let generation =
        CHAT_HISTORY_REFRESH_REVISION.fetch_add(1, std::sync::atomic::Ordering::AcqRel) + 1;
    std::thread::spawn(move || {
        let loaded = panel_logic::load_session_history(&default_neoth_home(), 20);
        let _ = slint::invoke_from_event_loop(move || {
            if CHAT_HISTORY_REFRESH_REVISION.load(std::sync::atomic::Ordering::Acquire)
                != generation
            {
                return;
            }
            let Some(window) = weak.upgrade() else {
                return;
            };
            let rows = match loaded {
                Ok(rows) => rows,
                Err(error) => {
                    tracing::warn!(error = %error, "session history refresh failed; retaining previous snapshot");
                    let error = neothd::security::redact::sanitize_tool_output(&error);
                    window.set_status_line(
                        format!(
                            "Session history unavailable: {error}. Keeping the previous session list."
                        )
                        .into(),
                    );
                    return;
                }
            };
            use slint::{Model, ModelRc, VecModel};
            let newest_preview = rows
                .first()
                .map(|row| (row.preview.clone(), row.last_timestamp.clone()));
            let model = rows
                .into_iter()
                .map(|row| SessionRow {
                    id: row.id.into(),
                    label: row.label.into(),
                    meta: row.meta.into(),
                    preview: row.preview.into(),
                    last_timestamp: row.last_timestamp.into(),
                })
                .collect::<Vec<_>>();
            window.set_chat_session_history(ModelRc::new(VecModel::from(model)));
            if let Some((preview, timestamp)) = newest_preview
                && window.get_chat_live_messages().row_count() == 0
            {
                set_local_chat_sidebar_preview(&window, &preview, &timestamp);
            }
        });
    });
}

fn apply_channels(window: &MainWindow, channels: Result<Vec<panel_logic::ChannelStatus>, String>) {
    use slint::{Model, ModelRc, VecModel};
    let (channels, error) = match channels {
        Ok(channels) => (channels, String::new()),
        Err(error) => (Vec::new(), error),
    };
    let channel_types = channels
        .iter()
        .map(|channel| slint::SharedString::from(channel.name.as_str()))
        .collect::<Vec<_>>();
    // The chat composer has exactly one bound route today: local CLI. External
    // configured channels remain visible for truthful discovery and management,
    // but their typed rows cannot acquire selection or inherit local sends.
    let mut chat_channels = build_chat_sidebar_channels(&channels);
    // Channel probe reloads must not erase per-session previews. Merge by the
    // stable typed id rather than by row index (configured rows can reorder).
    let existing_previews = window
        .get_chat_channels()
        .iter()
        .map(|row| (row.id.to_string(), (row.last_message, row.last_timestamp)))
        .collect::<std::collections::BTreeMap<_, _>>();
    for row in &mut chat_channels {
        if let Some((message, timestamp)) = existing_previews.get(row.id.as_str()) {
            row.last_message = message.clone();
            row.last_timestamp = timestamp.clone();
        }
    }
    // Send can beat the asynchronous channel probe. Reconstruct from the live
    // model first so that early operator input is not lost; retained history
    // is only a fallback when no live rows exist.
    let live_rows = window.get_chat_live_messages().row_count();
    let live_preview = (live_rows > 0).then(|| current_live_chat_preview(window));
    let history_preview = (live_rows == 0)
        .then(|| window.get_chat_session_history().row_data(0))
        .flatten()
        .map(|row| (row.preview.to_string(), row.last_timestamp.to_string()));
    hydrate_local_chat_sidebar_preview(&mut chat_channels, live_preview, history_preview);
    let rows = channels
        .into_iter()
        .map(|channel| ChannelRow {
            name: channel.name.into(),
            status: channel.status.into(),
            configured: channel.configured,
            detail: channel.detail.into(),
            setup_secret_f1: channel.setup_secret_mask[0],
            setup_secret_f2: channel.setup_secret_mask[1],
            setup_secret_f3: channel.setup_secret_mask[2],
            setup_secret_f4: channel.setup_secret_mask[3],
            setup_secret_f5: channel.setup_secret_mask[4],
            setup_secret_f6: channel.setup_secret_mask[5],
        })
        .collect::<Vec<_>>();
    window.set_channel_types(ModelRc::new(VecModel::from(channel_types)));
    window.set_channels(ModelRc::new(VecModel::from(rows)));
    window.set_channel_status_error(error.into());

    // unread-counts stays parallel-indexed + length-matched with chat-channels
    // (there is no routed unread stream yet, so every value is zero).
    let unread = vec![0i32; chat_channels.len()];
    window.set_chat_channels(ModelRc::new(VecModel::from(chat_channels)));
    window.set_chat_unread_counts(ModelRc::new(VecModel::from(unread)));
}

/// Fetch `neoth channel list --output json`. A missing binary, non-zero exit,
/// malformed stdout, or corrupt operator config is returned verbatim enough to
/// repair, but never with secret material from stdout.
fn fetch_channel_status() -> Result<Vec<panel_logic::ChannelStatus>, String> {
    let bin = which_neothd().ok_or_else(|| {
        "NEOTH CLI not found. Reinstall or repair PATH, then refresh.".to_string()
    })?;
    let output = spawn_neothd_plain(&bin)
        .arg("channel")
        .arg("list")
        .arg("--output")
        .arg("json")
        .output()
        .map_err(|error| format!("could not start NEOTH channel probe: {error}"))?;
    if !output.status.success() {
        let detail = String::from_utf8_lossy(&output.stderr)
            .lines()
            .map(str::trim)
            .find(|line| !line.is_empty())
            .unwrap_or("channel probe failed without detail")
            .to_string();
        return Err(detail);
    }
    panel_logic::parse_channel_status(&String::from_utf8_lossy(&output.stdout))
}

/// SPEC-05 — fetch the saved presets via `neoth preset list --json`. Empty on
/// missing binary / failure. PARSE is the unit-tested `panel_logic::parse_presets`.
fn fetch_presets() -> Vec<panel_logic::PresetEntry> {
    let Some(bin) = which_neothd() else {
        return Vec::new();
    };
    match spawn_neothd_plain(&bin)
        .arg("preset")
        .arg("list")
        .arg("--json")
        .output()
    {
        Ok(o) if o.status.success() => {
            panel_logic::parse_presets(&String::from_utf8_lossy(&o.stdout))
        }
        _ => Vec::new(),
    }
}

/// SPEC-05 — push the preset selector list onto the MainWindow. UI-thread only.
///
/// Injects flat sentinel header rows (is-header=true) so the Slint `for` loop
/// can use the same `if p.is-header:` / `if !p.is-header:` pattern as the
/// Skills expander — no nested conditionals inside the loop body.
///
/// Layout injected:
///   PresetRow { name="BUILT-IN", is_header=true }
///   … built-in rows …
///   PresetRow { name="YOURS",    is_header=true }   ← only when operator presets exist
///   … operator rows …
fn apply_presets(window: &MainWindow, presets: Vec<panel_logic::PresetEntry>) {
    use slint::{ModelRc, VecModel};
    let header = |label: &str| PresetRow {
        name: label.into(),
        active: false,
        builtin: false,
        description: "".into(),
        is_header: true,
    };
    let data_row = |p: panel_logic::PresetEntry| PresetRow {
        name: p.name.into(),
        active: p.active,
        builtin: p.builtin,
        description: p.description.into(),
        is_header: false,
    };

    // Split into builtin / operator so the YOURS header only appears once.
    let (builtins, operators): (Vec<_>, Vec<_>) = presets.into_iter().partition(|p| p.builtin);
    let mut rows: Vec<PresetRow> = Vec::with_capacity(builtins.len() + operators.len() + 2);

    rows.push(header("BUILT-IN"));
    for p in builtins {
        rows.push(data_row(p));
    }
    if !operators.is_empty() {
        rows.push(header("YOURS"));
        for p in operators {
            rows.push(data_row(p));
        }
    }
    window.set_preset_list(ModelRc::new(VecModel::from(rows)));
}

