/// SPEC-06 — push the provider-id picker options onto the MainWindow. UI-thread.
fn canonical_provider_ids() -> Vec<String> {
    neothd::config::inference::InferenceProvider::ALL
        .iter()
        .map(|provider| provider.as_str().to_string())
        .collect()
}

fn apply_provider_ids(window: &MainWindow, reported_ids: Vec<String>) {
    use slint::{ModelRc, VecModel};
    let ids = canonical_provider_ids();
    if !reported_ids.is_empty() && reported_ids != ids {
        tracing::warn!(
            reported = ?reported_ids,
            canonical = ?ids,
            "provider-list subprocess drift ignored; GUI uses the canonical roster"
        );
    }
    // GUI-improve (gap panel wf_641e1173) — compute the Config combo's selected
    // row = position of the operator's current provider in the LIVE list, so a
    // provider absent from the old hardcoded combo list no longer silently shows
    // as row 0 (claude_cli). `provider-choice` is set from freedom.yaml at
    // startup (line 241) before this runs.
    let current = window.get_provider_choice().to_string();
    let idx = ids.iter().position(|p| p == &current).unwrap_or(0) as i32;
    let rows: Vec<slint::SharedString> = ids.iter().cloned().map(Into::into).collect();
    window.set_provider_ids(ModelRc::new(VecModel::from(rows)));
    window.set_provider_choice_index(idx);
    let role_index = |provider: &str| ids.iter().position(|id| id == provider).unwrap_or(0) as i32;
    window.set_hemisphere_left_provider_index(role_index(
        window.get_hemisphere_left_provider().as_str(),
    ));
    window.set_hemisphere_right_provider_index(role_index(
        window.get_hemisphere_right_provider().as_str(),
    ));
    window.set_hemisphere_cerebellum_provider_index(role_index(
        window.get_hemisphere_cerebellum_provider().as_str(),
    ));
}

/// SPEC-06 — rebind a hemisphere role to a provider (`neoth hemispheres set
/// --role <r> --provider <p>`). The daemon owns the WAL `0x1F HEMISPHERE_REBOUND`
/// audit + its own validation. Returns an operator-readable status line.
fn set_hemisphere_via_subprocess(role: &str, provider: &str, model: &str) -> String {
    // GOLD-GUI-OVERHAUL — forward the picked model id (HemisphereSlot.model is a
    // free-form Option<String>; the CLI already accepts --model). Empty = leave
    // the role on its provider default. Bound through the typed automation
    // boundary: decode a `HemisphereSetAck`, confirm the acknowledged
    // role/provider(/model) match the request, and read the WAL audit segment
    // back off disk before reporting success.
    let mut args: Vec<&str> = vec!["hemispheres", "set", "--role", role, "--provider", provider];
    if !model.is_empty() {
        args.push("--model");
        args.push(model);
    }
    let expected_model = (!model.is_empty()).then_some(model);
    match run_neothd_json_action::<gui_action::HemisphereSetAck>(&args, "Hemisphere rebind") {
        Ok(ack) => match ack.verify_and_read_back(role, provider, expected_model) {
            Ok(()) => {
                if model.is_empty() {
                    format!("{role} → {provider}")
                } else {
                    format!("{role} → {provider} · {model}")
                }
            }
            Err(error) => format!("hemispheres set failed: {error}"),
        },
        Err(error) => format!("hemispheres set failed: {error}"),
    }
}

fn check_hemisphere_readiness(role: &str) -> String {
    let result = run_neothd_json_action::<gui_action::HemisphereReadinessAck>(
        &["hemispheres", "test", "--role", role],
        "Hemisphere configuration check",
    )
    .and_then(|ack| {
        ack.verify_build_only(role)?;
        Ok((ack.provider, ack.construct_latency_ms))
    });
    match result {
        Ok((provider, latency_ms)) => format!(
            "{role} configuration verified for {provider} ({latency_ms} ms); no provider request was sent"
        ),
        Err(error) => format!("{role} configuration is not ready: {error}"),
    }
}

/// GOLD-GUI-OVERHAUL — the per-role model-picker options for a provider. Local
/// providers (local_qwen/local_ouro) → abliterated-then-standard GGUF refs that
/// fit this PC's VRAM (`neoth models recommend --class …`, so Alex can SELECT a
/// fitting local/abliterated model). Cloud providers → the live model catalog
/// (`neoth catalog list --provider …`). Index 0 is always "(provider default)"
/// so the operator can leave the model unset. Robust: a subprocess hiccup just
/// yields the default-only list, never a hard fail.
fn fetch_hemisphere_model_ids(provider: &str) -> Vec<String> {
    let mut out = vec!["(provider default)".to_string()];
    let Some(bin) = which_neothd() else {
        return out;
    };
    if provider == "local_qwen" || provider == "local_ouro" {
        for class in ["abliterated", "standard"] {
            if let Ok(o) = spawn_neothd_plain(&bin)
                .arg("models")
                .arg("recommend")
                .arg("--class")
                .arg(class)
                .arg("--output")
                .arg("json")
                .output()
                && o.status.success()
            {
                out.extend(panel_logic::parse_model_recommend_refs(
                    &String::from_utf8_lossy(&o.stdout),
                ));
            }
        }
    } else if let Ok(o) = spawn_neothd_plain(&bin)
        .arg("catalog")
        .arg("list")
        .arg("--provider")
        .arg(provider)
        .arg("--output")
        .arg("json")
        .output()
        && o.status.success()
    {
        out.extend(panel_logic::parse_catalog_model_ids(
            &String::from_utf8_lossy(&o.stdout),
            provider,
        ));
    }
    out.dedup();
    out
}

/// SPEC-05 — activate a preset by name (`neoth preset activate <name>`): sets
/// the active marker (does NOT merge into freedom.yaml — that's "Apply active").
/// Returns an operator-readable status line.
fn activate_preset_via_subprocess(name: &str) -> String {
    // Typed receipt + presets.yaml readback — a bare exit code no longer
    // gates which bundle future config loads apply.
    let outcome = run_neothd_json_action::<gui_action::PresetActivateAck>(
        &["preset", "activate", name],
        "Preset activate",
    )
    .and_then(|ack| ack.verify(name))
    .and_then(|()| read_back_active_preset(name));
    match outcome {
        Ok(()) => format!("active preset → {name}"),
        Err(error) => format!("preset activate failed: {error}"),
    }
}

/// SPEC-05 builtin-presets — run `neoth preset apply <name> --dry-run`
/// and parse the JSON plan. Returns the plan on success; None when the
/// binary is missing, the command fails, or the output is unparseable.
fn dry_run_preset_via_subprocess(name: &str) -> Option<panel_logic::ApplyPlan> {
    let bin = which_neothd()?;
    let out = spawn_neothd_plain(&bin)
        .arg("preset")
        .arg("apply")
        .arg(name)
        .arg("--dry-run")
        .output()
        .ok()?;
    if !out.status.success() {
        return None;
    }
    panel_logic::parse_apply_plan(&String::from_utf8_lossy(&out.stdout))
}

/// SPEC-05 builtin-presets — mint a full-auto token then apply <name> with
/// `--yes --gui-confirmed --gui-token <token>`.
/// Returns a human-readable status string.
/// Tolerant `preset list --json` snapshot for post-mutation readback
/// (additive query surface → no `deny_unknown_fields`).
#[derive(Debug, serde::Deserialize)]
struct PresetListSnapshot {
    active: Option<String>,
    #[serde(default)]
    presets: Vec<PresetListRow>,
}

#[derive(Debug, serde::Deserialize)]
struct PresetListRow {
    name: String,
    /// Absent on older CLIs → defaults to false (operator-owned).
    /// Conservative for the delete readback: a missing field causes a
    /// false failure, never a false success.
    #[serde(default)]
    builtin: bool,
}

/// Post-activate readback: presets.yaml must now carry the active marker.
fn read_back_active_preset(name: &str) -> std::result::Result<(), String> {
    let snap = run_neothd_json_action::<PresetListSnapshot>(
        &["preset", "list", "--json"],
        "Preset list readback",
    )?;
    if snap.active.as_deref() != Some(name) {
        return Err(format!(
            "preset readback reports active `{}`, expected `{name}` — presets.yaml did not settle",
            snap.active.as_deref().unwrap_or("<none>")
        ));
    }
    Ok(())
}

/// Post-delete readback. Built-ins legitimately keep the name listed after
/// an operator preset shadowing them is deleted — only a remaining
/// operator-owned row is a failure.
fn read_back_preset_deleted(name: &str) -> std::result::Result<(), String> {
    let snap = run_neothd_json_action::<PresetListSnapshot>(
        &["preset", "list", "--json"],
        "Preset list readback",
    )?;
    let still_there = snap
        .presets
        .iter()
        .any(|row| row.name == name && !row.builtin);
    if still_there {
        return Err(format!(
            "preset readback still lists `{name}` as an operator preset — the delete did not settle"
        ));
    }
    Ok(())
}

/// Post-apply readback shared by every preset-apply surface: a fresh
/// `preset apply <name> --dry-run` (always emitted as JSON, runs before any
/// consent/token gate) must report zero remaining field changes — proof the
/// config now matches the preset. Takes the pinned binary so the GR-05
/// staged-fake test seam keeps working.
fn preset_settled_readback_with(
    bin: &std::path::Path,
    name: &str,
) -> std::result::Result<(), String> {
    let mut command = spawn_neothd_plain(bin);
    command.args(["preset", "apply", name, "--dry-run"]);
    gui_action::run_json::<gui_action::PresetPlanAck>(&mut command, "Preset apply readback")
        .and_then(|plan| plan.verify_settled(name))
}

fn apply_preset_with_fullauto_token(name: &str) -> String {
    let Some(bin) = which_neothd() else {
        return "preset apply: neothd binary not found".to_string();
    };
    // Mint the single-use token through the shared verified ceremony step
    // (same typed boundary as on_full_auto_confirmed).
    let tok = match mint_fullauto_token_verified() {
        Ok(token) => token,
        Err(error) => {
            return format!(
                "Full-auto token mint failed for preset `{name}`: {error} — daemon must be running."
            );
        }
    };
    match spawn_neothd_plain(&bin)
        .arg("preset")
        .arg("apply")
        .arg(name)
        .arg("--yes")
        .arg("--gui-confirmed")
        .arg("--gui-token")
        .arg(&tok)
        .output()
    {
        // Typed readback — the same settled-plan proof as the direct path;
        // the dry-run needs no token (it runs before the ceremony gate).
        Ok(o) if o.status.success() => match preset_settled_readback_with(&bin, name) {
            Ok(()) => format!("Applied preset `{name}` (full-auto)."),
            Err(error) => format!("Preset `{name}` applied, but the readback failed: {error}"),
        },
        Ok(o) => format!(
            "preset apply `{name}` failed (exit {}): {}",
            o.status,
            String::from_utf8_lossy(&o.stderr).trim()
        ),
        Err(e) => format!("preset apply could not start: {e}"),
    }
}

/// SPEC-05 builtin-presets — apply <name> non-interactively with `--yes`
/// (no autonomy token needed — not a full-auto preset).
fn apply_preset_direct(name: &str) -> String {
    let Some(bin) = which_neothd() else {
        return "preset apply: neothd binary not found".to_string();
    };
    // 1. Apply the preset (the write; the CLI prints table text, exit-gated).
    match spawn_neothd_plain(&bin)
        .arg("preset")
        .arg("apply")
        .arg(name)
        .arg("--yes")
        .output()
    {
        Ok(o) if o.status.success() => {}
        Ok(o) => {
            return format!(
                "preset apply `{name}` failed (exit {}): {}",
                o.status,
                String::from_utf8_lossy(&o.stderr).trim()
            );
        }
        Err(e) => return format!("preset apply could not start: {e}"),
    }
    // 2. Typed readback: a post-apply dry-run must report zero remaining field
    //    changes — proof the config now matches the preset. A bare exit code is
    //    not trusted for this freedom.yaml mutation.
    match preset_settled_readback_with(&bin, name) {
        Ok(()) => format!("Applied preset `{name}`."),
        Err(error) => format!("Preset `{name}` applied, but the readback failed: {error}"),
    }
}

/// SPEC-05 builtin-presets — delete an operator preset via
/// `neoth preset delete <name>`.
fn delete_preset_via_subprocess(name: &str) -> String {
    // Typed receipt + list readback (an operator-owned row must be gone;
    // a shadowed built-in staying listed is legitimate).
    let outcome = run_neothd_json_action::<gui_action::PresetDeleteAck>(
        &["preset", "delete", name],
        "Preset delete",
    )
    .and_then(|ack| ack.verify(name).map(|()| ack.removed))
    .and_then(|removed| read_back_preset_deleted(name).map(|()| removed));
    match outcome {
        Ok(true) => format!("Deleted preset `{name}`."),
        Ok(false) => format!("Preset `{name}` was not present (already removed)."),
        Err(error) => format!("preset delete `{name}` failed: {error}"),
    }
}

fn kanban_catalog_command(bin: &Path) -> std::process::Command {
    let mut command = spawn_neothd_plain(bin);
    command
        .arg("kanban")
        .arg("list")
        .arg("--all")
        .arg("--output")
        .arg("json");
    command
}

fn fetch_kanban_board_snapshot() -> KanbanBoardSnapshot {
    let Some(bin) = which_neothd() else {
        return KanbanBoardSnapshot {
            summary: "Run `cargo install --path ../neothd` to enable Code Sessions data."
                .to_string(),
            ..Default::default()
        };
    };

    // Step 1: catalog ALL sessions newest-first. Done/abandoned sessions remain
    // explicitly selectable while Latest (live) resolves only to an active one.
    let list_out = kanban_catalog_command(&bin).output();
    let list_stdout = match list_out {
        Ok(out) if out.status.success() => out.stdout,
        Ok(out) => {
            let stderr = String::from_utf8_lossy(&out.stderr).trim().to_string();
            return KanbanBoardSnapshot {
                summary: format!(
                    "kanban list failed (exit {}): {}",
                    out.status,
                    if stderr.is_empty() {
                        "(no stderr)"
                    } else {
                        &stderr
                    }
                ),
                ..Default::default()
            };
        }
        Err(e) => {
            return KanbanBoardSnapshot {
                summary: format!("kanban list could not start: {e}"),
                ..Default::default()
            };
        }
    };
    let sessions: Vec<CodingSessionJson> = match serde_json::from_slice(&list_stdout) {
        Ok(v) => v,
        Err(e) => {
            return KanbanBoardSnapshot {
                summary: format!("kanban list JSON parse failed: {e}"),
                ..Default::default()
            };
        }
    };
    let requested_override = KANBAN_SESSION_OVERRIDE.load(std::sync::atomic::Ordering::Acquire);
    let catalog = resolve_kanban_catalog(&sessions, requested_override);
    let selected_session = catalog
        .selected_session_index
        .and_then(|index| sessions.get(index))
        .cloned();
    let mut snap = KanbanBoardSnapshot {
        sessions_labels: catalog.labels,
        sessions_ids: catalog.ids,
        active_session_idx: catalog.selector_index,
        catalog_update: KanbanCatalogUpdate::Replace {
            selected_override: catalog.selected_override,
        },
        ..Default::default()
    };
    let Some(selected_session) = selected_session else {
        snap.summary = if sessions.is_empty() {
            "No sessions yet. Run `neoth code \"...\"`, then refresh.".to_string()
        } else {
            "No active session. Pick a historical session or run `neoth code \"...\"`.".to_string()
        };
        return snap;
    };

    // Step 2: full session detail incl. tasks.
    let show_out = spawn_neothd_plain(&bin)
        .arg("kanban")
        .arg("show")
        .arg(selected_session.session_id.to_string())
        .arg("--output")
        .arg("json")
        .output();
    let show_stdout = match show_out {
        Ok(out) if out.status.success() => out.stdout,
        Ok(out) => {
            snap.summary = format!(
                "kanban show #{} failed (exit {})",
                selected_session.session_id, out.status
            );
            return snap;
        }
        Err(e) => {
            snap.summary = format!("kanban show could not start: {e}");
            return snap;
        }
    };
    let envelope: CodingShowEnvelope = match serde_json::from_slice(&show_stdout) {
        Ok(v) => v,
        Err(e) => {
            snap.summary = format!("kanban show JSON parse failed: {e}");
            return snap;
        }
    };

    // Step 3: group tasks by status into the five board buckets.
    snap.summary = format!(
        "Session #{}  [{}]   {}",
        envelope.session.session_id, envelope.session.status, envelope.session.prompt,
    );
    snap.feed = fetch_kanban_feed(&bin);
    for task in envelope.tasks {
        // I10 — pre-format rich card fields via panel_logic helpers so Slint
        // only handles strings/bools (no arithmetic in .slint). Mirror the
        // warm-path construction in `board_json_to_snapshot` exactly.
        let row = KanbanTaskRow {
            task_id: format!("#{}", task.task_id).into(),
            title: task.title.into(),
            hemisphere: task.hemisphere.into(),
            type_chip: task.task_type.into(),
            worker: task.worker.unwrap_or_default().into(),
            tests: panel_logic::format_tests_string(
                task.test_summary.as_ref().map(|ts| ts.passing),
                task.test_summary.as_ref().map(|ts| ts.failing),
                task.test_summary.as_ref().map(|ts| ts.total),
            )
            .into(),
            tests_failing: task
                .test_summary
                .as_ref()
                .map(|ts| ts.failing > 0)
                .unwrap_or(false),
            eta: panel_logic::format_eta(task.eta_ns, task.started_ns).into(),
            parent_ref: task
                .parent_task_id
                .map(|p| format!("#{p}"))
                .unwrap_or_default()
                .into(),
            has_patch: task.patch_path.is_some(),
            // H16 — stamped later by apply_kanban_snapshot.
            selected: false,
        };
        // Wire-form status names mirror `TaskStatus::as_str` in
        // `neothd::coding::types`. Unknown statuses go to BACKLOG so
        // the operator still sees them rather than silent drops.
        match task.status.as_str() {
            "todo" => snap.todo.push(row),
            "in_progress" => snap.in_progress.push(row),
            "review" => snap.review.push(row),
            "done" | "archived" => snap.done.push(row),
            _ => snap.backlog.push(row),
        }
    }
    // HO-02: only probe on the success path (we have a working binary).
    snap.cerebellum_bound = Some(probe_cerebellum_bound(&bin));
    snap
}

// ── Warm-channel board client (B — persistent-stdio-stream, Session 30) ─────
//
// The legacy `fetch_kanban_board_snapshot` above spawns FOUR cold
// subprocesses per call. `GuiStreamClient` holds ONE `neoth gui-stream`
// child open across refreshes and gets the whole board in a single
// NDJSON round-trip. On ANY I/O / protocol error the caller drops the
// client and falls back to the cold path, so the warm channel is a pure
// optimisation — it can never make the board worse than before.

/// Board payload as returned by `neoth gui-stream`'s `board` method.
/// Field-for-field mirror of the daemon's `cli::kanban::GuiBoardSnapshot`.
#[derive(Debug, Deserialize)]
struct GuiBoardJson {
    summary: String,
    cerebellum_bound: bool,
    tasks: Vec<GuiBoardTaskJson>,
    feed: Vec<FeedEntryJson>,
}

/// I10 — field-for-field mirror of `cli::kanban::GuiBoardTask`.
/// `#[serde(default)]` on every I10 addition keeps warm-channel clients
/// deserialising cleanly against a daemon that predates this build.
#[derive(Debug, Default, Deserialize)]
struct GuiBoardTaskJson {
    task_id: i64,
    title: String,
    hemisphere: String,
    status: String,
    #[serde(default)]
    task_type: String,
    #[serde(default)]
    worker: Option<String>,
    #[serde(default)]
    parent_task_id: Option<i64>,
    #[serde(default)]
    eta_ns: Option<u64>,
    #[serde(default)]
    started_ns: Option<u64>,
    #[serde(default)]
    has_patch: bool,
    #[serde(default)]
    tests_passing: Option<u32>,
    #[serde(default)]
    tests_failing: Option<u32>,
    #[serde(default)]
    tests_total: Option<u32>,
}

/// Map the warm-channel board payload into the same `KanbanBoardSnapshot`
/// the cold path produces. The status-bucketing + feed `rev()`+map mirror
/// `fetch_kanban_board_snapshot` (task loop) and `fetch_kanban_feed`
/// EXACTLY, so warm and cold are byte-for-byte equivalent in the UI.
fn board_json_to_snapshot(b: GuiBoardJson) -> KanbanBoardSnapshot {
    let mut snap = KanbanBoardSnapshot {
        summary: b.summary,
        cerebellum_bound: Some(b.cerebellum_bound),
        ..Default::default()
    };
    for t in b.tasks {
        // I10 — same pre-format helpers as the cold path so both produce
        // identical KanbanTaskRow values (warm/cold equivalence invariant).
        let row = KanbanTaskRow {
            task_id: format!("#{}", t.task_id).into(),
            title: t.title.into(),
            hemisphere: t.hemisphere.into(),
            type_chip: t.task_type.into(),
            worker: t.worker.unwrap_or_default().into(),
            tests: panel_logic::format_tests_string(
                t.tests_passing,
                t.tests_failing,
                t.tests_total,
            )
            .into(),
            tests_failing: t.tests_failing.map(|f| f > 0).unwrap_or(false),
            eta: panel_logic::format_eta(t.eta_ns, t.started_ns).into(),
            parent_ref: t
                .parent_task_id
                .map(|p| format!("#{p}"))
                .unwrap_or_default()
                .into(),
            has_patch: t.has_patch,
            // H16 — stamped later by apply_kanban_snapshot.
            selected: false,
        };
        match t.status.as_str() {
            "todo" => snap.todo.push(row),
            "in_progress" => snap.in_progress.push(row),
            "review" => snap.review.push(row),
            "done" | "archived" => snap.done.push(row),
            _ => snap.backlog.push(row),
        }
    }
    // Server returns feed oldest-first (WAL append order); the right rail
    // wants most-recent-first — same `.rev()` as `fetch_kanban_feed`.
    snap.feed = b
        .feed
        .into_iter()
        .rev()
        .map(|e| KanbanFeedRow {
            ts: format_hms_from_ns(e.ts_ns).into(),
            actor: e.actor.into(),
            message: e.message.into(),
        })
        .collect();
    snap
}

/// Per-request read budget. The warm channel is local IPC — a healthy
/// daemon answers in single-digit ms. 5s is generous slack; exceeding it
/// means the child is hung, so `request_board` gives up and the caller
/// falls back to the cold path (and drops this client so the next tick
/// reconnects). Bounds how long a worker thread can sit on a stalled read.
const GUI_STREAM_READ_TIMEOUT: std::time::Duration = std::time::Duration::from_secs(5);

/// Persistent client to a `neoth gui-stream` child. Owns the child + its
/// stdin, plus an `mpsc` receiver fed by a dedicated reader thread that
/// owns stdout. Decoupling the blocking read into its own thread means
/// `request_board` waits on a `recv_timeout` (never an unbounded
/// `read_line`), so a hung daemon can neither pin the per-tick worker
/// thread nor delay this client's `Drop` (and thus the child kill) past
/// the timeout. Dropping the client kills the child, which EOFs the
/// reader thread.
/// DES-10 — one entry in the live channel activity ring.
/// Contains ONLY traffic METADATA: who/when/direction/size.
/// WAL message bodies are hashed by design and never appear here.
#[derive(Debug, Clone)]
struct ChannelActivity {
    /// Stable identity used to suppress history/live-WAL replay duplicates.
    identity: String,
    /// "in" | "out" | "proactive" | "blocked"
    direction: String,
    channel: String,
    peer: String,
    bytes: u64,
    ts_unix: u64,
    /// Empty for ordinary channel traffic; canonical terminal display label
    /// for proactive records.
    outcome: String,
    verification: String,
}

/// Parse `{"push":true,"channel_feed":[...]}` tolerantly.
/// Returns `None` if the line is not a push frame — caller forwards normally.
fn parse_channel_feed_push(line: &str) -> Option<Vec<ChannelActivity>> {
    let v: serde_json::Value = serde_json::from_str(line.trim()).ok()?;
    if v.get("push").and_then(|b| b.as_bool()) != Some(true) {
        return None;
    }
    let arr = v.get("channel_feed")?.as_array()?;
    let entries: Vec<ChannelActivity> = arr
        .iter()
        .filter_map(|e| {
            // `event_id` presence gates what counts as a real feed row;
            // the value itself has no consumer (no replay/dedup on this side).
            let event_id = e.get("event_id")?;
            Some(ChannelActivity {
                identity: e
                    .get("identity")
                    .and_then(|value| value.as_str())
                    .map(str::to_string)
                    .unwrap_or_else(|| format!("legacy:{event_id}")),
                direction: e
                    .get("direction")
                    .and_then(|d| d.as_str())
                    .unwrap_or("in")
                    .to_string(),
                channel: e
                    .get("channel")
                    .and_then(|c| c.as_str())
                    .unwrap_or("")
                    .to_string(),
                peer: e
                    .get("peer")
                    .and_then(|p| p.as_str())
                    .unwrap_or("")
                    .to_string(),
                bytes: e.get("bytes").and_then(|b| b.as_u64()).unwrap_or(0),
                ts_unix: e.get("ts_unix").and_then(|t| t.as_u64()).unwrap_or(0),
                outcome: e
                    .get("outcome")
                    .and_then(|value| value.as_str())
                    .unwrap_or("")
                    .to_string(),
                verification: e
                    .get("verification")
                    .and_then(|value| value.as_str())
                    .unwrap_or("")
                    .to_string(),
            })
        })
        .collect();
    Some(entries)
}

fn load_proactive_history_activity(home: &Path) -> Result<Vec<ChannelActivity>> {
    const MAX_DISPLAY: usize = 60;
    let records = neothd::daemon::proactive_egress::read_delivery_history(home)
        .context("read private proactive delivery history")?;
    let first = records.len().saturating_sub(MAX_DISPLAY);
    Ok(records
        .into_iter()
        .skip(first)
        .map(|record| ChannelActivity {
            identity: format!("proactive:{}", record.intent_id()),
            direction: "proactive".to_string(),
            channel: record.target_channel().to_string(),
            peer: record.dedup_sha256().chars().take(8).collect(),
            bytes: record.message_bytes() as u64,
            ts_unix: record.delivered_at_unix().max(0) as u64,
            outcome: record.outcome().display_label().to_string(),
            verification: record.verification_label().to_string(),
        })
        .collect())
}

fn merge_channel_activity_rows(window: &MainWindow, entries: Vec<ChannelActivity>) {
    use slint::Model as _;
    use slint::{ModelRc, VecModel};

    const MAX_DISPLAY: usize = 60;
    let mut rows: Vec<ChannelActivityRow> = (0..window.get_channel_activity().row_count())
        .filter_map(|index| window.get_channel_activity().row_data(index))
        .collect();
    let mut known: std::collections::HashSet<String> =
        rows.iter().map(|row| row.event_id.to_string()).collect();
    for entry in entries {
        if !known.insert(entry.identity.clone()) {
            continue;
        }
        rows.push(ChannelActivityRow {
            event_id: entry.identity.into(),
            direction: entry.direction.into(),
            channel: entry.channel.into(),
            peer: entry.peer.into(),
            bytes: fmt_event_bytes(entry.bytes).into(),
            ts: fmt_ts_unix(entry.ts_unix).into(),
            outcome: entry.outcome.into(),
            verification: entry.verification.into(),
        });
    }
    if rows.len() > MAX_DISPLAY {
        rows.drain(0..rows.len() - MAX_DISPLAY);
    }
    window.set_channel_activity(ModelRc::new(VecModel::from(rows)));
}

/// Parse a spontaneous board frame and keep it off the request/response
/// channel. The reader thread stores only the newest snapshot because every
/// push is a complete board replacement.
fn parse_board_push(line: &str) -> Option<GuiBoardJson> {
    let value: serde_json::Value = serde_json::from_str(line.trim()).ok()?;
    if value.get("push").and_then(|flag| flag.as_bool()) != Some(true) {
        return None;
    }
    serde_json::from_value(value.get("board")?.clone()).ok()
}

fn take_pending_board(
    pending: &std::sync::Mutex<Option<GuiBoardJson>>,
) -> Option<KanbanBoardSnapshot> {
    pending
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .take()
        .map(board_json_to_snapshot)
}

#[cfg(test)]
mod channel_feed_tests {
    use super::{parse_board_push, parse_channel_feed_push, take_pending_board};

    #[test]
    fn parses_valid_push_frame() {
        let line = r#"{"push":true,"channel_feed":[{"event_id":7,"identity":"proactive:abc","direction":"proactive","channel":"telegram","peer":"u42","bytes":128,"ts_unix":1720000000,"outcome":"crash_unknown","verification":"wal_verified"}]}"#;
        let result = parse_channel_feed_push(line).expect("should parse");
        assert_eq!(result.len(), 1);
        assert_eq!(result[0].identity, "proactive:abc");
        assert_eq!(result[0].direction, "proactive");
        assert_eq!(result[0].channel, "telegram");
        assert_eq!(result[0].peer, "u42");
        assert_eq!(result[0].bytes, 128);
        assert_eq!(result[0].ts_unix, 1_720_000_000);
        assert_eq!(result[0].outcome, "crash_unknown");
        assert_eq!(result[0].verification, "wal_verified");
    }

    #[test]
    fn rejects_non_push_json() {
        let line = r#"{"ok":true,"board":{}}"#;
        assert!(parse_channel_feed_push(line).is_none());
    }

    #[test]
    fn rejects_non_json() {
        assert!(parse_channel_feed_push("not json at all").is_none());
    }

    #[test]
    fn tolerates_missing_optional_fields() {
        let line = r#"{"push":true,"channel_feed":[{"event_id":1}]}"#;
        let result = parse_channel_feed_push(line).expect("should parse");
        assert_eq!(result.len(), 1);
        assert_eq!(result[0].bytes, 0);
        assert_eq!(result[0].direction, "in");
    }

    #[test]
    fn board_push_is_consumed_once_as_a_live_snapshot() {
        let line = r#"{"push":true,"board":{"summary":"Session #7","cerebellum_bound":true,"tasks":[{"task_id":9,"title":"wire it","hemisphere":"left","status":"in_progress"}],"feed":[]}}"#;
        let pending = std::sync::Mutex::new(parse_board_push(line));

        let snapshot = take_pending_board(&pending).expect("board push must reach the consumer");
        assert_eq!(snapshot.summary, "Session #7");
        assert_eq!(snapshot.in_progress.len(), 1);
        assert!(
            take_pending_board(&pending).is_none(),
            "a consumed complete snapshot must not replay on every timer tick"
        );
    }

    #[test]
    fn board_response_is_not_misclassified_as_a_push() {
        let line = r#"{"id":3,"ok":true,"board":{"summary":"s","cerebellum_bound":true,"tasks":[],"feed":[]}}"#;
        assert!(parse_board_push(line).is_none());
    }
}

const CHANNEL_ACTIVITY_RING_CAP: usize = 100;

struct GuiStreamClient {
    child: std::process::Child,
    stdin: std::process::ChildStdin,
    /// Lines the reader thread pulled off the child's stdout, in order.
    /// Push lines are intercepted by the reader thread and routed to either
    /// `activity_ring` or `pending_board`, so request methods see only
    /// id-bearing responses.
    rx: std::sync::mpsc::Receiver<String>,
    /// Capped ring of the latest channel-activity push entries. Shared with
    /// the reader thread (Arc<Mutex>) and drained by the UI timer.
    activity_ring: std::sync::Arc<std::sync::Mutex<std::collections::VecDeque<ChannelActivity>>>,
    /// Newest complete spontaneous board snapshot. The timer consumes this
    /// before issuing an explicit board request, giving TRAIL-02 a live GUI
    /// consumer while naturally coalescing bursts.
    pending_board: std::sync::Arc<std::sync::Mutex<Option<GuiBoardJson>>>,
    next_id: u64,
}

impl GuiStreamClient {
    /// Spawn `neoth gui-stream` with piped stdin/stdout (stderr to null).
    /// `spawn_neothd_plain` sets `NEOTH_LOG=error`, so stdout carries only
    /// the NDJSON responses; `request_board` additionally skips any stray
    /// non-JSON line as a belt-and-suspenders guard. Errors propagate so
    /// the caller falls back to the cold path.
    fn connect(bin: &Path) -> std::io::Result<Self> {
        use std::process::Stdio;
        let mut child = spawn_neothd_plain(bin)
            .arg("gui-stream")
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::null())
            .spawn()?;
        let stdin = child.stdin.take().ok_or_else(|| {
            std::io::Error::new(std::io::ErrorKind::BrokenPipe, "gui-stream: no stdin pipe")
        })?;
        let stdout = child.stdout.take().ok_or_else(|| {
            std::io::Error::new(std::io::ErrorKind::BrokenPipe, "gui-stream: no stdout pipe")
        })?;
        // Dedicated reader thread owns stdout, pushes whole lines onto the
        // channel. It exits when the child dies (read_line → EOF) or when
        // the receiver is dropped (send error). Detached on purpose: it is
        // self-terminating and cheap, and we never want to JOIN it from a
        // drop path that might otherwise block on a stalled read.
        //
        // Push lines are intercepted here: channel metadata goes to the ring,
        // complete boards replace the pending snapshot. Neither is forwarded
        // to `tx`, so request/response matching remains clean.
        let (tx, rx) = std::sync::mpsc::channel::<String>();
        let activity_ring =
            std::sync::Arc::new(std::sync::Mutex::new(std::collections::VecDeque::<
                ChannelActivity,
            >::new()));
        let ring_writer = activity_ring.clone();
        let pending_board = std::sync::Arc::new(std::sync::Mutex::new(None));
        let board_writer = pending_board.clone();
        std::thread::spawn(move || {
            use std::io::BufRead;
            let mut reader = std::io::BufReader::new(stdout);
            let mut line = String::new();
            loop {
                line.clear();
                match reader.read_line(&mut line) {
                    Ok(0) => break, // EOF — child exited
                    Ok(_) => {
                        // Intercept push frames — route to ring, not response chan.
                        if let Some(entries) = parse_channel_feed_push(&line) {
                            if let Ok(mut ring) = ring_writer.lock() {
                                for entry in entries {
                                    ring.push_back(entry);
                                }
                                while ring.len() > CHANNEL_ACTIVITY_RING_CAP {
                                    ring.pop_front();
                                }
                            }
                            // Do NOT forward push lines to tx.
                        } else if let Some(board) = parse_board_push(&line) {
                            if let Ok(mut pending) = board_writer.lock() {
                                *pending = Some(board);
                            }
                            // Complete board pushes are consumed by the timer,
                            // never confused with an id-bearing response.
                        } else if tx.send(std::mem::take(&mut line)).is_err() {
                            break; // receiver gone — client dropped
                        }
                    }
                    Err(_) => break, // pipe error — give up
                }
            }
        });
        Ok(Self {
            child,
            stdin,
            rx,
            activity_ring,
            pending_board,
            next_id: 1,
        })
    }

    /// One `{"id":N,"method":"board"}` round-trip → mapped snapshot.
    /// `None` on any I/O, EOF, timeout, protocol (`ok:false`), or parse
    /// failure; the caller then drops `self` and falls back to the cold
    /// path. Never blocks longer than `GUI_STREAM_READ_TIMEOUT` per line.
    fn request_board(&mut self) -> Option<KanbanBoardSnapshot> {
        use std::io::Write;
        let id = self.next_id;
        self.next_id = self.next_id.wrapping_add(1);
        // Hand-format the request line — no need to pull in a serialiser
        // for a two-field object with a numeric id + a literal method.
        let req = format!("{{\"id\":{id},\"method\":\"board\"}}\n");
        self.stdin.write_all(req.as_bytes()).ok()?;
        self.stdin.flush().ok()?;

        // Pull lines (via the reader thread) until we get a parseable JSON
        // response object. `NEOTH_LOG=error` already keeps stdout free of
        // the daemon's INFO banner, but this is the robustness net: ANY
        // stray non-JSON line (e.g. an error-level tracing event) is
        // skipped. Bounded by MAX_SKIP (chatty stream) AND by the per-recv
        // timeout (hung daemon) — both fall back to the cold path.
        const MAX_SKIP: usize = 32;
        for _ in 0..MAX_SKIP {
            let line = self.rx.recv_timeout(GUI_STREAM_READ_TIMEOUT).ok()?;
            let trimmed = line.trim();
            if trimmed.is_empty() {
                continue;
            }
            let Ok(v) = serde_json::from_str::<serde_json::Value>(trimmed) else {
                continue; // not JSON — a log line; skip it
            };
            // A genuine response carries an `ok` bool. Anything else that
            // happens to be JSON but lacks it is not our response — skip.
            let Some(ok) = v.get("ok").and_then(|b| b.as_bool()) else {
                continue;
            };
            if !ok {
                tracing::warn!(response = %trimmed, "gui-stream: board request not ok");
                return None;
            }
            let board: GuiBoardJson = serde_json::from_value(v.get("board")?.clone()).ok()?;
            return Some(board_json_to_snapshot(board));
        }
        // Too many non-response lines — treat as a broken channel.
        None
    }

    /// One `{"id":N,"method":"activity"}` round-trip → `(mood, caption)`. Same
    /// robustness net + fallback semantics as `request_board`. Best-effort: a
    /// `None` just skips a Buddy update this tick.
    fn request_activity(&mut self) -> Option<(String, String)> {
        use std::io::Write;
        let id = self.next_id;
        self.next_id = self.next_id.wrapping_add(1);
        let req = format!("{{\"id\":{id},\"method\":\"activity\"}}\n");
        self.stdin.write_all(req.as_bytes()).ok()?;
        self.stdin.flush().ok()?;
        const MAX_SKIP: usize = 32;
        for _ in 0..MAX_SKIP {
            let line = self.rx.recv_timeout(GUI_STREAM_READ_TIMEOUT).ok()?;
            let trimmed = line.trim();
            if trimmed.is_empty() {
                continue;
            }
            let Ok(v) = serde_json::from_str::<serde_json::Value>(trimmed) else {
                continue;
            };
            let Some(ok) = v.get("ok").and_then(|b| b.as_bool()) else {
                continue;
            };
            if !ok {
                return None;
            }
            let activity = v.get("activity")?.as_str()?.to_string();
            let caption = v
                .get("caption")
                .and_then(|c| c.as_str())
                .unwrap_or("")
                .to_string();
            return Some((activity, caption));
        }
        None
    }

    /// DES-10 — drain all accumulated channel-activity entries from the ring,
    /// returning them newest-last (FIFO order). Empties the ring so the next
    /// drain only yields new entries. Called from the UI timer thread; the
    /// lock is held only for the drain, not across invoke_from_event_loop.
    fn drain_channel_activity(&self) -> Vec<ChannelActivity> {
        self.activity_ring
            .lock()
            .map(|mut ring| ring.drain(..).collect())
            .unwrap_or_default()
    }

    fn take_pushed_board(&self) -> Option<KanbanBoardSnapshot> {
        take_pending_board(&self.pending_board)
    }
}

impl Drop for GuiStreamClient {
    fn drop(&mut self) {
        // Kill + reap the child. This closes the child's stdout, so the
        // detached reader thread's `read_line` returns EOF and the thread
        // exits on its own. Because `request_board` waits on a bounded
        // `recv_timeout` (not a raw blocking `read_line`), this Drop is
        // never gated behind an unbounded read — it runs promptly even if
        // the daemon had gone unresponsive.
        let _ = self.child.kill();
        let _ = self.child.wait();
    }
}

/// Board fetch for the live-tail timer: try the warm `gui-stream` channel
/// first (lazy-connecting the client on first use), fall back to the cold
/// 4-subprocess path on any failure. A failed warm request drops the dead
/// client so the next tick reconnects from scratch.
/// Warm-only activity probe for the docked Buddy. Reuses the SHARED gui-stream
/// client (serialised by its mutex with the board fetch, so requests never
/// interleave on the wire). `None` when there's no warm channel — the Buddy
/// keeps its current mood that tick (no cold-path subprocess for ambient mood).
fn fetch_activity_warm(
    client: &std::sync::Mutex<Option<GuiStreamClient>>,
) -> Option<(String, String)> {
    let bin = which_neothd()?;
    let mut guard = client.lock().unwrap_or_else(|p| p.into_inner());
    if guard.is_none() {
        // Spawn the warm channel on first activity poll so the Buddy reflects
        // the daemon even if the operator never opens the Code Sessions tab.
        match GuiStreamClient::connect(&bin) {
            Ok(c) => *guard = Some(c),
            Err(_) => return None,
        }
    }
    let c = guard.as_mut()?;
    match c.request_activity() {
        Some(v) => Some(v),
        None => {
            // Broken channel — drop it so the next fetch reconnects.
            *guard = None;
            None
        }
    }
}

fn fetch_board_warm_or_cold(
    client: &std::sync::Mutex<Option<GuiStreamClient>>,
) -> KanbanBoardSnapshot {
    // A3 — only the explicit Latest (live) sentinel uses the warm channel;
    // concrete historical/live pins require the cold `kanban show <id>` path.
    if KANBAN_SESSION_OVERRIDE.load(std::sync::atomic::Ordering::Acquire) != KANBAN_LATEST_SESSION {
        return fetch_kanban_board_snapshot();
    }
    let Some(bin) = which_neothd() else {
        return fetch_kanban_board_snapshot(); // surfaces the "install" hint
    };
    // Recover from a poisoned lock rather than panicking the worker — the
    // guarded value is just a reconnectable client, never corrupt state.
    let mut guard = client.lock().unwrap_or_else(|p| p.into_inner());
    if guard.is_none() {
        match GuiStreamClient::connect(&bin) {
            Ok(c) => *guard = Some(c),
            Err(e) => {
                tracing::warn!(error = %e, "gui-stream: connect failed; using cold path");
                return fetch_kanban_board_snapshot();
            }
        }
    }
    if let Some(c) = guard.as_mut() {
        if let Some(snap) = c.take_pushed_board() {
            return snap;
        }
        if let Some(snap) = c.request_board() {
            return snap;
        }
        // Warm request failed — drop the dead child so the next tick
        // reconnects, and serve this tick from the cold path.
        tracing::warn!("gui-stream: warm request failed; dropping client + cold fallback");
        *guard = None;
    }
    fetch_kanban_board_snapshot()
}

/// HO-02: probe whether a Cerebellum provider is bound. Runs
/// `neoth hemispheres show --output json` and returns true UNLESS we can
/// positively determine the cerebellum role has no provider AND there is
/// no single-mode fallback. Fail-safe (true) on any spawn/parse error so
/// a transient probe failure never false-alarms the operator with the
/// "no Cerebellum bound" banner.
fn probe_cerebellum_bound(bin: &Path) -> bool {
    let out = spawn_neothd_plain(bin)
        .arg("hemispheres")
        .arg("show")
        .arg("--output")
        .arg("json")
        .output();
    let stdout = match out {
        Ok(o) if o.status.success() => o.stdout,
        _ => return true, // fail-safe: don't alarm when the probe can't run
    };
    let v: serde_json::Value = match serde_json::from_slice(&stdout) {
        Ok(v) => v,
        Err(_) => return true,
    };
    // single-mode: every role routes to the single fallback provider.
    if v.get("single_provider_fallback")
        .and_then(|x| x.as_str())
        .is_some()
    {
        return true;
    }
    // per-role mode: the cerebellum role must carry a provider string.
    if let Some(roles) = v.get("roles").and_then(|x| x.as_array()) {
        for r in roles {
            if r.get("role").and_then(|x| x.as_str()) == Some("cerebellum") {
                return r.get("provider").and_then(|x| x.as_str()).is_some();
            }
        }
    }
    // No fallback + no cerebellum role row → decompose can't run.
    false
}

/// Pick #8 step 3 — Activity feed right rail. Subprocess
/// `neothd kanban watch --output json` reads the latest kanban frames
/// from `~/.neoth/wal/`, returns `Vec<FeedEntryJson>`. We collapse
/// failures to an empty feed (degraded UI is fine — board still works).
fn fetch_kanban_feed(bin: &Path) -> Vec<KanbanFeedRow> {
    let out = spawn_neothd_plain(bin)
        .arg("kanban")
        .arg("watch")
        .arg("--output")
        .arg("json")
        .arg("--limit")
        .arg("50")
        .output();
    let stdout = match out {
        Ok(o) if o.status.success() => o.stdout,
        Ok(o) => {
            tracing::warn!(
                exit = ?o.status,
                stderr = %String::from_utf8_lossy(&o.stderr).trim(),
                "kanban watch failed; rendering empty feed",
            );
            return Vec::new();
        }
        Err(e) => {
            tracing::warn!(error = %e, "kanban watch could not start; rendering empty feed");
            return Vec::new();
        }
    };
    let entries: Vec<FeedEntryJson> = match serde_json::from_slice(&stdout) {
        Ok(v) => v,
        Err(e) => {
            tracing::warn!(error = %e, "kanban watch JSON parse failed; rendering empty feed");
            return Vec::new();
        }
    };
    // Most-recent-first for the right rail — the WAL scan returns
    // newest-last (append order), so reverse for the UI.
    entries
        .into_iter()
        .rev()
        .map(|e| KanbanFeedRow {
            ts: format_hms_from_ns(e.ts_ns).into(),
            actor: e.actor.into(),
            message: e.message.into(),
        })
        .collect()
}

/// Detail-pane subprocess fetch. Strips the leading `#` from the
/// Slint-formatted task id, calls `neoth kanban task <id> --output
/// json`, parses the `{task, comments}` envelope, returns the
/// formatted `KanbanCommentRow` vec. Empty vec on any failure — the
/// detail pane just renders without a comment thread instead of
/// surfacing a subprocess error in the UI.
fn fetch_task_comments(task_id_with_hash: &str) -> Vec<KanbanCommentRow> {
    let id = task_id_with_hash
        .strip_prefix('#')
        .unwrap_or(task_id_with_hash);
    let Some(bin) = which_neothd() else {
        return Vec::new();
    };
    let out = spawn_neothd_plain(&bin)
        .arg("kanban")
        .arg("task")
        .arg(id)
        .arg("--output")
        .arg("json")
        .output();
    let stdout = match out {
        Ok(o) if o.status.success() => o.stdout,
        Ok(o) => {
            tracing::warn!(
                task_id = id,
                exit = ?o.status,
                "kanban task fetch failed; rendering empty comments"
            );
            return Vec::new();
        }
        Err(e) => {
            tracing::warn!(task_id = id, error = %e, "kanban task fetch could not start");
            return Vec::new();
        }
    };
    let envelope: TaskDetailEnvelope = match serde_json::from_slice(&stdout) {
        Ok(v) => v,
        Err(e) => {
            tracing::warn!(error = %e, "kanban task JSON parse failed");
            return Vec::new();
        }
    };
    envelope
        .comments
        .into_iter()
        .map(|c| KanbanCommentRow {
            ts: format_hms_from_ns(c.created_ns).into(),
            author: c.author.into(),
            body: c.body.into(),
        })
        .collect()
}

/// Format a unix-ns timestamp as `HH:MM` for the activity feed. Mirrors
/// `neothd::cli::kanban::format_ts_short` but emits HH:MM (not HH:MM:SS)
/// because the feed rail is narrow + the seconds add visual noise.
fn format_hms_from_ns(ts_ns: u64) -> String {
    let secs = ts_ns / 1_000_000_000;
    let h = (secs / 3600) % 24;
    let m = (secs / 60) % 60;
    format!("{h:02}:{m:02}")
}

/// H16 — re-stamp `selected` flags on the five in-memory column models from
/// the KANBAN_SELECTION store, without refetching the board. Runs on the
/// event loop (models are UI-thread-owned).
fn restamp_kanban_selection(window: &MainWindow) {
    use slint::{Model as _, ModelRc, VecModel};
    let sel = KANBAN_SELECTION.lock().expect("kanban selection lock");
    let stamp = |model: ModelRc<KanbanTaskRow>| -> ModelRc<KanbanTaskRow> {
        let rows: Vec<KanbanTaskRow> = model
            .iter()
            .map(|mut r| {
                r.selected = sel.contains(r.task_id.as_str());
                r
            })
            .collect();
        ModelRc::new(VecModel::from(rows))
    };
    window.set_kanban_backlog(stamp(window.get_kanban_backlog()));
    window.set_kanban_todo(stamp(window.get_kanban_todo()));
    window.set_kanban_in_progress(stamp(window.get_kanban_in_progress()));
    window.set_kanban_review(stamp(window.get_kanban_review()));
    window.set_kanban_done(stamp(window.get_kanban_done()));
    window.set_kanban_selected_count(sel.len() as i32);
}

/// Push a `KanbanBoardSnapshot` into the Slint properties. Warm snapshots and
/// degraded catalog probes preserve the selector; a successful catalog probe
/// replaces it even when empty. The caller must pass the selection-generation
/// guard before invoking this function.
fn apply_kanban_snapshot(window: &MainWindow, mut snap: KanbanBoardSnapshot) {
    use slint::{ModelRc, VecModel};
    // H16 — stamp batch-selection onto the fresh rows and drop stale ids
    // (tasks that vanished from the board must not stay silently selected).
    {
        let mut sel = KANBAN_SELECTION.lock().expect("kanban selection lock");
        let known: Vec<String> = snap
            .backlog
            .iter()
            .chain(&snap.todo)
            .chain(&snap.in_progress)
            .chain(&snap.review)
            .chain(&snap.done)
            .map(|r| r.task_id.to_string())
            .collect();
        sel.retain_known(&known);
        for col in [
            &mut snap.backlog,
            &mut snap.todo,
            &mut snap.in_progress,
            &mut snap.review,
            &mut snap.done,
        ] {
            for task in col.iter_mut() {
                task.selected = sel.contains(task.task_id.as_str());
            }
        }
        window.set_kanban_selected_count(sel.len() as i32);
    }
    window.set_kanban_backlog(ModelRc::new(VecModel::from(snap.backlog)));
    window.set_kanban_todo(ModelRc::new(VecModel::from(snap.todo)));
    window.set_kanban_in_progress(ModelRc::new(VecModel::from(snap.in_progress)));
    window.set_kanban_review(ModelRc::new(VecModel::from(snap.review)));
    window.set_kanban_done(ModelRc::new(VecModel::from(snap.done)));
    window.set_kanban_feed(ModelRc::new(VecModel::from(snap.feed)));
    window.set_kanban_session_summary(snap.summary.into());
    // A3 — an authoritative empty catalog deliberately clears the model and
    // id map. `Preserve` is reserved for warm frames and transient failures.
    if let KanbanCatalogUpdate::Replace { selected_override } = snap.catalog_update {
        let previous =
            KANBAN_SESSION_OVERRIDE.swap(selected_override, std::sync::atomic::Ordering::AcqRel);
        if previous != selected_override {
            // A stale/missing pin was reset to Latest. Invalidate any other
            // fetch that captured the old pin alongside this successful list.
            KANBAN_SELECTION_GENERATION.fetch_add(1, std::sync::atomic::Ordering::AcqRel);
        }
        *KANBAN_SESSION_IDS.lock().unwrap_or_else(|e| e.into_inner()) = snap.sessions_ids;
        window.set_kanban_sessions(ModelRc::new(VecModel::from(snap.sessions_labels)));
        window.set_kanban_session_idx(snap.active_session_idx);
    }
    // HO-02: None (degraded / un-probed path) → true, so the banner only
    // shows when we positively determined no Cerebellum is bound.
    window.set_cerebellum_bound(snap.cerebellum_bound.unwrap_or(true));
}

/// R2-P0-1: GUI chat dispatch via the `neothd chat` subprocess. Returns
/// `Ok(reply_text)` on success or `Err(error_for_bubble)` so the caller
/// can render either path as a chat bubble.
///
/// Routing through the daemon binary (same pattern as
/// `probe_hardware_via_subprocess`) keeps the GUI crate decoupled from
/// daemon internals while ensuring GUI Send hits EXACTLY the same
/// provider / WAL / permission / cost / autonomy code path as
/// `neothd chat` from a terminal — that's the R2 done-criterion.
/// Chat-feel parity (openhuman): split a NEOTH assistant reply into
/// multiple bubbles at blank-line (paragraph) boundaries, so a
/// multi-paragraph reply reads as a conversation cluster instead of one
/// wall of text. Mirrors openhuman's render-time `splitAgentMessageInto
/// Bubbles` — a pure line-iterator state machine, no Slint/UI dependency,
/// fully unit-testable.
///
/// Rules:
/// - A fenced code block (```…```) is kept INTACT as one bubble — blank
///   lines inside a fence never split it (avoids fragmenting code/tables).
/// - A blank line OUTSIDE a fence ends the current bubble.
/// - Segments that are only a visual separator (`---` / `***` / `___`) are
///   dropped (openhuman's `isVisualSeparatorOnly`) so horizontal rules
///   don't render as empty bubbles.
/// - Each emitted segment is trimmed. A non-empty reply always yields at
///   least one bubble (falls back to the whole trimmed reply).
pub fn segment_reply_into_bubbles(reply: &str) -> Vec<String> {
    fn push_segment(cur: &[&str], out: &mut Vec<String>) {
        let trimmed = cur.join("\n");
        let trimmed = trimmed.trim();
        if !trimmed.is_empty() && !is_visual_separator_only(trimmed) {
            out.push(trimmed.to_string());
        }
    }
    let mut bubbles: Vec<String> = Vec::new();
    let mut current: Vec<&str> = Vec::new();
    let mut in_fence = false;
    for line in reply.lines() {
        if line.trim_start().starts_with("```") {
            in_fence = !in_fence;
            current.push(line);
            continue;
        }
        if !in_fence && line.trim().is_empty() {
            push_segment(&current, &mut bubbles);
            current.clear();
        } else {
            current.push(line);
        }
    }
    push_segment(&current, &mut bubbles);
    if bubbles.is_empty() {
        let t = reply.trim();
        if !t.is_empty() {
            bubbles.push(t.to_string());
        }
    }
    bubbles
}

/// True when `s` (already trimmed, non-empty) is ONLY a Markdown
/// horizontal-rule / visual separator — 3+ of `-`/`*`/`_` (allowing
/// interspersed spaces, as Markdown permits `- - -`). Such a segment
/// carries no content and is dropped during bubble segmentation.
fn is_visual_separator_only(s: &str) -> bool {
    let non_space: Vec<char> = s.chars().filter(|c| !c.is_whitespace()).collect();
    non_space.len() >= 3
        && non_space.iter().all(|&c| c == '-' || c == '*' || c == '_')
        && non_space.iter().all(|&c| c == non_space[0])
}

/// Borrow at most `max_chars` Unicode scalar values without ever slicing in
/// the middle of a UTF-8 code point.
fn utf8_prefix(value: &str, max_chars: usize) -> &str {
    value
        .char_indices()
        .nth(max_chars)
        .map_or(value, |(byte_index, _)| &value[..byte_index])
}

fn utf8_suffix(value: &str, max_chars: usize) -> &str {
    if max_chars == 0 {
        return &value[value.len()..];
    }
    value
        .char_indices()
        .rev()
        .nth(max_chars - 1)
        .map_or(value, |(byte_index, _)| &value[byte_index..])
}

fn install_chat_launch_gate(
    slot: &std::sync::Mutex<Option<ChatLaunchGate>>,
    request_id: ChatStreamRequestId,
) -> std::result::Result<ChatLaunchGate, String> {
    let gate = ChatLaunchGate::new(request_id);
    let mut current = slot
        .lock()
        .map_err(|_| "chat launch authority is unavailable".to_string())?;
    *current = Some(gate.clone());
    Ok(gate)
}

fn chat_launch_gate_for_request(
    slot: &std::sync::Mutex<Option<ChatLaunchGate>>,
    request_id: ChatStreamRequestId,
) -> std::result::Result<ChatLaunchGate, String> {
    slot.lock()
        .map_err(|_| "chat launch authority is unavailable".to_string())?
        .as_ref()
        .filter(|gate| gate.request_id() == request_id)
        .cloned()
        .ok_or_else(|| "request-bound chat launch authority is missing".to_string())
}

fn discard_chat_launch_gate(
    slot: &std::sync::Mutex<Option<ChatLaunchGate>>,
    request_id: ChatStreamRequestId,
) {
    if let Ok(mut current) = slot.lock()
        && current
            .as_ref()
            .is_some_and(|gate| gate.request_id() == request_id)
    {
        current.take();
    }
}

fn kill_owned_chat_child(
    slot: &std::sync::Mutex<Option<OwnedChatChild>>,
    request_id: ChatStreamRequestId,
) -> std::result::Result<bool, String> {
    let mut current = slot.lock().unwrap_or_else(|poisoned| {
        tracing::warn!("recovering poisoned chat supervision state for Stop");
        poisoned.into_inner()
    });
    match current.as_mut() {
        Some(owned) if owned.request_id() == request_id => owned
            .request_tree_termination()
            .map(|()| true)
            .map_err(|error| format!("chat process tree could not be stopped: {error}")),
        Some(_) => Err("chat supervision belongs to another request".to_string()),
        None => Ok(false),
    }
}

fn wait_for_owned_chat_child_exit(
    slot: &std::sync::Mutex<Option<OwnedChatChild>>,
    request_id: ChatStreamRequestId,
) -> std::result::Result<std::process::ExitStatus, String> {
    let mut last_poll_error: Option<String> = None;
    let mut next_pending_warning = std::time::Instant::now() + std::time::Duration::from_secs(5);
    loop {
        let mut current = slot.lock().unwrap_or_else(|poisoned| {
            tracing::warn!("recovering poisoned chat supervision state while reaping");
            poisoned.into_inner()
        });
        let Some(owned) = current.as_mut() else {
            return Err("supervised chat subprocess disappeared before exit".to_string());
        };
        if owned.request_id() != request_id {
            return Err("chat supervision belongs to another request".to_string());
        }
        if let Err(error) = owned.request_tree_termination() {
            let error = format!("terminate supervised chat process tree: {error}");
            if last_poll_error.as_deref() != Some(error.as_str()) {
                tracing::warn!(
                    request_id = request_id.get(),
                    error = %error,
                    "chat process tree remains owned after a termination retry failed"
                );
                last_poll_error = Some(error);
            }
        }
        match owned.poll_reaped_and_empty() {
            Ok(Some(status)) => {
                current.take();
                if let Some(error) = last_poll_error {
                    tracing::warn!(
                        request_id = request_id.get(),
                        error = %error,
                        "chat subprocess exit became observable after a transient poll failure"
                    );
                }
                return Ok(status);
            }
            Ok(None) => {}
            Err(error) => {
                let error = format!("chat process-tree exit poll failed: {error}");
                if last_poll_error.as_deref() != Some(error.as_str()) {
                    tracing::warn!(
                        request_id = request_id.get(),
                        error = %error,
                        "chat subprocess remains supervised after exit poll failure"
                    );
                    last_poll_error = Some(error);
                }
            }
        }
        if std::time::Instant::now() >= next_pending_warning {
            tracing::warn!(
                request_id = request_id.get(),
                last_error = last_poll_error.as_deref().unwrap_or("none"),
                "chat process-tree cleanup remains pending; request, Stop retry, worker secrets, and child ownership are retained"
            );
            next_pending_warning = std::time::Instant::now() + std::time::Duration::from_secs(5);
        }
        drop(current);
        std::thread::sleep(std::time::Duration::from_millis(20));
    }
}

#[allow(clippy::too_many_arguments)]
fn shutdown_gui_chat_runtime(
    stream: &std::sync::Mutex<ChatStreamController>,
    launch_gate: &std::sync::Mutex<Option<ChatLaunchGate>>,
    child: &std::sync::Mutex<Option<OwnedChatChild>>,
    worker_barrier: &ChatWorkerBarrier,
    signal_clock: &std::sync::Mutex<Option<ChatTurnWatchdog>>,
    watchdog_retry: &std::sync::Mutex<Option<PendingChatWatchdogRetry>>,
    watchdog_input: &std::sync::Mutex<Option<RequestBoundChatRetryInput>>,
    watchdog_retry_stop: &std::sync::Mutex<Option<RequestBoundChatWatchdogRetryStop>>,
    model_overrides: &std::sync::Mutex<std::collections::HashMap<ChatStreamRequestId, String>>,
    pending_consent: &std::sync::Mutex<Option<PendingGuiChatConsent>>,
    main_consent_token: &std::sync::Mutex<Option<RequestBoundChatConsentToken>>,
    buddy_consent_token: &std::sync::Mutex<Option<RequestBoundChatConsentToken>>,
    last_operator_input: &std::sync::Mutex<String>,
    attachments: &std::sync::Mutex<Vec<PathBuf>>,
    consent_flow_active: &std::sync::atomic::AtomicBool,
    auto_nudge_budget: &std::sync::atomic::AtomicU8,
    auto_in_progress: &std::sync::atomic::AtomicBool,
) -> std::result::Result<(), String> {
    use zeroize::Zeroize as _;

    let mut errors = Vec::new();
    // This closes the pre-park race first: a dispatch callback that has not
    // registered yet is rejected, while every already registered worker must
    // acknowledge through its RAII lease before shutdown succeeds.
    worker_barrier.begin_shutdown();

    let active_request = {
        let mut controller = stream.lock().unwrap_or_else(|poisoned| {
            tracing::warn!("recovering poisoned chat controller during GUI shutdown");
            poisoned.into_inner()
        });
        let active = controller.active_request();
        if let Some(request) = active {
            controller.request_cancel(request.request_id);
        }
        active
    };

    if let Some(request) = active_request {
        let gate = launch_gate.lock().unwrap_or_else(|poisoned| {
            tracing::warn!("recovering poisoned chat launch gate during GUI shutdown");
            poisoned.into_inner()
        });
        if let Some(gate) = gate
            .as_ref()
            .filter(|gate| gate.request_id() == request.request_id)
        {
            gate.cancel_before_commit();
        }
    }

    let parked_request = {
        child
            .lock()
            .unwrap_or_else(|poisoned| {
                tracing::warn!("recovering poisoned chat child slot during GUI shutdown");
                poisoned.into_inner()
            })
            .as_ref()
            .map(OwnedChatChild::request_id)
    };
    if let Some(request_id) = parked_request
        && let Err(error) = kill_owned_chat_child(child, request_id)
    {
        errors.push(error);
    }

    // Every registered worker is also its request's cleanup reaper. Do not
    // race it for the Child slot, and never cross the zeroization boundary
    // while that worker can still own request material.
    worker_barrier.wait_empty();

    // A worker acknowledgement includes child cleanup. Recheck the slot so a
    // future pre-lease regression still cannot turn GUI close into an orphan.
    let late_request = child
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .as_ref()
        .map(OwnedChatChild::request_id);
    if let Some(request_id) = late_request {
        if let Err(error) = kill_owned_chat_child(child, request_id) {
            errors.push(format!("late shutdown cleanup: {error}"));
        }
        if let Err(error) = wait_for_owned_chat_child_exit(child, request_id) {
            errors.push(format!("late shutdown cleanup: {error}"));
        }
    }

    {
        let mut controller = stream
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        if let Some(request) = controller.active_request() {
            controller.settle(request.request_id, false);
        }
    }
    launch_gate
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .take();
    lock_chat_signal_clock(signal_clock).take();
    lock_chat_watchdog_retry(watchdog_retry).take();
    lock_chat_watchdog_input(watchdog_input).take();
    lock_chat_watchdog_retry_stop(watchdog_retry_stop).take();
    main_consent_token
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .take();
    buddy_consent_token
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .take();
    if let Some(mut pending) = pending_consent
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .take()
    {
        pending.body.zeroize();
    }
    for (_, mut model) in model_overrides
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .drain()
    {
        model.zeroize();
    }
    last_operator_input
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .zeroize();
    attachments
        .lock()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .clear();
    consent_flow_active.store(false, std::sync::atomic::Ordering::Release);
    auto_nudge_budget.store(0, std::sync::atomic::Ordering::Release);
    auto_in_progress.store(false, std::sync::atomic::Ordering::Release);

    if errors.is_empty() {
        Ok(())
    } else {
        Err(errors.join("; "))
    }
}

fn bind_chat_consent_token(
    slot: &std::sync::Mutex<Option<RequestBoundChatConsentToken>>,
    request_id: ChatStreamRequestId,
    token: Option<zeroize::Zeroizing<Vec<u8>>>,
) -> std::result::Result<(), String> {
    let mut current = slot
        .lock()
        .map_err(|_| "private chat consent state is unavailable".to_string())?;
    *current = token.map(|token| (request_id, token));
    Ok(())
}

fn take_chat_consent_token(
    slot: &std::sync::Mutex<Option<RequestBoundChatConsentToken>>,
    request_id: ChatStreamRequestId,
) -> std::result::Result<Option<zeroize::Zeroizing<Vec<u8>>>, String> {
    let mut current = slot
        .lock()
        .map_err(|_| "private chat consent state is unavailable".to_string())?;
    match current.take() {
        Some((bound_request_id, token)) if bound_request_id == request_id => Ok(Some(token)),
        Some(stale) => {
            *current = Some(stale);
            Err("private chat consent token belongs to another request".to_string())
        }
        None => Ok(None),
    }
}

fn discard_chat_consent_token(
    slot: &std::sync::Mutex<Option<RequestBoundChatConsentToken>>,
    request_id: ChatStreamRequestId,
) {
    if let Ok(mut current) = slot.lock()
        && current
            .as_ref()
            .is_some_and(|(bound_request_id, _)| *bound_request_id == request_id)
    {
        current.take();
    }
}

#[derive(Serialize)]
struct GuiChatLaunchEnvelope<'a> {
    version: u8,
    launch: &'static str,
    stream_control_token: &'a str,
    consent_token: Option<&'a str>,
}

fn encode_gui_chat_launch_envelope(
    stream_control_token: &str,
    consent_token: Option<&zeroize::Zeroizing<Vec<u8>>>,
) -> std::result::Result<zeroize::Zeroizing<Vec<u8>>, String> {
    let consent_token = consent_token
        .map(|token| {
            std::str::from_utf8(token.as_slice())
                .map_err(|_| "private chat consent token is not UTF-8".to_string())
        })
        .transpose()?;
    serde_json::to_vec(&GuiChatLaunchEnvelope {
        version: 1,
        launch: "commit",
        stream_control_token,
        consent_token,
    })
    .map(zeroize::Zeroizing::new)
    .map_err(|error| format!("private chat launch envelope could not be encoded: {error}"))
}

fn new_stream_control_token() -> std::result::Result<zeroize::Zeroizing<String>, String> {
    let mut control_nonce = zeroize::Zeroizing::new([0_u8; 16]);
    getrandom::getrandom(&mut control_nonce[..])
        .map_err(|error| format!("OS RNG unavailable for stream control token: {error}"))?;
    Ok(zeroize::Zeroizing::new(hex::encode(control_nonce.as_ref())))
}

const CHAT_STREAM_PROTOCOL_VERSION: u64 = 3;
/// Any record inside this namespace is reserved for GUI control traffic. A
/// future/unsupported version must fail closed rather than becoming assistant
/// text or disappearing after a provider boundary.
const CHAT_STREAM_CONTROL_NAMESPACE: &str = "\u{1e}NEOTH/";
/// GUI-private stream controls are records, not provider text.  The leading
/// ASCII RS plus this printable, versioned discriminator means a provider's
/// ordinary JSON (including a partial JSON object without a newline) is
/// rendered immediately instead of being mistaken for an incomplete control.
const CHAT_STREAM_CONTROL_PREFIX: &str = "\u{1e}NEOTH/1 ";

fn chat_stream_request_id(control_token: &str) -> String {
    use sha2::{Digest as _, Sha256};

    let mut digest = Sha256::new();
    digest.update(b"neoth-chat-stream-request-v3\0");
    digest.update(control_token.as_bytes());
    hex::encode(digest.finalize())
}

fn chat_stream_content_hash(text: &str) -> String {
    use sha2::{Digest as _, Sha256};

    hex::encode(Sha256::digest(text.as_bytes()))
}

fn chat_stream_finalization_receipt(
    request_id: &str,
    chunk_count: u64,
    content_hash: &str,
) -> String {
    use sha2::{Digest as _, Sha256};

    let mut digest = Sha256::new();
    digest.update(b"neoth-chat-stream-finalization-v3\0");
    digest.update(request_id.as_bytes());
    digest.update(b"\0");
    digest.update(chunk_count.to_le_bytes());
    digest.update(b"\0");
    digest.update(content_hash.as_bytes());
    hex::encode(digest.finalize())
}

fn format_skill_route_status(report: &neothd::skills::resolver::SkillRouteReport) -> String {
    use neothd::skills::resolver::{SkillRouteOutcome, SkillRouteRejectionCode, SkillRouteStage};

    let candidate_label = |candidate: &neothd::skills::resolver::SkillRouteCandidateReport| {
        candidate.mode_id.as_ref().map_or_else(
            || candidate.skill_id.clone(),
            |mode| format!("{}/{mode}", candidate.skill_id),
        )
    };
    let degradation = report
        .degraded_reason
        .as_deref()
        .map(|reason| format!(" · degraded: {reason}"))
        .unwrap_or_default();
    match report.outcome {
        SkillRouteOutcome::Match => {
            let selected = report
                .candidates
                .first()
                .map(candidate_label)
                .unwrap_or_else(|| "unknown".to_string());
            let stage = match report.stage {
                Some(SkillRouteStage::Explicit) => "explicit",
                Some(SkillRouteStage::ParentLiteral) => "trigger",
                Some(SkillRouteStage::Mode) => "mode",
                Some(SkillRouteStage::Embedding) => "semantic",
                None => "matched",
            };
            format!("Skill: {selected} · {stage}{degradation}")
        }
        SkillRouteOutcome::NoMatch => format!("Skill: Automatic · no match{degradation}"),
        SkillRouteOutcome::Conflict => {
            let candidates = report
                .candidates
                .iter()
                .map(candidate_label)
                .collect::<Vec<_>>()
                .join(", ");
            format!("Skill conflict: {candidates}{degradation}")
        }
        SkillRouteOutcome::Rejected => {
            let reason = match report.rejection {
                Some(SkillRouteRejectionCode::EmptyExplicitSkill) => "empty selection",
                Some(SkillRouteRejectionCode::ExplicitSkillUnavailable) => "unavailable",
                Some(SkillRouteRejectionCode::ExplicitSkillDisabled) => "disabled",
                Some(SkillRouteRejectionCode::ExplicitSkillOutsidePathScope) => {
                    "outside path scope"
                }
                None => "rejected",
            };
            format!("Skill rejected: {reason}{degradation}")
        }
    }
}

fn terminal_skill_route_status(
    current_status: &str,
    phase: ChatStreamPhase,
) -> Option<&'static str> {
    if current_status != "Resolving Skill…" {
        return None;
    }
    match phase {
        ChatStreamPhase::Cancelled => Some("Skill: unresolved · request cancelled before report"),
        ChatStreamPhase::Failed => Some("Skill: unavailable · no authenticated route report"),
        _ => None,
    }
}

/// Chat-feel parity #3 (beat-openhuman): split the raw stdout of
/// `neoth chat --stream` into `(reply_text, done)`. The CLI streams raw reply
/// deltas, emits an authenticated RS-prefixed `provider_done` boundary before
/// post-reply pipelines, and emits an authenticated final `done` record only
/// after those pipelines succeed. The explicit record wire prevents ordinary
/// provider JSON from being withheld as a possible control frame. A consumer
/// can therefore distinguish Receiving, Finalizing, clean completion and a
/// truncated/failed pipeline. Pure fn — unit-testable; called per stdout chunk
/// and once at EOF.
pub fn strip_stream_sentinel(raw: &str) -> (String, bool) {
    let (text, done, _) = parse_stream_sentinel(raw);
    (text, done)
}

/// GOLD-ADAPT-ODY-02/05 — token/timing stats the extended done-sentinel
/// carries. All-zero when the daemon predates the extension (recall
/// early-return still emits the minimal `{"neoth_stream":"done","count":1}`).
#[derive(Debug, Default, Clone, PartialEq, Eq)]
pub struct StreamStats {
    pub used_tokens: u64,
    pub limit_tokens: u64,
    pub input_tokens: u64,
    pub output_tokens: u64,
    pub elapsed_ms: u64,
    pub model: String,
}

#[derive(Debug, Default, Clone, PartialEq)]
struct ParsedChatStream {
    text: String,
    route_report: Option<neothd::skills::resolver::SkillRouteReport>,
    notices: Vec<StreamNotice>,
    completed_control_ranges: Vec<std::ops::Range<usize>>,
    provider_done: bool,
    done: bool,
    protocol_valid: bool,
    stats: StreamStats,
}

enum ParsedSkillRouteFrame {
    NotRoute,
    Valid(neothd::skills::resolver::SkillRouteReport),
    InvalidControl,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct StreamNotice {
    id: String,
    kind: String,
    text: String,
    durable: bool,
    timestamp: Option<String>,
}

enum StreamNoticeFrame {
    NotNotice,
    Valid(StreamNotice),
    InvalidAuthenticated,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ProviderDeltaFrame {
    sequence: u64,
    text: String,
}

enum ParsedProviderDeltaFrame {
    NotDelta,
    Valid(ProviderDeltaFrame),
    InvalidAuthenticated,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ProviderDoneFrame {
    protocol_version: u64,
    request_id: String,
    count: u64,
    content_hash: String,
}

enum ParsedProviderDoneFrame {
    NotDone,
    Valid(ProviderDoneFrame),
    InvalidAuthenticated,
}

/// Split the accumulated stream buffer into (reply-text, done, stats).
/// Mid-stream (no sentinel yet): done=false, zero stats.
pub fn parse_stream_sentinel(raw: &str) -> (String, bool, StreamStats) {
    parse_stream_sentinel_with_expected_token(raw, None)
}

#[cfg(test)]
fn parse_stream_sentinel_with_token(
    raw: &str,
    expected_control_token: &str,
) -> (String, bool, StreamStats) {
    parse_stream_sentinel_with_expected_token(raw, Some(expected_control_token))
}

fn parse_stream_sentinel_with_expected_token(
    raw: &str,
    expected_control_token: Option<&str>,
) -> (String, bool, StreamStats) {
    let parsed = parse_chat_stream_protocol(raw, expected_control_token);
    (
        parsed.text,
        parsed.done && parsed.protocol_valid,
        parsed.stats,
    )
}

fn parse_chat_stream_protocol(raw: &str, expected_control_token: Option<&str>) -> ParsedChatStream {
    parse_chat_stream_protocol_with_mode(raw, expected_control_token, true, false)
}

#[cfg(test)]
fn parse_chat_stream_protocol_incremental(
    raw: &str,
    expected_control_token: Option<&str>,
) -> ParsedChatStream {
    parse_chat_stream_protocol_with_mode(raw, expected_control_token, false, false)
}

fn parse_chat_stream_protocol_incremental_with_route_state(
    raw: &str,
    expected_control_token: Option<&str>,
    route_report_delivered: bool,
) -> ParsedChatStream {
    parse_chat_stream_protocol_with_mode(raw, expected_control_token, false, route_report_delivered)
}

fn parse_chat_stream_protocol_with_route_state(
    raw: &str,
    expected_control_token: Option<&str>,
    route_report_delivered: bool,
) -> ParsedChatStream {
    parse_chat_stream_protocol_with_mode(raw, expected_control_token, true, route_report_delivered)
}

#[derive(Debug, Default)]
struct IncrementalControlFrameGate {
    awaiting_line_end: bool,
}

impl IncrementalControlFrameGate {
    /// Once the versioned control prefix starts, JSON parsing waits for its
    /// terminating newline. Core serialization escapes newlines inside `text`,
    /// so a multi-megabyte notice is decoded exactly once rather than reparsing
    /// the complete accumulated prefix for every 512-byte read. Ordinary JSON
    /// is never deferred merely because it starts with `{`.
    fn can_defer_without_decoding(&self, new_bytes: &[u8]) -> bool {
        self.awaiting_line_end && !new_bytes.contains(&b'\n')
    }

    fn observe_decoded_buffer(&mut self, raw: &str) {
        let tail = raw.rsplit_once('\n').map_or(raw, |(_, tail)| tail);
        // Do not suppress an ordinary string that merely begins with a few
        // prefix bytes: keep decoding until the complete discriminator is
        // present. Once present, the rest of a large JSON frame can wait for
        // its newline without repeated full-buffer decoding.
        self.awaiting_line_end = has_stream_control_prefix(tail);
    }
}

fn compact_completed_control_frames(
    buffer: &mut Vec<u8>,
    completed_ranges: &[std::ops::Range<usize>],
) -> Result<(), &'static str> {
    if completed_ranges.is_empty() {
        return Ok(());
    }
    let removed_bytes = completed_ranges
        .iter()
        .map(|range| range.end.saturating_sub(range.start))
        .sum::<usize>();
    let mut compacted = Vec::with_capacity(buffer.len().saturating_sub(removed_bytes));
    let mut cursor = 0usize;
    for range in completed_ranges {
        if range.start < cursor || range.end > buffer.len() || range.start > range.end {
            return Err("chat stream parser produced an invalid control-frame byte range");
        }
        compacted.extend_from_slice(&buffer[cursor..range.start]);
        cursor = range.end;
    }
    compacted.extend_from_slice(&buffer[cursor..]);
    use zeroize::Zeroize as _;
    buffer.zeroize();
    *buffer = compacted;
    Ok(())
}

fn parse_chat_stream_protocol_with_mode(
    raw: &str,
    expected_control_token: Option<&str>,
    input_complete: bool,
    route_report_delivered: bool,
) -> ParsedChatStream {
    let terminal = if input_complete || raw.ends_with('\n') {
        final_stream_sentinel(raw, expected_control_token)
    } else {
        None
    };
    let (reply_end, sentinel) = terminal
        .as_ref()
        .map(|(position, sentinel)| (*position, Some(sentinel)))
        .unwrap_or((raw.len(), None));
    let g = |key: &str| {
        sentinel
            .and_then(|sentinel| sentinel.get(key))
            .and_then(|value| value.as_u64())
            .unwrap_or(0)
    };
    let stats = StreamStats {
        used_tokens: g("used_tokens"),
        limit_tokens: g("limit_tokens"),
        input_tokens: g("input_tokens"),
        output_tokens: g("output_tokens"),
        elapsed_ms: g("elapsed_ms"),
        model: sentinel
            .and_then(|sentinel| sentinel.get("model"))
            .and_then(|value| value.as_str())
            .unwrap_or("")
            .to_string(),
    };
    let mut visible = String::with_capacity(reply_end);
    let mut route_report = None;
    let mut route_report_count = u8::from(route_report_delivered);
    let mut notices = Vec::new();
    let mut completed_control_ranges = Vec::new();
    let mut notice_ids = std::collections::HashSet::new();
    let mut provider_done: Option<ProviderDoneFrame> = None;
    let mut provider_done_count = 0u8;
    let mut provider_delta_count = 0u64;
    let mut provider_delta_text = String::new();
    let mut saw_provider_activity = false;
    let mut saw_route_blocking_notice = false;
    let mut saw_untyped_reply = false;
    let mut provider_reply_open = true;
    let mut protocol_valid = true;
    let mut segment_start = 0usize;
    for segment in raw[..reply_end].split_inclusive('\n') {
        let segment_end = segment_start + segment.len();
        if !input_complete && !segment.ends_with('\n') && is_incomplete_stream_control_tail(segment)
        {
            if is_unsupported_stream_control_candidate(segment) {
                protocol_valid = false;
            }
            segment_start = segment_end;
            continue;
        }
        let line = match classify_stream_control_line(segment) {
            StreamControlLine::V1(line) => line,
            StreamControlLine::ReservedUnsupported => {
                // `RSNEOTH/` is an owned namespace. Never render or silently
                // ignore an unsupported control version, including after a
                // valid provider boundary; the request must fail closed.
                protocol_valid = false;
                segment_start = segment_end;
                continue;
            }
            StreamControlLine::Ordinary => {
                if provider_reply_open {
                    // The emitter inserts one blank line before a control record
                    // when a raw CLI delta did not end in a newline. It is a wire
                    // delimiter, not a leading provider paragraph; retaining the
                    // historical suppression also keeps compaction from leaving a
                    // phantom newline before the first typed delta.
                    let leading_control_delimiter = expected_control_token.is_some()
                        && visible.is_empty()
                        && !saw_provider_activity
                        && !saw_untyped_reply
                        && segment.trim().is_empty();
                    if !leading_control_delimiter && !segment.trim().is_empty() {
                        saw_untyped_reply = true;
                    }
                    if !leading_control_delimiter {
                        visible.push_str(segment);
                    }
                }
                segment_start = segment_end;
                continue;
            }
        };
        let line = line.trim();
        if is_authenticated_done_candidate(line, expected_control_token) {
            // The one valid terminal frame is removed from this prefix by
            // `final_stream_sentinel`. Any authenticated `done` that remains
            // here is therefore duplicated, misplaced, or shadowed by a later
            // terminal frame and invalidates the whole completion contract.
            protocol_valid = false;
            segment_start = segment_end;
            continue;
        }
        match authenticated_skill_route(line, expected_control_token) {
            ParsedSkillRouteFrame::Valid(report) => {
                route_report_count = route_report_count.saturating_add(1);
                let route_is_late = saw_provider_activity
                    || saw_route_blocking_notice
                    || provider_delta_count != 0
                    || provider_done_count != 0
                    || saw_untyped_reply
                    || !provider_reply_open;
                if route_report_count != 1 || route_is_late {
                    protocol_valid = false;
                } else {
                    route_report = Some(report);
                }
                completed_control_ranges.push(segment_start..segment_end);
            }
            ParsedSkillRouteFrame::InvalidControl => {
                protocol_valid = false;
                completed_control_ranges.push(segment_start..segment_end);
            }
            ParsedSkillRouteFrame::NotRoute => {
                match authenticated_stream_notice(line, expected_control_token) {
                    StreamNoticeFrame::Valid(notice) => {
                        let route_precedes_notice = route_report_count == 1;
                        saw_route_blocking_notice = true;
                        if !route_precedes_notice || !notice_ids.insert(notice.id.clone()) {
                            protocol_valid = false;
                        } else {
                            notices.push(notice);
                            completed_control_ranges.push(segment_start..segment_end);
                        }
                    }
                    StreamNoticeFrame::InvalidAuthenticated => {
                        protocol_valid = false;
                    }
                    StreamNoticeFrame::NotNotice => {
                        match authenticated_provider_delta(line, expected_control_token) {
                            ParsedProviderDeltaFrame::Valid(delta) => {
                                saw_provider_activity = true;
                                if route_report_count != 1
                                    || !provider_reply_open
                                    || delta.sequence != provider_delta_count.saturating_add(1)
                                {
                                    protocol_valid = false;
                                } else {
                                    provider_delta_count = delta.sequence;
                                    provider_delta_text.push_str(&delta.text);
                                    visible.push_str(&delta.text);
                                }
                            }
                            ParsedProviderDeltaFrame::InvalidAuthenticated => {
                                protocol_valid = false;
                            }
                            ParsedProviderDeltaFrame::NotDelta => {
                                match authenticated_provider_done(line, expected_control_token) {
                                    ParsedProviderDoneFrame::Valid(boundary) => {
                                        saw_provider_activity = true;
                                        provider_done_count = provider_done_count.saturating_add(1);
                                        if provider_done.replace(boundary).is_some() {
                                            protocol_valid = false;
                                        }
                                        provider_reply_open = false;
                                    }
                                    ParsedProviderDoneFrame::InvalidAuthenticated => {
                                        protocol_valid = false;
                                    }
                                    // A complete RS-prefixed line that is not
                                    // one of the authenticated frame types is
                                    // a malformed/unknown control record. Do
                                    // not let it enter the assistant reply.
                                    ParsedProviderDoneFrame::NotDone => {
                                        protocol_valid = false;
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
        segment_start = segment_end;
    }
    if let Some(boundary) = provider_done.as_ref() {
        if boundary.protocol_version == CHAT_STREAM_PROTOCOL_VERSION {
            protocol_valid &= route_report_count == 1
                && !saw_untyped_reply
                && provider_delta_count == boundary.count
                && chat_stream_content_hash(&provider_delta_text) == boundary.content_hash;
        } else {
            // Version 1 is retained only for local preflight/recall actions,
            // which do not own the stdout body and therefore cannot provide
            // typed provider deltas or a content hash.
            protocol_valid &= boundary.protocol_version == 1
                && sentinel
                    .and_then(|frame| frame.get("model"))
                    .and_then(|value| value.as_str())
                    == Some("local");
        }
    }
    if let (Some(boundary), Some(done)) = (provider_done.as_ref(), sentinel) {
        protocol_valid &=
            terminal_matches_provider_boundary(done, expected_control_token, boundary);
    }
    ParsedChatStream {
        text: visible.trim_end().to_string(),
        route_report,
        notices,
        completed_control_ranges,
        provider_done: provider_done_count == 1,
        done: terminal.is_some(),
        protocol_valid: protocol_valid
            && provider_done_count <= 1
            && (terminal.is_none() || expected_control_token.is_none() || provider_done_count == 1),
        stats,
    }
}

fn is_incomplete_stream_control_tail(segment: &str) -> bool {
    let candidate = segment.trim_end_matches(['\r', '\n']);
    let whitespace_stripped = candidate.trim_start();
    // Hold only a whole or byte-split reserved *wire namespace*. A short
    // partial namespace is necessarily ambiguous for a few bytes; any ordinary
    // JSON/text that diverges before `RSNEOTH/` stays visible immediately.
    (!candidate.is_empty() && CHAT_STREAM_CONTROL_NAMESPACE.starts_with(candidate))
        || has_reserved_stream_control_namespace(candidate)
        || (whitespace_stripped.len() != candidate.len()
            && !whitespace_stripped.is_empty()
            && (CHAT_STREAM_CONTROL_NAMESPACE.starts_with(whitespace_stripped)
                || has_reserved_stream_control_namespace(whitespace_stripped)))
}

fn has_reserved_stream_control_namespace(segment: &str) -> bool {
    segment.starts_with(CHAT_STREAM_CONTROL_NAMESPACE)
}

fn has_stream_control_prefix(segment: &str) -> bool {
    segment.starts_with(CHAT_STREAM_CONTROL_PREFIX)
}

fn is_unsupported_stream_control_candidate(segment: &str) -> bool {
    let candidate = segment.trim_end_matches(['\r', '\n']);
    let whitespace_stripped = candidate.trim_start();
    // Once the complete v1 discriminator is present, an incomplete JSON
    // payload necessarily extends the prefix. It must remain deferred until
    // its newline instead of being mistaken for an unsupported version.
    (has_reserved_stream_control_namespace(candidate)
        && !candidate.starts_with(CHAT_STREAM_CONTROL_PREFIX)
        && !CHAT_STREAM_CONTROL_PREFIX.starts_with(candidate))
        || (whitespace_stripped.len() != candidate.len()
            && has_reserved_stream_control_namespace(whitespace_stripped)
            && !whitespace_stripped.starts_with(CHAT_STREAM_CONTROL_PREFIX)
            && !CHAT_STREAM_CONTROL_PREFIX.starts_with(whitespace_stripped))
}

/// Classify one complete logical line without ever letting a reserved control
/// namespace fall through to provider text. Unprefixed JSON remains ordinary
/// text in GUI-owned streams; accepting it incrementally would reintroduce
/// split-frame leakage.
enum StreamControlLine<'a> {
    V1(&'a str),
    ReservedUnsupported,
    Ordinary,
}

fn classify_stream_control_line(segment: &str) -> StreamControlLine<'_> {
    let line = segment.trim_end_matches(['\r', '\n']);
    if let Some(payload) = line.strip_prefix(CHAT_STREAM_CONTROL_PREFIX) {
        StreamControlLine::V1(payload)
    } else if has_reserved_stream_control_namespace(line)
        || (line.trim_start().len() != line.len()
            && has_reserved_stream_control_namespace(line.trim_start()))
    {
        StreamControlLine::ReservedUnsupported
    } else {
        StreamControlLine::Ordinary
    }
}

fn authenticated_skill_route(
    line: &str,
    expected_control_token: Option<&str>,
) -> ParsedSkillRouteFrame {
    let frame = match serde_json::from_str::<serde_json::Value>(line) {
        Ok(frame) => frame,
        Err(_) => {
            let claims_skill_route = line.trim_start().starts_with('{')
                && line.contains("\"neoth_stream\"")
                && line.contains("\"skill_route\"");
            return if claims_skill_route {
                ParsedSkillRouteFrame::InvalidControl
            } else {
                ParsedSkillRouteFrame::NotRoute
            };
        }
    };
    if frame.get("neoth_stream").and_then(|value| value.as_str()) != Some("skill_route") {
        return ParsedSkillRouteFrame::NotRoute;
    }
    let Some(expected_control_token) = expected_control_token else {
        return ParsedSkillRouteFrame::InvalidControl;
    };
    let Some(object) = frame.as_object() else {
        return ParsedSkillRouteFrame::InvalidControl;
    };
    const FRAME_KEYS: [&str; 5] = [
        "neoth_stream",
        "protocol_version",
        "request_id",
        "control_token",
        "report",
    ];
    if object.len() != FRAME_KEYS.len() || FRAME_KEYS.iter().any(|key| !object.contains_key(*key)) {
        return ParsedSkillRouteFrame::InvalidControl;
    }
    if frame.get("control_token").and_then(|value| value.as_str()) != Some(expected_control_token)
        || frame
            .get("protocol_version")
            .and_then(|value| value.as_u64())
            != Some(CHAT_STREAM_PROTOCOL_VERSION)
        || frame.get("request_id").and_then(|value| value.as_str())
            != Some(chat_stream_request_id(expected_control_token).as_str())
    {
        return ParsedSkillRouteFrame::InvalidControl;
    }
    let Some(raw_report) = frame.get("report") else {
        return ParsedSkillRouteFrame::InvalidControl;
    };
    let Ok(report) =
        serde_json::from_value::<neothd::skills::resolver::SkillRouteReport>(raw_report.clone())
    else {
        return ParsedSkillRouteFrame::InvalidControl;
    };
    if serde_json::to_value(&report).ok().as_ref() != Some(raw_report) {
        return ParsedSkillRouteFrame::InvalidControl;
    }
    ParsedSkillRouteFrame::Valid(report)
}

fn authenticated_stream_notice(
    line: &str,
    expected_control_token: Option<&str>,
) -> StreamNoticeFrame {
    let Some(expected_control_token) = expected_control_token else {
        return StreamNoticeFrame::NotNotice;
    };
    let Ok(frame) = serde_json::from_str::<serde_json::Value>(line) else {
        return StreamNoticeFrame::NotNotice;
    };
    if frame.get("neoth_stream").and_then(|value| value.as_str()) != Some("notice") {
        return StreamNoticeFrame::NotNotice;
    }
    if frame.get("control_token").and_then(|value| value.as_str()) != Some(expected_control_token) {
        return StreamNoticeFrame::NotNotice;
    }
    let expected_request_id = chat_stream_request_id(expected_control_token);
    if frame
        .get("protocol_version")
        .and_then(|value| value.as_u64())
        != Some(CHAT_STREAM_PROTOCOL_VERSION)
        || frame.get("request_id").and_then(|value| value.as_str())
            != Some(expected_request_id.as_str())
    {
        return StreamNoticeFrame::InvalidAuthenticated;
    }
    let Some(kind) = frame.get("kind").and_then(|value| value.as_str()) else {
        return StreamNoticeFrame::InvalidAuthenticated;
    };
    let Some(id) = frame.get("id").and_then(|value| value.as_str()) else {
        return StreamNoticeFrame::InvalidAuthenticated;
    };
    let Some(text) = frame.get("text").and_then(|value| value.as_str()) else {
        return StreamNoticeFrame::InvalidAuthenticated;
    };
    let Some(durable) = frame.get("durable").and_then(|value| value.as_bool()) else {
        return StreamNoticeFrame::InvalidAuthenticated;
    };
    let id_is_lower_hex = !id.is_empty()
        && id.len() <= 64
        && id
            .bytes()
            .all(|byte| byte.is_ascii_hexdigit() && !byte.is_ascii_uppercase());
    let valid_kind_contract = match kind {
        "background_result" => id.len() == 16 && id_is_lower_hex,
        "review_result" | "operator_notice" | "finalization_error" => id_is_lower_hex && !durable,
        _ => false,
    };
    if !valid_kind_contract {
        return StreamNoticeFrame::InvalidAuthenticated;
    }
    StreamNoticeFrame::Valid(StreamNotice {
        id: id.to_string(),
        kind: kind.to_string(),
        text: neothd::security::redact::sanitize_tool_output(text),
        durable,
        timestamp: None,
    })
}

fn authenticated_provider_delta(
    line: &str,
    expected_control_token: Option<&str>,
) -> ParsedProviderDeltaFrame {
    let Some(expected_control_token) = expected_control_token else {
        return ParsedProviderDeltaFrame::NotDelta;
    };
    let Ok(frame) = serde_json::from_str::<serde_json::Value>(line) else {
        return ParsedProviderDeltaFrame::NotDelta;
    };
    if frame.get("neoth_stream").and_then(|value| value.as_str()) != Some("provider_delta") {
        return ParsedProviderDeltaFrame::NotDelta;
    }
    if frame.get("control_token").and_then(|value| value.as_str()) != Some(expected_control_token) {
        return ParsedProviderDeltaFrame::NotDelta;
    }
    let Some(sequence) = frame.get("sequence").and_then(|value| value.as_u64()) else {
        return ParsedProviderDeltaFrame::InvalidAuthenticated;
    };
    let Some(text) = frame.get("text").and_then(|value| value.as_str()) else {
        return ParsedProviderDeltaFrame::InvalidAuthenticated;
    };
    let expected_request_id = chat_stream_request_id(expected_control_token);
    if frame
        .get("protocol_version")
        .and_then(|value| value.as_u64())
        != Some(CHAT_STREAM_PROTOCOL_VERSION)
        || frame.get("request_id").and_then(|value| value.as_str())
            != Some(expected_request_id.as_str())
        || sequence == 0
    {
        return ParsedProviderDeltaFrame::InvalidAuthenticated;
    }
    ParsedProviderDeltaFrame::Valid(ProviderDeltaFrame {
        sequence,
        text: text.to_string(),
    })
}

fn authenticated_provider_done(
    line: &str,
    expected_control_token: Option<&str>,
) -> ParsedProviderDoneFrame {
    let Some(expected_control_token) = expected_control_token else {
        return ParsedProviderDoneFrame::NotDone;
    };
    let Ok(frame) = serde_json::from_str::<serde_json::Value>(line) else {
        return ParsedProviderDoneFrame::NotDone;
    };
    if frame.get("neoth_stream").and_then(|value| value.as_str()) != Some("provider_done") {
        return ParsedProviderDoneFrame::NotDone;
    }
    if frame.get("control_token").and_then(|value| value.as_str()) != Some(expected_control_token) {
        return ParsedProviderDoneFrame::NotDone;
    }
    let protocol_version = frame
        .get("protocol_version")
        .and_then(|value| value.as_u64())
        .unwrap_or(1);
    let request_id = frame
        .get("request_id")
        .and_then(|value| value.as_str())
        .unwrap_or("");
    let Some(count) = frame.get("count").and_then(|value| value.as_u64()) else {
        return ParsedProviderDoneFrame::InvalidAuthenticated;
    };
    let content_hash = frame
        .get("content_hash")
        .and_then(|value| value.as_str())
        .unwrap_or("");
    if protocol_version == CHAT_STREAM_PROTOCOL_VERSION {
        if request_id != chat_stream_request_id(expected_control_token)
            || content_hash.len() != 64
            || !content_hash.bytes().all(|byte| byte.is_ascii_hexdigit())
        {
            return ParsedProviderDoneFrame::InvalidAuthenticated;
        }
    } else if protocol_version != 1 {
        return ParsedProviderDoneFrame::InvalidAuthenticated;
    }
    ParsedProviderDoneFrame::Valid(ProviderDoneFrame {
        protocol_version,
        request_id: request_id.to_string(),
        count,
        content_hash: content_hash.to_string(),
    })
}

fn terminal_matches_provider_boundary(
    done: &serde_json::Value,
    expected_control_token: Option<&str>,
    boundary: &ProviderDoneFrame,
) -> bool {
    let Some(expected_control_token) = expected_control_token else {
        return true;
    };
    let done_version = done
        .get("protocol_version")
        .and_then(|value| value.as_u64())
        .unwrap_or(1);
    if done_version != boundary.protocol_version
        || done.get("count").and_then(|value| value.as_u64()) != Some(boundary.count)
    {
        return false;
    }
    if done_version == 1 {
        return done.get("model").and_then(|value| value.as_str()) == Some("local");
    }
    let expected_request_id = chat_stream_request_id(expected_control_token);
    if boundary.request_id != expected_request_id
        || done.get("request_id").and_then(|value| value.as_str())
            != Some(expected_request_id.as_str())
        || done.get("content_hash").and_then(|value| value.as_str())
            != Some(boundary.content_hash.as_str())
    {
        return false;
    }
    let expected_receipt = chat_stream_finalization_receipt(
        &expected_request_id,
        boundary.count,
        &boundary.content_hash,
    );
    done.get("finalization_receipt")
        .and_then(|value| value.as_str())
        == Some(expected_receipt.as_str())
}

/// Accept a completion marker only when it is valid JSON on the final
/// non-empty line. GUI-owned subprocesses additionally bind that marker to a
/// fresh per-turn nonce, so model-generated text cannot forge a clean EOF.
fn final_stream_sentinel(
    raw: &str,
    expected_control_token: Option<&str>,
) -> Option<(usize, serde_json::Value)> {
    let line_ending_trimmed = raw.trim_end_matches(['\r', '\n']);
    let pos = line_ending_trimmed.rfind('\n').map_or(0, |index| index + 1);
    let wire_line = &line_ending_trimmed[pos..];
    // GUI-owned subprocesses require the explicit v1 record discriminator at
    // byte zero. The no-token public helper retains its terminal-only legacy
    // whitespace normalization for ordinary CLI output, where no authenticated
    // state is incrementally consumed.
    let line = match expected_control_token {
        Some(_) => wire_line.strip_prefix(CHAT_STREAM_CONTROL_PREFIX)?,
        None => wire_line
            .trim()
            .strip_prefix(CHAT_STREAM_CONTROL_PREFIX)
            .unwrap_or_else(|| wire_line.trim()),
    };
    let sentinel: serde_json::Value = serde_json::from_str(line).ok()?;
    if sentinel
        .get("neoth_stream")
        .and_then(|value| value.as_str())
        != Some("done")
    {
        return None;
    }
    if let Some(expected) = expected_control_token
        && sentinel
            .get("control_token")
            .and_then(|value| value.as_str())
            != Some(expected)
    {
        return None;
    }
    Some((pos, sentinel))
}

fn is_authenticated_done_candidate(line: &str, expected_control_token: Option<&str>) -> bool {
    let Some(expected_control_token) = expected_control_token else {
        return false;
    };
    let Ok(frame) = serde_json::from_str::<serde_json::Value>(line) else {
        return false;
    };
    frame.get("neoth_stream").and_then(|value| value.as_str()) == Some("done")
        && frame.get("control_token").and_then(|value| value.as_str())
            == Some(expected_control_token)
}

