    #[test]
    fn background_notice_requires_token_and_unique_valid_id() {
        let route = skill_route_frame("right");
        let wrong_token = serde_json::json!({
            "neoth_stream": "notice",
            "protocol_version": CHAT_STREAM_PROTOCOL_VERSION,
            "request_id": chat_stream_request_id("wrong"),
            "control_token": "wrong",
            "kind": "background_result",
            "id": "0123456789abcdef",
            "text": "result",
            "durable": true,
        });
        let parsed = parse_chat_stream_protocol(&wrong_token.to_string(), Some("right"));
        assert!(parsed.notices.is_empty());
        assert!(parsed.protocol_valid);
        assert!(parsed.text.contains("\"neoth_stream\":\"notice\""));

        let valid = serde_json::json!({
            "neoth_stream": "notice",
            "protocol_version": CHAT_STREAM_PROTOCOL_VERSION,
            "request_id": chat_stream_request_id("right"),
            "control_token": "right",
            "kind": "background_result",
            "id": "0123456789abcdef",
            "text": "result",
            "durable": true,
        });
        let duplicate = format!(
            "{route}\n{}\n{}\nreply",
            control_frame(valid.clone()),
            control_frame(valid)
        );
        let parsed = parse_chat_stream_protocol(&duplicate, Some("right"));
        assert_eq!(parsed.text, "reply");
        assert_eq!(parsed.notices.len(), 1);
        assert!(!parsed.protocol_valid);

        let malformed = serde_json::json!({
            "neoth_stream": "notice",
            "protocol_version": CHAT_STREAM_PROTOCOL_VERSION,
            "request_id": chat_stream_request_id("right"),
            "control_token": "right",
            "kind": "background_result",
            "id": "not-a-valid-id",
            "text": "result",
            "durable": true,
        });
        let parsed = parse_chat_stream_protocol(
            &format!("{route}\n{}\nreply", control_frame(malformed)),
            Some("right"),
        );
        assert_eq!(parsed.text, "reply");
        assert!(parsed.notices.is_empty());
        assert!(!parsed.protocol_valid);

        let no_durable_receipt = serde_json::json!({
            "neoth_stream": "notice",
            "protocol_version": CHAT_STREAM_PROTOCOL_VERSION,
            "request_id": chat_stream_request_id("right"),
            "control_token": "right",
            "kind": "background_result",
            "id": "0123456789abcdef",
            "text": "result",
        });
        let parsed = parse_chat_stream_protocol(
            &format!("{route}\n{}\nreply", control_frame(no_durable_receipt)),
            Some("right"),
        );
        assert_eq!(parsed.text, "reply");
        assert!(parsed.notices.is_empty());
        assert!(!parsed.protocol_valid);

        let recoverable = serde_json::json!({
            "neoth_stream": "notice",
            "protocol_version": CHAT_STREAM_PROTOCOL_VERSION,
            "request_id": chat_stream_request_id("right"),
            "control_token": "right",
            "kind": "background_result",
            "id": "0123456789abcdef",
            "text": "result",
            "durable": false,
        });
        let parsed = parse_chat_stream_protocol(
            &format!("{route}\n{}\nreply", control_frame(recoverable)),
            Some("right"),
        );
        assert_eq!(parsed.text, "reply");
        assert!(parsed.protocol_valid);
        assert_eq!(parsed.notices.len(), 1);
        assert!(!parsed.notices[0].durable);
    }

    #[test]
    fn background_notice_materialization_is_ordered_and_idempotent() {
        let request_id = ChatStreamRequestId::parse_wire("42").unwrap();
        let mut rows = vec![
            ChatMessage {
                role: "assistant".into(),
                text: "older".into(),
                request_id: "41".into(),
                ..Default::default()
            },
            ChatMessage {
                role: "operator".into(),
                text: "question".into(),
                request_id: request_id.as_wire().into(),
                ..Default::default()
            },
            ChatMessage {
                role: "assistant".into(),
                text: "…".into(),
                request_id: request_id.as_wire().into(),
                ..Default::default()
            },
        ];
        let notices = vec![StreamNotice {
            id: "0123456789abcdef".to_string(),
            kind: "background_result".to_string(),
            text: "finished".to_string(),
            durable: true,
            timestamp: None,
        }];

        assert_eq!(insert_stream_notices(&mut rows, request_id, &notices), 1);
        assert_eq!(rows[1].role.as_str(), "assistant");
        assert_eq!(rows[1].text.as_str(), "[btw] finished");
        assert_eq!(
            rows[1].request_id.as_str(),
            "notice:background_result:0123456789abcdef"
        );
        assert_eq!(rows[2].request_id.as_str(), "42");
        assert_eq!(insert_stream_notices(&mut rows, request_id, &notices), 0);
        assert_eq!(rows.len(), 4);
    }

    #[test]
    fn review_and_finalization_events_materialize_after_the_same_turn() {
        let request_id = ChatStreamRequestId::parse_wire("42").unwrap();
        let mut rows = vec![
            ChatMessage {
                role: "operator".into(),
                text: "question".into(),
                request_id: request_id.as_wire().into(),
                ..Default::default()
            },
            ChatMessage {
                role: "assistant".into(),
                text: "reply".into(),
                request_id: request_id.as_wire().into(),
                ..Default::default()
            },
        ];
        let notices = vec![
            StreamNotice {
                id: "0123456789abcdef".to_string(),
                kind: "review_result".to_string(),
                text: "quality: PASS".to_string(),
                durable: false,
                timestamp: None,
            },
            StreamNotice {
                id: "fedcba9876543210".to_string(),
                kind: "finalization_error".to_string(),
                text: "WAL drain failed".to_string(),
                durable: false,
                timestamp: None,
            },
        ];

        assert_eq!(insert_stream_notices(&mut rows, request_id, &notices), 2);
        assert_eq!(rows[2].role.as_str(), "assistant");
        assert_eq!(rows[2].text.as_str(), "[review]\nquality: PASS");
        assert_eq!(rows[3].role.as_str(), "error");
        assert_eq!(
            rows[3].text.as_str(),
            "Finalization failed: WAL drain failed"
        );
        assert_eq!(insert_stream_notices(&mut rows, request_id, &notices), 0);
    }

    #[test]
    fn lf_p2_26a_post_provider_gate_round_trips_through_main_and_buddy_consumers() {
        use neothd::cli::chat::{
            emit_deferred_post_provider_stream_to, emit_deferred_stream_done_to,
            emit_stream_finalization_error_to,
        };
        use neothd::hooks::dispatcher::StageOutcome;
        use neothd::hooks::schema::{HookAction, HookDef, HookMatcher};
        use neothd::hooks::{HookStage, run_stage};

        const TOKEN: &str = "lf-p2-26a-gui-token";
        const SECRET: &str = "sk-lf-p2-26a-gui-never-visible";
        let provider_chunks = ["first chunk ", SECRET, " third chunk"];
        let provider_body = provider_chunks.concat();
        let make_hook = |action| HookDef {
            name: "lf-p2-26a-gui-post-provider".to_owned(),
            stage: HookStage::PostProviderCall,
            enabled: Some(true),
            priority: None,
            matcher: Some(HookMatcher {
                pattern: SECRET.to_owned(),
            }),
            action,
            status_message: None,
            once: false,
            fail_fast: false,
        };

        let blocked = run_stage(
            HookStage::PostProviderCall,
            &provider_body,
            &[make_hook(HookAction::Block {
                reason: "synthetic secret must remain private".to_owned(),
            })],
        )
        .expect("real post-provider dispatcher blocks the fixture");
        assert!(matches!(blocked, StageOutcome::Block { .. }));

        let accepted = run_stage(
            HookStage::PostProviderCall,
            &provider_body,
            &[make_hook(HookAction::Replace {
                template: "[REDACTED]".to_owned(),
            })],
        )
        .expect("real post-provider dispatcher replaces the fixture");
        let accepted_body = match accepted {
            StageOutcome::Continue { body, .. } => body,
            StageOutcome::Block { .. } => panic!("replace hook must continue"),
        };
        assert!(!accepted_body.contains(SECRET));

        let mut identity = neothd::providers::CompletionIdentity::default();
        identity.provider = "lf-p2-gui-fixture".to_owned();
        identity.wire_model = "lf-p2-gui-model".to_owned();
        let completion = neothd::providers::Completion {
            identity,
            model: "lf-p2-gui-model".to_owned(),
            input_tokens: Some(13),
            output_tokens: Some(8),
            latency: std::time::Duration::from_millis(17),
            ..Default::default()
        };
        let mut producer = Vec::new();
        let pending = emit_deferred_post_provider_stream_to(
            &mut producer,
            Some(TOKEN),
            256,
            &completion,
            &accepted_body,
        )
        .expect("real producer emits only the accepted body and boundary");
        emit_deferred_stream_done_to(&mut producer, Some(TOKEN), &pending.done_line)
            .expect("real producer commits success after finalization");
        let wire = format!(
            "{}\n{}",
            skill_route_frame(TOKEN),
            String::from_utf8(producer).expect("producer emits UTF-8 protocol bytes")
        );
        assert!(!wire.contains(SECRET));

        // Main and Buddy have different UI workers, but both hand their owned
        // child stdout to this exact authenticated parser.  Parse independently
        // to prove each consumer receives one replacement-only completion with
        // matching provider boundary, hash/count, request id, receipt, and
        // terminal success ordering.
        for consumer in ["Main", "Buddy"] {
            let parsed = parse_chat_stream_protocol(&wire, Some(TOKEN));
            assert!(parsed.provider_done, "{consumer} must see the boundary");
            assert!(parsed.done, "{consumer} must see terminal success");
            assert!(parsed.protocol_valid, "{consumer} must verify the receipt");
            assert_eq!(parsed.text, accepted_body, "{consumer} visible body");
            assert_eq!(parsed.stats.used_tokens, 21, "{consumer} token count");
            assert_eq!(parsed.stats.input_tokens, 13, "{consumer} input count");
            assert_eq!(parsed.stats.output_tokens, 8, "{consumer} output count");
            assert_eq!(parsed.stats.limit_tokens, 256, "{consumer} token limit");
            assert_eq!(parsed.stats.model, "lf-p2-gui-model", "{consumer} model");
        }

        let mut failed_producer = Vec::new();
        let _pending = emit_deferred_post_provider_stream_to(
            &mut failed_producer,
            Some(TOKEN),
            256,
            &completion,
            &accepted_body,
        )
        .expect("provider boundary is emitted before a later finalization failure");
        emit_stream_finalization_error_to(
            &mut failed_producer,
            TOKEN,
            "synthetic finalizer failed after provider boundary",
        )
        .expect("real producer surfaces an authenticated finalization failure");
        let failed_wire = format!(
            "{}\n{}",
            skill_route_frame(TOKEN),
            String::from_utf8(failed_producer).expect("producer emits UTF-8 protocol bytes")
        );
        for consumer in ["Main", "Buddy"] {
            let parsed = parse_chat_stream_protocol(&failed_wire, Some(TOKEN));
            assert!(
                parsed.provider_done,
                "{consumer} still sees provider boundary"
            );
            assert!(!parsed.done, "{consumer} must not receive false success");
            assert!(
                !(parsed.done && parsed.protocol_valid),
                "{consumer} must never classify finalization failure as success"
            );
            assert_eq!(
                parsed.text, accepted_body,
                "{consumer} retains accepted body"
            );
            assert_eq!(parsed.notices.len(), 1, "{consumer} sees the error notice");
            assert_eq!(parsed.notices[0].kind, "finalization_error");
            assert!(
                parsed.notices[0]
                    .text
                    .contains("synthetic finalizer failed")
            );
        }
    }

    #[test]
    fn gui_chat_skill_args_precede_flag_terminator_with_automatic_omitting_flag() {
        let mut explicit = std::process::Command::new("neoth");
        explicit.arg("chat").arg("--stream");
        append_chat_prompt_args(
            &mut explicit,
            Some("systematic_debugging"),
            "--operator-text",
        );
        let explicit_args = explicit
            .get_args()
            .map(|arg| arg.to_string_lossy().into_owned())
            .collect::<Vec<_>>();
        assert_eq!(
            explicit_args,
            vec![
                "chat",
                "--stream",
                "--skill",
                "systematic_debugging",
                "--",
                "--operator-text",
            ]
        );

        let mut automatic = std::process::Command::new("neoth");
        automatic.arg("chat").arg("--stream");
        append_chat_prompt_args(&mut automatic, None, "prompt");
        let automatic_args = automatic
            .get_args()
            .map(|arg| arg.to_string_lossy().into_owned())
            .collect::<Vec<_>>();
        assert_eq!(automatic_args, vec!["chat", "--stream", "--", "prompt"]);

        let source = include_str!("main.rs");
        let compact = source.split_whitespace().collect::<String>();
        let production = source.split("mod chat_subprocess_tests").next().unwrap();
        assert_eq!(
            production.matches("append_chat_prompt_args(").count(),
            3,
            "one shared helper plus Main and Buddy call sites must stay in parity"
        );
        assert_eq!(
            source
                .matches("cmd.arg(\"--gui-launch-envelope-stdin\")")
                .count(),
            2,
            "main chat and Buddy must both use the private launch envelope"
        );
        assert!(!source.contains(concat!("NEOTH_STREAM_", "CONTROL_TOKEN")));
        assert!(compact.contains(".arg(\"loop\").arg(\"run\").arg(\"--\").arg(&prompt)"));
    }

    #[test]
    fn main_and_buddy_incognito_launches_are_request_bound_and_truthful() {
        let command_args = |incognito| {
            let mut command = std::process::Command::new("neoth");
            configure_gui_chat_launch_args(&mut command, incognito);
            command
                .get_args()
                .map(|arg| arg.to_string_lossy().into_owned())
                .collect::<Vec<_>>()
        };
        assert_eq!(
            command_args(false),
            vec!["chat", "--stream", "--gui-launch-envelope-stdin"],
            "a normal per-turn selection must not silently enable Incognito"
        );
        assert_eq!(
            command_args(true),
            vec![
                "chat",
                "--stream",
                "--incognito",
                "--gui-launch-envelope-stdin",
            ],
            "the captured Incognito selection must reach the CLI before the private envelope"
        );

        let source = include_str!("main.rs");
        let production = source.split("mod chat_subprocess_tests").next().unwrap();
        assert_eq!(
            production
                .matches("configure_gui_chat_launch_args(&mut cmd, incognito);")
                .count(),
            2,
            "Main and Buddy must share the exact request-bound Incognito launch path"
        );
        assert!(production.contains("window.on_chat_send_clicked(move |text, incognito|"));
        assert!(production.contains("overlay.on_send_clicked(move |text, incognito|"));
        assert!(production.contains("incognito: bool,"));
        assert!(production.contains("PendingChatWatchdogRetry"));
        assert!(production.contains("retry.incognito"));
        assert!(production.contains("w.invoke_chat_send_clicked(\"continue\".into(), incognito)"));
        assert!(production.contains("succeeded && !incognito"));
        assert!(production.contains("ChatStreamPhase::Complete && !incognito"));
        assert!(production.contains("w.set_chat_incognito(false);"));
        assert!(production.contains("w.set_chat_incognito_active(incognito);"));
        assert!(production.contains("ov.set_incognito(false);"));
        assert!(production.contains("activate_buddy_chat_request_ui(&win, &ov, incognito);"));
        assert!(production.contains("overlay.on_incognito_selection_changed"));
        assert!(production.contains("settle_main_chat_request_ui(&w);"));
        assert!(production.contains("settle_buddy_chat_request_ui(&win, &ov);"));
        let launch_gate_failures = production
            .match_indices("install_chat_launch_gate(launch_gate_slot.as_ref()")
            .map(|(offset, _)| &production[offset..])
            .collect::<Vec<_>>();
        assert!(
            launch_gate_failures[0]
                .split("if let Some(model)")
                .next()
                .unwrap()
                .contains("settle_main_chat_request_ui(&w);")
        );
        assert!(
            launch_gate_failures[1]
                .split("win.set_chat_send_in_flight(true)")
                .next()
                .unwrap()
                .contains("settle_buddy_chat_request_ui(&win, &ov);")
        );
        let model_lock_failure = production
            .split("Model selection state failed; message was not sent.")
            .next()
            .unwrap();
        assert!(
            model_lock_failure
                .rsplit("if let Some(model) = selected_model")
                .next()
                .unwrap()
                .contains("settle_main_chat_request_ui(&w);")
        );
        assert!(production.contains("w.invoke_chat_send_clicked(text, m.incognito);"));
        assert!(production.contains("if !incognito {\n            if let Ok(mut last)"));
        assert!(production.contains("let request_incognito = rows"));
        assert!(production.contains("incognito: request_incognito,"));

        let chat_ui = include_str!("../ui/chat.slint");
        let overlay_ui = include_str!("../ui/overlay.slint");
        let main_ui = include_str!("../ui/main.slint");
        for ui in [chat_ui, overlay_ui] {
            assert!(ui.contains("Incognito"));
            assert!(ui.contains("Next turn selected"));
            assert!(ui.contains("Next turn unselected"));
            assert!(ui.contains("Incognito active"));
            assert!(ui.contains("Standard active"));
            assert!(ui.contains("wrap: word-wrap"));
            assert!(ui.contains("checked <=> root.incognito;"));
        }
        assert!(chat_ui.contains("if root.message.incognito: Text"));
        assert!(chat_ui.contains("Incognito request: no profile, recall, or transcript access"));
        assert!(main_ui.contains("in-out property <bool> chat-incognito: false;"));
        assert!(main_ui.contains("in property <bool> chat-incognito-active: false;"));
        assert!(main_ui.contains("incognito <=> root.chat-incognito;"));
        assert!(overlay_ui.contains("if root.compact && !root.send-in-flight: NeothCheckBox"));
        assert!(overlay_ui.contains(concat!(
            "Incognito selected for the next Buddy turn: ",
            "no profile, recall, or transcript data will be used"
        )));
        assert!(overlay_ui.contains("if root.compact && root.send-in-flight: NeothCheckBox"));
        assert!(overlay_ui.contains("checked: root.incognito-active;"));
        assert!(overlay_ui.contains("enabled: false;"));
        assert!(overlay_ui.contains("callback incognito-selection-changed(bool);"));
        assert!(
            chat_ui.contains("!(root.incognito || (root.send-in-flight && root.incognito-active))")
        );
        assert!(
            production.contains("Incognito selected — checking exact provider consent routes…")
        );
        assert!(production.contains("Incognito selected — checking provider consent…"));
    }

    #[test]
    fn selecting_incognito_detaches_arrow_up_recall_from_a_standard_turn() {
        let recalled = std::sync::Mutex::new("previous standard prompt".to_string());
        assert_eq!(
            eligible_operator_recall(&recalled, false, false).as_deref(),
            Some("previous standard prompt")
        );

        detach_operator_recall_for_incognito(&recalled, true);
        assert!(eligible_operator_recall(&recalled, true, false).is_none());
        assert!(eligible_operator_recall(&recalled, false, true).is_none());
        assert!(eligible_operator_recall(&recalled, false, false).is_none());
    }

    #[test]
    fn prelaunch_failure_settlement_clears_active_privacy_on_main_and_buddy() {
        let window = MainWindow::new().unwrap();
        let overlay = MiniOverlay::new().unwrap();

        window.set_chat_send_in_flight(true);
        window.set_chat_incognito_active(true);
        settle_main_chat_request_ui(&window);
        assert!(!window.get_chat_send_in_flight());
        assert!(!window.get_chat_incognito_active());

        window.set_chat_send_in_flight(true);
        window.set_chat_incognito_active(true);
        overlay.set_send_in_flight(true);
        overlay.set_incognito_active(true);
        settle_buddy_chat_request_ui(&window, &overlay);
        assert!(!window.get_chat_send_in_flight());
        assert!(!window.get_chat_incognito_active());
        assert!(!overlay.get_send_in_flight());
        assert!(!overlay.get_incognito_active());
    }

    #[test]
    fn buddy_incognito_activation_is_visible_to_main_and_blocks_recall() {
        let window = MainWindow::new().unwrap();
        let overlay = MiniOverlay::new().unwrap();
        let recalled = std::sync::Mutex::new("previous standard prompt".to_string());

        detach_operator_recall_for_incognito(&recalled, true);
        activate_buddy_chat_request_ui(&window, &overlay, true);
        window.set_chat_send_in_flight(true);

        assert!(window.get_chat_incognito_active());
        assert!(window.get_chat_send_in_flight());
        assert!(overlay.get_incognito_active());
        assert!(eligible_operator_recall(&recalled, false, true).is_none());
        settle_buddy_chat_request_ui(&window, &overlay);
    }

    #[test]
    fn incognito_rows_never_replace_or_create_local_sidebar_preview() {
        use slint::{Model, ModelRc, VecModel};

        let window = MainWindow::new().unwrap();
        window.set_chat_channels(ModelRc::new(VecModel::from(build_chat_sidebar_channels(
            &[],
        ))));
        let standard_id = ChatStreamRequestId::parse_wire("41").unwrap();
        assert!(begin_live_chat_request(
            &window,
            standard_id,
            "standard prompt",
            false,
        ));
        assert!(settle_live_chat_request(
            &window,
            standard_id,
            ChatStreamPhase::Complete,
            Some("standard reply"),
        ));
        let baseline = current_live_chat_preview(&window);
        assert!(!baseline.0.is_empty());

        let private_id = ChatStreamRequestId::parse_wire("42").unwrap();
        assert!(begin_live_chat_request(
            &window,
            private_id,
            "PRIVATE_PROMPT_SENTINEL",
            true,
        ));
        assert_eq!(current_live_chat_preview(&window), baseline);
        assert!(project_chat_stream_update(
            &window,
            private_id,
            ChatStreamPhase::Receiving,
            Some("PRIVATE_STREAM_REPLY_SENTINEL"),
        ));
        assert_eq!(current_live_chat_preview(&window), baseline);
        assert!(settle_live_chat_request(
            &window,
            private_id,
            ChatStreamPhase::Complete,
            Some("PRIVATE_REPLY_SENTINEL"),
        ));
        assert_eq!(current_live_chat_preview(&window), baseline);
        let local = window
            .get_chat_channels()
            .iter()
            .find(|row| row.id == "cli")
            .unwrap();
        assert_eq!(local.last_message.as_str(), baseline.0.as_str());
        assert_eq!(local.last_timestamp.as_str(), baseline.1.as_str());
        assert!(!local.last_message.contains("PRIVATE"));

        let private_only = MainWindow::new().unwrap();
        private_only.set_chat_channels(ModelRc::new(VecModel::from(build_chat_sidebar_channels(
            &[],
        ))));
        assert!(begin_live_chat_request(
            &private_only,
            private_id,
            "PRIVATE_ONLY_PROMPT",
            true,
        ));
        assert_eq!(
            current_live_chat_preview(&private_only),
            (String::new(), String::new())
        );
        assert!(settle_live_chat_request(
            &private_only,
            private_id,
            ChatStreamPhase::Complete,
            Some("PRIVATE_ONLY_REPLY"),
        ));
        assert_eq!(
            current_live_chat_preview(&private_only),
            (String::new(), String::new())
        );
        let local = private_only
            .get_chat_channels()
            .iter()
            .find(|row| row.id == "cli")
            .unwrap();
        assert!(local.last_message.is_empty());
        assert!(local.last_timestamp.is_empty());
    }

    #[test]
    fn consent_bound_skill_selection_is_captured_by_value_and_refreshes_by_id() {
        let mut state = SkillPickerState::default();
        state.refresh(vec![
            "Automatic".to_string(),
            "alpha".to_string(),
            "beta".to_string(),
        ]);
        let selected = state.select(2).unwrap();
        let captured_for_consent = selected.selected_id.clone();

        let (reordered, removed) = state.refresh(vec![
            "Automatic".to_string(),
            "beta".to_string(),
            "alpha".to_string(),
        ]);
        assert!(!removed);
        assert_eq!(reordered.selected_index, 1);
        assert_eq!(reordered.selected_id.as_deref(), Some("beta"));

        state.select(0).unwrap();
        assert_eq!(captured_for_consent.as_deref(), Some("beta"));
        assert!(state.snapshot().selected_id.is_none());

        state.select(2).unwrap();
        let (reset, removed) = state.refresh(vec!["Automatic".to_string(), "beta".to_string()]);
        assert!(removed);
        assert_eq!(reset.selected_index, 0);
        assert!(reset.selected_id.is_none());
    }

    #[test]
    fn gui_chat_launch_envelope_binds_stream_and_optional_consent_tokens() {
        let consent = zeroize::Zeroizing::new(b"token.0123456789abcdef".to_vec());
        let encoded =
            encode_gui_chat_launch_envelope("0123456789abcdef0123456789abcdef", Some(&consent))
                .unwrap();
        let value: serde_json::Value = serde_json::from_slice(encoded.as_slice()).unwrap();
        assert_eq!(value["version"], 1);
        assert_eq!(value["launch"], "commit");
        assert_eq!(
            value["stream_control_token"],
            "0123456789abcdef0123456789abcdef"
        );
        assert_eq!(value["consent_token"], "token.0123456789abcdef");

        let encoded =
            encode_gui_chat_launch_envelope("fedcba9876543210fedcba9876543210", None).unwrap();
        let value: serde_json::Value = serde_json::from_slice(encoded.as_slice()).unwrap();
        assert!(value["consent_token"].is_null());
    }

    #[test]
    fn private_chat_consent_token_can_only_be_taken_by_its_request() {
        let first = ChatStreamRequestId::parse_wire("41").unwrap();
        let second = ChatStreamRequestId::parse_wire("42").unwrap();
        let slot = std::sync::Mutex::new(None);
        bind_chat_consent_token(
            &slot,
            first,
            Some(zeroize::Zeroizing::new(b"secret".to_vec())),
        )
        .unwrap();

        assert!(take_chat_consent_token(&slot, second).is_err());
        let token = take_chat_consent_token(&slot, first)
            .unwrap()
            .expect("request-bound consent token");
        assert_eq!(token.as_slice(), b"secret");
        assert!(take_chat_consent_token(&slot, first).unwrap().is_none());
    }

    #[test]
    fn chat_sidebar_treats_only_local_cli_as_a_bound_route() {
        let channels = vec![
            panel_logic::ChannelStatus {
                name: "telegram".to_string(),
                status: "connected".to_string(),
                configured: true,
                detail: "healthy".to_string(),
                setup_secret_mask: [false; 6],
            },
            panel_logic::ChannelStatus {
                name: "whatsapp".to_string(),
                status: "unconfigured".to_string(),
                configured: false,
                detail: "missing credentials".to_string(),
                setup_secret_mask: [false; 6],
            },
        ];

        let rows = build_chat_sidebar_channels(&channels);
        assert_eq!(rows.len(), 2, "unconfigured channels are not chat rows");
        assert_eq!(rows[0].id.as_str(), "cli");
        assert!(rows[0].route_bound);
        assert!(!rows[0].configurable);
        assert_eq!(rows[1].id.as_str(), "telegram");
        assert!(!rows[1].route_bound);
        assert!(rows[1].configurable);
        assert!(rows[1].detail.contains("routing not available"));
        assert_eq!(rows.iter().filter(|row| row.route_bound).count(), 1);
    }

    #[test]
    fn lf_p1_20_send_before_channel_probe_hydrates_live_preview() {
        let mut rows = build_chat_sidebar_channels(&[]);
        let live_preview = panel_logic::latest_chat_sidebar_preview([
            ("partial assistant chunk", "10:01", true),
            ("early operator send", "10:00", false),
        ]);
        hydrate_local_chat_sidebar_preview(
            &mut rows,
            Some(live_preview),
            Some(("older retained reply".into(), "09:00".into())),
        );
        assert_eq!(rows[0].last_message.as_str(), "early operator send");
        assert_eq!(rows[0].last_timestamp.as_str(), "10:00");

        let mut cold_rows = build_chat_sidebar_channels(&[]);
        hydrate_local_chat_sidebar_preview(
            &mut cold_rows,
            None,
            Some(("retained fallback".into(), "09:00".into())),
        );
        assert_eq!(cold_rows[0].last_message.as_str(), "retained fallback");

        rows[0].last_message = "newer completed reply".into();
        hydrate_local_chat_sidebar_preview(
            &mut rows,
            Some(("stale recompute".into(), "10:01".into())),
            None,
        );
        assert_eq!(rows[0].last_message.as_str(), "newer completed reply");
    }

    #[test]
    fn lf_p1_20_session_load_generation_rejects_a_after_b_and_return_to_live() {
        let a_revision = 1;
        assert!(session_load_is_current(
            1,
            a_revision,
            true,
            "session-a",
            "session-a"
        ));

        let b_revision = 2;
        assert!(!session_load_is_current(
            b_revision,
            a_revision,
            true,
            "session-b",
            "session-a"
        ));
        assert!(session_load_is_current(
            b_revision,
            b_revision,
            true,
            "session-b",
            "session-b"
        ));

        let live_revision = 3;
        for (revision, session) in [(a_revision, "session-a"), (b_revision, "session-b")] {
            assert!(!session_load_is_current(
                live_revision,
                revision,
                false,
                "",
                session
            ));
        }

        // A real/imported session id named `live` remains historical because
        // mode is typed separately; the identifier cannot grant mutations.
        assert!(session_load_is_current(4, 4, true, "live", "live"));
        assert!(!session_load_is_current(5, 4, false, "", "live"));
    }

    #[test]
    fn lf_p1_20_chat_sidebar_session_selection_is_readonly_and_fully_wired() {
        let rust_source = include_str!("main.rs");
        let shell_source = include_str!("../ui/main.slint");
        let chat_source = include_str!("../ui/chat.slint");
        assert!(!rust_source.contains(concat!("on_chat_channel", "_switched")));
        assert!(!shell_source.contains("callback chat-channel-switched"));
        assert!(!chat_source.contains("callback channel-switched"));

        for contract in [
            "in property <string> active-session-id: \"\";",
            "in property <bool> history-active: false;",
            "callback live-session-selected();",
            "callback session-selected(string);",
            "last-message: ch.last-message != \"\" ? ch.last-message : ch.detail;",
            "last-timestamp: ch.last-timestamp;",
            "root.session-selected(s.id)",
            "root.live-session-selected()",
            "mutation-actions-enabled: !root.history-active && !root.send-in-flight;",
            "if !root.history-active && root.link-chips.length > 0",
            "if !root.history-active: Composer {",
            "if root.history-active: Rectangle {",
            "if root.send-in-flight: HorizontalLayout {",
            "clicked => { root.stop-stream-clicked(); }",
            "root.send-enabled && root.draft != \"\" && !root.send-in-flight",
            "Return to Local CLI to compose, attach, retry or edit.",
        ] {
            assert!(
                chat_source.contains(contract),
                "missing ChatView contract: {contract}"
            );
        }
        for contract in [
            "in property <string> chat-active-session-id: \"\";",
            "in property <bool> chat-history-active: false;",
            "callback chat-live-session-selected();",
            "callback chat-session-selected(string);",
            "active-session-id: root.chat-active-session-id;",
            "history-active: root.chat-history-active;",
        ] {
            assert!(
                shell_source.contains(contract),
                "missing shell contract: {contract}"
            );
        }
        for contract in [
            "window.on_chat_live_session_selected",
            "window.on_chat_session_selected",
            "load_session_messages",
            "chat_session_revision",
            "CHAT_HISTORY_REFRESH_REVISION",
            "Historical transcripts are read-only.",
        ] {
            assert!(
                rust_source.contains(contract),
                "missing Rust wiring: {contract}"
            );
        }

        assert!(chat_source.contains("active: ch.route-bound && !root.history-active;"));
        assert!(chat_source.contains("accessible-enabled: root.route-bound;"));
        assert!(
            chat_source
                .matches("enabled: !root.send-in-flight;")
                .count()
                >= 5,
            "typing, focus, quick commands and attachment mutations must be locked to the accepted request snapshot"
        );
        let compact_chat = chat_source.split_whitespace().collect::<String>();
        assert!(compact_chat.contains("if(root.send-in-flight){returnaccept;}"));
        assert_eq!(
            rust_source
                .matches(concat!(
                    "Wait for the active reply or stop it before ",
                    "changing attachments."
                ))
                .count(),
            3,
            "drop, picker and remove callbacks must all enforce the request snapshot"
        );
        for accessibility_contract in [
            "accessible-role: progress-indicator;",
            "accessible-label: \"Response status\";",
            "accessible-value: root.stream-label;",
            "Theme.animation-mode != 2 || mod(animation-tick(), 1060ms)",
            "&& Theme.animation-mode == 2",
            "accessible-action-default => {",
            "forward-focus: key-focus;",
            "key-focus := FocusScope {",
            "forward-focus: session-focus;",
            "session-focus := FocusScope {",
            "Current read-only history session.",
            "event.text == \"\\n\" || event.text == \" \"",
        ] {
            assert!(
                chat_source.contains(accessibility_contract),
                "missing accessible session-row contract: {accessibility_contract}"
            );
        }
        assert!(!chat_source.contains("opacity: root.active-session-id == s.id"));
        assert!(!chat_source.contains("root.any-active && !root.active"));
        assert!(!chat_source.contains("font-size: 10px;"));
        assert!(
            chat_source
                .contains("height: max(64px, row-body.preferred-height + Theme.space-tight * 2);")
        );
        assert!(
            chat_source.contains(
                "height: max(62px, session-body.preferred-height + Theme.space-tight * 2);"
            )
        );
        assert!(chat_source.contains("Read-only history · select a session to inspect"));
        assert!(chat_source.contains("chat routing not available"));
        assert!(
            rust_source.contains("cmd.arg(\"chat\").arg(\"--stream\")"),
            "truthful sidebar must not remove the working local CLI chat"
        );
    }

    #[test]
    fn strip_stream_sentinel_multiparagraph_preserved_before_sentinel() {
        // Internal blank lines (paragraph breaks) survive — only the
        // trailing blank+sentinel is removed, so segmentation still works.
        let raw = "Para one.\n\nPara two.\n\n{\"neoth_stream\":\"done\",\"count\":3}";
        let (txt, done) = strip_stream_sentinel(raw);
        assert_eq!(txt, "Para one.\n\nPara two.");
        assert!(done);
        // And it segments into two bubbles downstream.
        assert_eq!(segment_reply_into_bubbles(&txt).len(), 2);
    }

    #[test]
    fn visual_separator_matrix() {
        assert!(is_visual_separator_only("---"));
        assert!(is_visual_separator_only("***"));
        assert!(is_visual_separator_only("___"));
        assert!(is_visual_separator_only("- - -")); // markdown spaced hr
        assert!(!is_visual_separator_only("--")); // too short
        assert!(!is_visual_separator_only("-*-")); // mixed glyphs
        assert!(!is_visual_separator_only("text")); // real content
    }

    #[test]
    fn shape_chat_output_happy_path_returns_trimmed_stdout() {
        // Reply with trailing newlines (every `neothd chat` adds one);
        // shape_chat_output trims the tail but preserves internal
        // newlines for code blocks / lists.
        let result = shape_chat_output(true, b"The answer is 42.\nLine two.\n\n", b"", Some(0));
        assert_eq!(result, Ok("The answer is 42.\nLine two.".to_string()));
    }

    #[test]
    fn shape_chat_output_empty_stdout_is_error_with_doctor_hint() {
        let result = shape_chat_output(true, b"", b"", Some(0));
        match result {
            Err(msg) => {
                assert!(msg.contains("empty reply"));
                assert!(msg.contains("neoth doctor"));
            }
            Ok(_) => panic!("empty stdout must error"),
        }
    }

    #[test]
    fn shape_chat_output_nonzero_with_stderr_surfaces_diagnostic() {
        let result = shape_chat_output(
            false,
            b"",
            b"Error: no provider configured. Run `neoth init` first.",
            Some(1),
        );
        match result {
            Err(msg) => {
                assert!(msg.contains("exit 1"));
                assert!(msg.contains("no provider configured"));
                assert!(msg.contains("Chat failed"));
            }
            Ok(_) => panic!("non-zero exit must error"),
        }
    }

    #[test]
    fn shape_chat_output_nonzero_no_stderr_points_at_terminal() {
        let result = shape_chat_output(false, b"", b"", Some(137));
        match result {
            Err(msg) => {
                assert!(msg.contains("exit 137"));
                assert!(msg.contains("no diagnostic"));
                assert!(msg.contains("terminal"));
            }
            Ok(_) => panic!("non-zero exit must error"),
        }
    }

    #[test]
    fn shape_chat_output_truncates_long_stderr_to_600_chars() {
        let long_stderr = "X".repeat(5000);
        let result = shape_chat_output(false, b"", long_stderr.as_bytes(), Some(1));
        match result {
            Err(msg) => {
                // Total error message includes prefix + 599 chars of
                // stderr + ellipsis. Bound at ~650 to allow prefix.
                assert!(msg.len() < 700, "msg too long: {} chars", msg.len());
                assert!(msg.contains("…"));
            }
            Ok(_) => panic!("non-zero must error"),
        }
    }

    #[test]
    fn shape_chat_output_handles_utf8_multibyte_stderr_truncation() {
        // 1000 em-dashes (3 bytes each in utf-8) — truncation must
        // not split a multi-byte char.
        let long_stderr = "—".repeat(1000);
        let result = shape_chat_output(false, b"", long_stderr.as_bytes(), Some(2));
        match result {
            Err(msg) => {
                // The message must be valid utf-8 (would panic on the
                // older `&str[..600]` byte-slice path).
                assert!(msg.is_ascii() || msg.chars().count() > 100);
                assert!(msg.contains("…"));
            }
            Ok(_) => panic!("non-zero must error"),
        }
    }

    #[test]
    fn shape_chat_output_handles_none_exit_code() {
        // Process killed by signal: status.code() returns None.
        let result = shape_chat_output(false, b"", b"killed", None);
        match result {
            Err(msg) => assert!(msg.contains("exit ?")),
            Ok(_) => panic!("killed must error"),
        }
    }

    #[test]
    fn binary_missing_message_carries_install_pointer() {
        // Operator-readable diagnostic for the no-binary path. Pin
        // the install pointers so a future refactor doesn't drop them.
        assert!(BINARY_MISSING_MESSAGE.contains("public `neoth`"));
        assert!(BINARY_MISSING_MESSAGE.contains("compatibility launcher"));
        assert!(
            BINARY_MISSING_MESSAGE.contains("release tarball")
                || BINARY_MISSING_MESSAGE.contains("cargo install")
        );
    }

    #[test]
    fn main_and_buddy_share_contained_process_and_shutdown_contract() {
        let source = include_str!("main.rs");
        let spawn_contract = concat!("OwnedChatChild::", "spawn(request_id");
        assert_eq!(
            source.matches(spawn_contract).count(),
            2,
            "Main and Buddy must both use the process-tree supervisor"
        );
        let lease_contract = concat!("let _worker_lease", " = worker_lease;");
        assert_eq!(
            source.matches(lease_contract).count(),
            2,
            "both dispatch-claimed workers must acknowledge the quit barrier"
        );
        let run = source.find("let run_result = window.run();").unwrap();
        let shutdown = source
            .find("let chat_shutdown_result = shutdown_gui_chat_runtime(")
            .unwrap();
        assert!(
            shutdown > run,
            "process-tree cleanup must run after the event loop exits"
        );
        let shutdown_body = source
            .split("fn shutdown_gui_chat_runtime(")
            .nth(1)
            .unwrap()
            .split("fn bind_chat_consent_token(")
            .next()
            .unwrap();
        for contract in [
            "worker_barrier.begin_shutdown();",
            "gate.cancel_before_commit();",
            "kill_owned_chat_child(child, request_id)",
            "wait_for_owned_chat_child_exit(child, request_id)",
            "worker_barrier.wait_empty",
            "pending.body.zeroize();",
            "model.zeroize();",
            "watchdog_retry",
            "watchdog_input",
        ] {
            assert!(
                shutdown_body.contains(contract),
                "missing shutdown contract: {contract}"
            );
        }
    }

