    #[test]
    fn skill_inventory_rejects_partial_or_ambiguous_snapshots() {
        let dir = TempDir::new().unwrap();
        let skills_dir = dir.path().join("skills");
        let duplicate = vec![
            neothd::skills::loader::SkillInventoryRow::Healthy {
                manifest: Box::new(test_skill_manifest("alpha", "one")),
                origin: neothd::skills::loader::SkillInventoryOrigin::Bundled,
                path: None,
                runtime_state:
                    neothd::skills::loader::SkillInventoryRuntimeState::TrustedBundledActive,
                package_generation_sha256: None,
                install_incarnation: None,
                install_terminal_receipt_sha256: None,
            },
            neothd::skills::loader::SkillInventoryRow::Healthy {
                manifest: Box::new(test_skill_manifest("alpha", "two")),
                origin: neothd::skills::loader::SkillInventoryOrigin::User,
                path: Some(skills_dir.join("alpha")),
                runtime_state: neothd::skills::loader::SkillInventoryRuntimeState::InstalledActive,
                package_generation_sha256: Some("a".repeat(64)),
                install_incarnation: Some(1),
                install_terminal_receipt_sha256: Some("b".repeat(64)),
            },
        ];
        assert!(
            skill_summaries_from_inventory_at(duplicate, &skills_dir)
                .unwrap_err()
                .contains("duplicate id")
        );

        let mut empty_manifest = test_skill_manifest("alpha", "placeholder");
        empty_manifest.description = "  ".to_string();
        let empty_description = vec![neothd::skills::loader::SkillInventoryRow::Healthy {
            manifest: Box::new(empty_manifest),
            origin: neothd::skills::loader::SkillInventoryOrigin::Bundled,
            path: None,
            runtime_state: neothd::skills::loader::SkillInventoryRuntimeState::TrustedBundledActive,
            package_generation_sha256: None,
            install_incarnation: None,
            install_terminal_receipt_sha256: None,
        }];
        assert!(
            skill_summaries_from_inventory_at(empty_description, &skills_dir)
                .unwrap_err()
                .contains("empty description")
        );

        let wrong_path = vec![neothd::skills::loader::SkillInventoryRow::Healthy {
            manifest: Box::new(test_skill_manifest("alpha", "Alpha skill")),
            origin: neothd::skills::loader::SkillInventoryOrigin::User,
            path: Some(skills_dir.join("other")),
            runtime_state: neothd::skills::loader::SkillInventoryRuntimeState::Disabled,
            package_generation_sha256: Some("a".repeat(64)),
            install_incarnation: None,
            install_terminal_receipt_sha256: None,
        }];
        assert!(
            skill_summaries_from_inventory_at(wrong_path, &skills_dir)
                .unwrap_err()
                .contains("invalid origin/path binding")
        );

        for (origin, runtime_state) in [
            (
                neothd::skills::loader::SkillInventoryOrigin::Bundled,
                neothd::skills::loader::SkillInventoryRuntimeState::InstalledActive,
            ),
            (
                neothd::skills::loader::SkillInventoryOrigin::Bundled,
                neothd::skills::loader::SkillInventoryRuntimeState::BundledFallbackActive,
            ),
            (
                neothd::skills::loader::SkillInventoryOrigin::User,
                neothd::skills::loader::SkillInventoryRuntimeState::TrustedBundledActive,
            ),
        ] {
            let user_origin = origin == neothd::skills::loader::SkillInventoryOrigin::User;
            let impossible = vec![neothd::skills::loader::SkillInventoryRow::Healthy {
                manifest: Box::new(test_skill_manifest("impossible", "Impossible binding")),
                origin,
                path: user_origin.then(|| skills_dir.join("impossible")),
                runtime_state,
                package_generation_sha256: user_origin.then(|| "a".repeat(64)),
                install_incarnation: None,
                install_terminal_receipt_sha256: None,
            }];
            assert!(
                skill_summaries_from_inventory_at(impossible, &skills_dir)
                    .unwrap_err()
                    .contains("invalid origin/runtime binding")
            );
        }

        for runtime_state in [
            neothd::skills::loader::SkillInventoryRuntimeState::TrustedBundledActive,
            neothd::skills::loader::SkillInventoryRuntimeState::InstalledActive,
        ] {
            let impossible = vec![neothd::skills::loader::SkillInventoryRow::Broken {
                id: "broken-impossible".to_string(),
                error: "invalid runtime binding".to_string(),
                path: skills_dir.join("broken-impossible"),
                repairability: neothd::skills::installer::SkillRepairability::RemoveOnly,
                runtime_state,
                package_generation_sha256: None,
                install_incarnation: None,
                install_terminal_receipt_sha256: None,
            }];
            assert!(
                skill_summaries_from_inventory_at(impossible, &skills_dir)
                    .unwrap_err()
                    .contains("invalid runtime binding")
            );
        }
    }

    #[test]
    fn broken_inventory_supports_repair_and_remove_while_bundled_uninstall_is_blocked() {
        let dir = TempDir::new().unwrap();
        let skills_dir = dir.path().join("skills");
        let inventory = vec![
            neothd::skills::loader::SkillInventoryRow::Healthy {
                manifest: Box::new(test_skill_manifest("bundled", "Bundled skill")),
                origin: neothd::skills::loader::SkillInventoryOrigin::Bundled,
                path: None,
                runtime_state:
                    neothd::skills::loader::SkillInventoryRuntimeState::TrustedBundledActive,
                package_generation_sha256: None,
                install_incarnation: None,
                install_terminal_receipt_sha256: None,
            },
            neothd::skills::loader::SkillInventoryRow::Broken {
                id: "broken-skill".to_string(),
                error: "missing skill.yaml".to_string(),
                path: skills_dir.join("broken-skill"),
                repairability: neothd::skills::installer::SkillRepairability::ManifestReplaceable,
                runtime_state: neothd::skills::loader::SkillInventoryRuntimeState::Disabled,
                package_generation_sha256: None,
                install_incarnation: None,
                install_terminal_receipt_sha256: None,
            },
            neothd::skills::loader::SkillInventoryRow::Broken {
                id: "broken\nskill".to_string(),
                error: "bad\nmanifest".to_string(),
                path: skills_dir.join("broken\nskill"),
                repairability: neothd::skills::installer::SkillRepairability::RemoveOnly,
                runtime_state: neothd::skills::loader::SkillInventoryRuntimeState::Disabled,
                package_generation_sha256: None,
                install_incarnation: None,
                install_terminal_receipt_sha256: None,
            },
        ];
        let summaries = skill_summaries_from_inventory_at(inventory, &skills_dir).unwrap();

        let repairable = summaries
            .iter()
            .find(|skill| skill.operation_id == "broken-skill")
            .unwrap();
        assert!(repairable.broken);
        assert!(repairable.repairable);
        assert_eq!(repairable.origin, "user");
        assert!(skill_exists_in_inventory(&summaries, "broken-skill"));
        assert!(verify_skill_uninstall_target(&summaries, "broken-skill").is_ok());

        let diagnostic = summaries
            .iter()
            .find(|skill| skill.operation_id == "broken\nskill")
            .unwrap();
        assert_eq!(diagnostic.id, "broken�skill");
        assert_eq!(diagnostic.error, "bad�manifest");
        assert!(!diagnostic.repairable);
        assert!(verify_skill_uninstall_target(&summaries, "broken\nskill").is_ok());

        assert!(verify_skill_uninstall_target(&summaries, "bundled").is_err());
        assert!(verify_skill_uninstall_target(&summaries, "missing").is_err());
    }

    #[test]
    fn declined_skill_uninstall_is_not_dispatched_or_refreshed_as_a_failure() {
        let dispatched = std::cell::Cell::new(false);
        let outcome = dispatch_confirmed_skill_uninstall(false, || {
            dispatched.set(true);
            "mutated"
        });
        assert_eq!(outcome, SkillUninstallDispatch::Cancelled);
        assert!(!dispatched.get());

        let outcome = dispatch_confirmed_skill_uninstall(true, || {
            dispatched.set(true);
            "mutated"
        });
        assert_eq!(outcome, SkillUninstallDispatch::Executed("mutated"));
        assert!(dispatched.get());

        let source = include_str!("main.rs");
        let callback = source
            .split("window.on_skill_uninstall(move |id| {")
            .nth(1)
            .expect("skill uninstall callback")
            .split("// ── Skills: create via non-interactive wizard")
            .next()
            .expect("skill uninstall callback end");
        let cancelled = callback
            .find("SkillUninstallDispatch::Cancelled")
            .expect("explicit cancellation arm");
        let executed = callback
            .find("SkillUninstallDispatch::Executed")
            .expect("executed mutation arm");
        let refresh = callback
            .find("let skills = fetch_skills();")
            .expect("post-mutation inventory refresh");
        let cancellation_arm = &callback[cancelled..executed];
        assert!(cancelled < executed && executed < refresh);
        assert!(cancellation_arm.contains("\"info\""));
        assert!(cancellation_arm.contains("return;"));
        assert!(!cancellation_arm.contains("Skill uninstall failed"));
    }

