    #[test]
    fn interface_preference_label_covers_all_show_states() {
        // Pinned against cli/interface.rs render(): `preferred` is null
        // until the one-time choice, then "gui"/"cli".
        assert_eq!(
            interface_preference_label(true, Some("gui")),
            "GUI (this app)"
        );
        assert_eq!(
            interface_preference_label(true, Some("cli")),
            "CLI (terminal)"
        );
        assert_eq!(interface_preference_label(false, None), "not chosen yet");
        // chosen:true with a null/foreign value must not read as a valid choice.
        assert_eq!(interface_preference_label(true, None), "not chosen yet");
        assert_eq!(
            interface_preference_label(true, Some("web")),
            "unknown (web)"
        );
        // Decode contract: the snapshot tolerates a null preferred field.
        let snap: InterfaceShowSnapshot = serde_json::from_str(
            r#"{"chosen":false,"preferred":null,"changed":false,"path":"C:/x/interface.json"}"#,
        )
        .expect("decode interface show snapshot");
        assert!(!snap.chosen);
        assert!(snap.preferred.is_none());
    }

    #[test]
    fn consent_binding_accepts_every_core_endpoint_bound_provider() {
        for provider in [
            "local_ollama",
            "openai_api",
            "openai_compat",
            "aws_bedrock",
            "azure_openai",
        ] {
            let origin = format!("https://{provider}.example");
            let rows = panel_logic::parse_consent_rows(
                &serde_json::json!([{
                    "provider": provider,
                    "consent_required": true,
                    "current_route_granted": false,
                    "configured_endpoint_origins": [origin.clone()],
                    "granted_endpoint_origins": [],
                    "stale_endpoint_origins": [],
                    "granted_unix_ts": null,
                    "grantable": true,
                    "revokable": false,
                    "status": "pending",
                    "error": null,
                    "endpoint_origins": [],
                    "granted": false
                }])
                .to_string(),
            )
            .unwrap();
            let binding = gui_action::VerifiedConsentMutationBinding {
                config_sha256: "a".repeat(64),
                route_set_sha256: "b".repeat(64),
                required_routes: vec![gui_action::ConsentRouteBinding {
                    provider: provider.to_string(),
                    endpoint_origin: Some(origin.clone()),
                }],
                readback: vec![gui_action::ConsentRouteReadback {
                    provider: provider.to_string(),
                    endpoint_origin: Some(origin),
                    granted: false,
                    marker_authority_persisted: false,
                }],
            };
            assert!(
                verify_consent_row_binding(&rows[0], &binding).is_ok(),
                "{provider} must remain grantable through the GUI binding"
            );
        }
    }

    #[test]
    fn autonomy_and_consent_mutations_route_through_typed_receipts() {
        // Tier-1 receipt promotion (2026-07-20): every autonomy/consent
        // mutation must go through the typed helpers (ack verify + readback),
        // never a bare exit-code spawn. Patterns are concat-split so this
        // test's own source never matches itself.
        let source = include_str!("main.rs");
        // No handler may hand-roll bare autonomy/consent subprocess
        // mutations again (the forbidden `.arg(...)` spellings below).
        let bare_autonomy = concat!(".arg(\"auto", "nomy\")");
        let bare_consent = concat!(".arg(\"con", "sent\")");
        assert!(
            !source.contains(bare_autonomy),
            "autonomy mutation regressed to a bare subprocess spawn"
        );
        assert!(
            !source.contains(bare_consent),
            "consent mutation regressed to a bare subprocess spawn"
        );
        // The one FULL-AUTO ceremony: definition + settings radio + chat
        // consent strip + FULL-AUTO switch. A dropped call site means a
        // surface regressed to a weaker gate; a new one must share the helper.
        let ceremony = concat!("enable_full_auto_", "verified()");
        assert_eq!(
            source.matches(ceremony).count(),
            4,
            "expected the shared FULL-AUTO ceremony at exactly its 3 call sites + definition"
        );
        // Verified GATED switch: definition + chat strip + FULL-AUTO switch-back.
        let gated = concat!("switch_to_gated_", "verified()");
        assert_eq!(
            source.matches(gated).count(),
            3,
            "expected the verified GATED switch at exactly its 2 call sites + definition"
        );
        // Single mint boundary: definition + ceremony + full-auto preset apply.
        let mint = concat!("mint_fullauto_token_", "verified()");
        assert_eq!(
            source.matches(mint).count(),
            3,
            "expected the typed token mint at exactly its 2 call sites + definition"
        );
    }

